/* ⛔ GENERATED by kit/build.mjs from i18n/id.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["id"] = {"hero.headline":"<span class=\"hl-muted\">Satu pencarian.</span> <span class=\"hl-bright\">Setiap sumber. Setiap OS.</span>","hero.sub":"Temukan berkas apa pun sambil mengetik: berdasarkan namanya, kata-kata di dalamnya, bunyinya, isi header-nya, atau nama yang hanya mirip dengan yang Anda ingat.","hero.chipApp":"Aplikasi desktop","hero.chipCli":"Baris perintah","hero.chipLanguages":"18 bahasa","what.title":"Apa ini","what.p1":"Setiap sistem operasi punya kotak pencarian, dan masing-masing punya kekurangannya sendiri. Everything dari voidtools membuat pencarian nama berkas menjadi instan di Windows bertahun-tahun lalu, dan ia tetap hanya ada di Windows.","what.p2":"Freally Sourcerer adalah pencarian semacam itu untuk Windows, macOS, dan Linux. Ia menyimpan satu indeks untuk disk-disk Anda, yang terus diperbarui oleh catatan perubahan berkas milik setiap sistem — change journal NTFS di Windows, FSEvents di macOS, inotify dan fanotify di Linux — sehingga berkas baru dan berkas yang diganti namanya ditemukan tanpa pemindaian ulang.","what.p3":"Lalu ia membaca lebih jauh dari sekadar nama. Satu kueri dapat menanyakan nama, teks di dalam dokumen, kenyaringan terukur sebuah berkas audio, apa yang dikatakan header sebuah gambar atau program tentang dirinya sendiri, dan nama-nama yang hanya mirip dengan yang Anda ketik.","features.title":"Apa isinya","features.filename.title":"Nama berkas, seketika","features.filename.body":"Substring, wildcard, ekspresi reguler, AND, OR, dan NOT, serta pengubah milik Everything untuk ukuran, tanggal, ekstensi, dan path, dijawab dari indeks sambil Anda mengetik.","features.content.title":"Teks di dalam berkas","features.content.body":"Pencarian teks penuh di berkas PDF, Word, Excel, dan PowerPoint, Markdown, kode sumber dalam 32 bahasa, JSON, CSV, dan YAML, email, serta di dalam arsip tanpa membongkarnya.","features.audio.title":"Audio berdasarkan bunyinya","features.audio.body":"Temukan audio berdasarkan kenyaringan terukur dalam LUFS, true peak, keheningan, rentang dinamis, durasi, codec, dan sample rate — bukan berdasarkan tag yang diketik seseorang.","features.properties.title":"Apa yang dikatakan berkas tentang dirinya","features.properties.body":"Tujuh puluh dua properti yang dibaca dari header berkas: ukuran gambar dan kamera, codec dan durasi video, penulis dan jumlah halaman dokumen, arsitektur dan tanda tangan program, dan lainnya.","features.similar.title":"Nama yang hanya mirip","features.similar.body":"Lensa kemiripan menemukan nama yang dekat dengan yang Anda ketik — salah ketik, nomor versi, prefiks yang berbeda — dan pencarian yang tidak menemukan apa pun menawarkan nama nyata yang paling dekat.","features.everything.title":"Langsung terasa akrab jika Anda datang dari Everything","features.everything.body":"Sintaks pencarian Everything juga berfungsi di sini, dan daftar berkasnya dapat dibuka dan diekspor, sehingga katalog sebuah drive dapat berpindah di antara keduanya.","features.results.title":"Bertindak atas apa yang Anda temukan","features.results.body":"Buka, tampilkan di folder, salin, ganti nama seluruh himpunan hasil dengan pratinjau lalu urungkan, temukan duplikat dan folder kosong, serta jalankan perintah buatan Anda sendiri.","features.platforms.title":"Satu aplikasi, tiga sistem","features.platforms.body":"Aplikasi, bahasa kueri, dan indeks yang sama di Windows, macOS, dan Linux, baris perintah untuk skrip, dan delapan belas bahasa.","ladder.title":"Jalan menuju 1.0","ladder.intro":"Satu baris per versi. Versi setelah 0.23 adalah rencana, sesuai urutan pembangunannya.","ladder.rung.v0.19.84":"Build publik pertama: pencarian nama berkas yang terus diperbarui oleh change journal milik setiap sistem, bahasa kueri, aplikasi beserta pengaturannya, dalam delapan belas bahasa di Windows, macOS, dan Linux.","ladder.rung.v0.21.0":"Fitur wajib, bagian 1 dari 3: duplikat, folder kosong, daftar berkas Everything, dan setiap tindakan pada sebuah hasil dari menu klik kanannya.","ladder.rung.v0.22.0":"Fitur wajib, bagian 2 dari 3: indeks mengikuti disk secara langsung, Kesehatan Indeks, ganti nama massal dengan urungkan, drive yang dicabut tetap dapat dicari, dan baris perintah untuk skrip.","ladder.rung.v0.23.0":"Fitur wajib, bagian 3 dari 3, dan rilis stabil: mode portabel, audio dan video di pratinjau, Lihat Cepat, pembuat ekspresi reguler, dan laporan tentang folder yang tidak dapat dilihat pencarian. Rilis perbaikannya, 0.23.2, adalah versi saat ini.","ladder.rung.v0.24.0":"Lensa properti untuk gambar dan video: dimensi, data kamera, codec, dan durasi, dapat dicari dan ditampilkan sebagai kolom.","ladder.rung.v0.25.0":"Lensa properti untuk dokumen, program, dan paket: penulis dan jumlah halaman, arsitektur dan tanda tangan, installer, shortcut, arsip, font, email, dan basis data.","ladder.rung.v0.26.0":"Tag musik, dan lebih banyak lagi untuk orang yang bekerja dengan audio.","ladder.rung.v0.27.0":"Duplikat dan pembersihan disk.","ladder.rung.v0.28.0":"Tag, catatan, dan koleksi untuk berkas Anda.","ladder.rung.v0.29.0":"Pencarian tingkat lanjut: makro, snapshot, pemantau, dan hash berkas.","ladder.rung.v0.30.0":"Tampilan dan jendela.","ladder.rung.v0.31.0":"Peluncur, dan integrasi yang lebih erat dengan sistem operasi Anda.","ladder.rung.v0.32.0":"Baris perintah, antarmuka terminal, dan otomatisasi.","ladder.rung.v0.33.0":"Pencarian di seluruh jaringan lokal Anda, katalog, dan alat indeks untuk pengguna mahir.","ladder.rung.v1.0.0":"Lensa kode dan pengetahuan, serta rilisnya: versi 1.0.","ladder.note":"Versi yang selesai sudah dibangun dan ditandai (tag). Itu bukan unduhan: tidak ada satu pun, dan tidak akan ada sampai 1.0.0.","honest.title":"Hal-hal yang oleh kebanyakan situs diletakkan di paling bawah","honest.firstIndex.title":"Indeks pertama butuh waktu lebih lama di macOS dan Linux","honest.firstIndex.body":"Di Windows, change journal NTFS memungkinkan seluruh volume diindeks dengan cepat. macOS dan Linux tidak memiliki yang seperti itu, sehingga indeks pertama di sana menelusuri setiap folder: hitungan menit, bukan detik, pada disk yang besar. Setelah itu, peristiwa perubahan milik sistem itu sendiri yang menjaganya tetap mutakhir.","honest.network.title":"Apa yang tersambung ke internet, dan apa yang tidak pernah","honest.network.body":"Tidak ada telemetri, dan tidak ada apa pun tentang berkas atau pencarian Anda yang dikirim ke mana pun. Atas inisiatifnya sendiri, aplikasi hanya tersambung ke internet untuk satu hal: menanyakan apakah ada versi yang lebih baru, sekali sehari kecuali Anda mengubahnya, dan Anda dapat mematikannya. Laporan bug hanya dikirim saat Anda memilih untuk mengirimnya, setelah Anda melihat isinya.","honest.unreadable.title":"Ia memberi tahu apa yang tidak dapat dilihatnya","honest.unreadable.body":"Folder yang tidak dapat dibaca tampak sama persis dengan folder kosong. Sourcerer mencantumkan folder yang terpaksa dilewatinya, beserta alasan dan cara memperbaikinya untuk sistem Anda, alih-alih diam-diam mengembalikan hasil yang lebih sedikit.","honest.lenses.title":"Dua dari lima lensa belum tersambung","honest.lenses.body":"Lensa konten, yang membaca teks di dalam berkas, dan lensa kemiripan, yang menemukan nama yang hanya mirip, sudah dibangun tetapi belum menjawab pencarian. Saat ini lensa nama berkas, audio, dan properti yang menjawabnya. Menyambungkan dua lensa lainnya adalah bagian dari jalan menuju 1.0.","honest.downloads.title":"Tidak ada unduhan sebelum 1.0.0","honest.downloads.body":"Tidak ada beta di halaman ini, tidak ada build pratinjau, tidak ada akses awal. Versi 1.0.0 adalah yang pertama akan ditawarkan situs ini.","site.tagline":"Satu pencarian. Setiap sumber. Setiap OS.","footer.licence":"Berpemilik — Seluruh Hak Dilindungi. © Mike Weaver. Gratis digunakan saat ini; versi mendatang mungkin dijual. Bukan sumber terbuka.","footer.everything":"Everything adalah merek dagang voidtools, disebut di sini hanya untuk perbandingan. Freally Sourcerer tidak berafiliasi dengan voidtools.","featuresPage.lead":"Satu bilah pencarian untuk setiap berkas di Windows, macOS, dan Linux: nama, teks di dalam dokumen, audio berdasarkan bunyinya, apa yang dikatakan header berkas itu sendiri, dan nama yang hanya mirip — dari satu indeks yang menjaga dirinya tetap mutakhir.","featuresPage.version":"Halaman ini menjelaskan Freally Sourcerer versi 1.0: semua yang ada di sini termasuk dalam 1.0, dan tidak ada yang direncanakan untuk setelah 1.0 yang tercantum di sini.","featuresPage.numbers.intro":"Setiap angka dihitung dari kode aplikasi itu sendiri dan catatan perubahannya. Tidak ada yang dibulatkan ke atas.","featuresPage.numbers.lenses":"cara mencari dalam satu indeks: nama berkas, konten, audio, properti, dan nama yang mirip","featuresPage.numbers.properties":"properti berkas yang dibaca dari header","featuresPage.numbers.code":"bahasa pemrograman yang dibaca oleh pencarian kontennya","featuresPage.numbers.audioTypes":"jenis berkas audio dalam filter Audio","featuresPage.numbers.matchModes":"mode pencocokan, dari Cocokkan Huruf Besar/Kecil hingga Abaikan tanda baca","featuresPage.numbers.systems":"sistem operasi: Windows, macOS, dan Linux","featuresPage.numbers.languages":"bahasa","featuresPage.numbers.price":"harga saat ini","featuresPage.free.title":"Gratis saat ini","featuresPage.free.body":"Semua yang dilakukan Sourcerer saat ini gratis, untuk semua orang: tanpa paket berbayar, tanpa langganan, dan tanpa masa uji coba yang berakhir.","featuresPage.cards.title":"Apa yang dilakukan versi 1.0","featuresPage.cards.index.title":"Indeks langsung untuk setiap disk","featuresPage.cards.index.body":"Satu indeks untuk semua drive Anda, yang terus diperbarui oleh aliran perubahan milik setiap sistem — change journal NTFS di Windows, FSEvents di macOS, inotify dan fanotify di Linux — sehingga berkas baru, yang diganti namanya, dan yang dihapus langsung terlihat tanpa pemindaian ulang. Drive yang Anda cabut tetap dapat dicari, dan hasilnya menyebutkan di drive mana berkas itu berada.","featuresPage.cards.names.title":"Nama berkas, seperti cara Everything menemukannya","featuresPage.cards.names.body":"Substring, wildcard, ekspresi reguler, AND, OR, NOT, dan pengelompokan, dengan pengubah dan ejaan Everything untuk ukuran, tanggal, ekstensi, atribut, dan path, serta tujuh mode pencocokan, dari Cocokkan Huruf Besar/Kecil hingga Abaikan tanda baca dan pencocokan nama Tionghoa, Jepang, dan Korea berdasarkan cara bacanya.","featuresPage.cards.content.title":"Teks di dalam berkas","featuresPage.cards.content.body":"Pencarian teks penuh di berkas PDF, Word, Excel, dan PowerPoint, teks polos dan Markdown, kode sumber dalam 32 bahasa, JSON, CSV, dan YAML, email, serta di dalam arsip zip, 7z, dan tar tanpa membongkarnya. Sebuah penampil menelusuri setiap kecocokan dalam konteksnya.","featuresPage.cards.audio.title":"Audio berdasarkan bunyinya","featuresPage.cards.audio.body":"Diukur, bukan diberi tag: kenyaringan dalam LUFS, true peak, keheningan, rentang dinamis, durasi, codec, sample rate, dan kanal. Urutkan berdasarkan kenyaringan atau durasi, dan putar berkas di pratinjau tanpa meninggalkan daftar.","featuresPage.cards.properties.title":"Apa yang dikatakan berkas tentang dirinya","featuresPage.cards.properties.body":"Tujuh puluh dua properti yang dibaca dari header berkas dan dicari seperti pengubah lainnya: ukuran gambar dan data kamera, codec dan durasi video, penulis dan jumlah halaman dokumen, arsitektur dan tanda tangan program, versi installer, target shortcut, isi arsip, font, header email, dan tabel basis data. Masing-masing dapat dijadikan kolom.","featuresPage.cards.similar.title":"Nama yang hanya mirip","featuresPage.cards.similar.body":"Lensa kemiripan menemukan nama yang dekat dengan yang Anda ketik — salah ketik, nomor versi, prefiks yang berbeda — dan pencarian yang tidak menemukan apa pun menawarkan nama nyata yang paling dekat sebagai koreksi sekali klik.","featuresPage.cards.results.title":"Semua yang Anda lakukan dengan sebuah hasil","featuresPage.cards.results.body":"Buka, tampilkan di folder, Buka dengan, salin path, nama, isi, atau berkas itu sendiri, buka terminal di sana, dan jalankan perintah yang Anda tentukan sendiri. Spasi membuka Lihat Cepat, audio dan video diputar di pratinjau, dan jumlah hasil membuka statistik untuk seluruh himpunan.","featuresPage.cards.rename.title":"Ganti nama, urungkan, rapikan","featuresPage.cards.rename.body":"Ganti nama seluruh himpunan hasil dengan cari dan ganti, ekspresi reguler, penghitung, dan perubahan huruf besar/kecil, dengan pratinjau terlebih dahulu dan ditolak jika dua nama akan bertabrakan. Urungkan membalikkan ganti nama, bahkan setelah restart. Temukan duplikat dan folder kosong langsung dari indeks.","featuresPage.cards.everything.title":"Langsung terasa akrab jika Anda datang dari Everything","featuresPage.cards.everything.body":"Sintaks pencarian, filter cepat, dan daftar berkas Everything, untuk impor maupun ekspor, ditambah CSV, teks polos, playlist, dan NDJSON. Mode ketat memeriksa bahwa sebuah kueri hanya memakai apa yang dipahami Everything.","featuresPage.cards.cli.title":"Baris perintah untuk skrip","featuresPage.cards.cli.body":"Perintah freally memakai bahasa kueri yang sama, mencetak JSON, NDJSON, CSV, atau path yang dipisahkan NUL, mengembalikan kode keluar yang bermakna, dan mendukung pelengkapan di bash, zsh, fish, dan PowerShell.","featuresPage.cards.portable.title":"Portabel, jika Anda mau","featuresPage.cards.portable.body":"Jalankan dari flashdisk USB: indeks, pengaturan, markah, dan log tetap berada di folder Data di samping aplikasi, dan tidak ada yang didaftarkan ke komputer tempat ia dicolokkan.","featuresPage.cards.languages.title":"Delapan belas bahasa, terang atau gelap","featuresPage.cards.languages.body":"Menu, pengaturan, dan setiap dialog berganti bahasa seketika, dan bahasa Arab ditata dari kanan ke kiri. Aplikasi mengikuti tema terang atau gelap sistem Anda, atau mempertahankan tema yang Anda pilih.","featuresPage.compare.title":"Berdampingan dengan alat komersial","featuresPage.compare.intro":"Freally Sourcerer 1.0 berdampingan dengan alat pencarian desktop komersial yang dipakai orang saat ini. Setiap sel untuk produk lain berasal dari halaman milik pembuatnya sendiri, diperiksa pada 2 Oktober 2026, dan harga adalah harga daftar AS per Oktober 2026 — kecuali jika pembuatnya tidak menampilkan harga AS, yang dinyatakan di sel tersebut.","featuresPage.compare.feature":"Fitur","featuresPage.compare.note.beta":"dalam beta","featuresPage.compare.row.price":"Harga (USD, Oktober 2026)","featuresPage.compare.freeToday":"Gratis saat ini","featuresPage.compare.note.freeware":"perangkat lunak gratis","featuresPage.compare.note.oneTime":"sekali bayar","featuresPage.compare.note.perYear":"per tahun, paket Basic","featuresPage.compare.legend.unknown":"belum diverifikasi","featuresPage.compare.note.euros":"sekali bayar, hanya dalam euro","featuresPage.compare.row.systems":"Windows, macOS, dan Linux","featuresPage.compare.legend.yes":"ada","featuresPage.compare.legend.partly":"sebagian","featuresPage.compare.row.liveIndex":"Menemukan berkas berdasarkan nama dari indeks yang terus diperbarui saat berkas berubah","featuresPage.compare.note.scheduled":"indeks diperbarui sesuai jadwal","featuresPage.compare.note.spotlight":"indeks Spotlight","featuresPage.compare.note.chosenFolders":"folder yang Anda pilih","featuresPage.compare.row.content":"Mencari teks di dalam dokumen seperti berkas PDF dan Office","featuresPage.compare.note.notIndexed":"tidak diindeks, lambat","featuresPage.compare.row.audio":"Menemukan audio berdasarkan kenyaringan terukur, codec, sample rate, atau durasi","featuresPage.compare.note.noLoudness":"tanpa kenyaringan","featuresPage.compare.note.tagsBitRate":"tag dan bit rate","featuresPage.compare.note.mp3Tags":"tag MP3 dan FLAC","featuresPage.compare.row.properties":"Mencari apa yang dikatakan header berkas: ukuran gambar, kamera, penulis, jumlah halaman","featuresPage.compare.note.exifIptc":"EXIF dan IPTC","featuresPage.compare.row.similar":"Menemukan berkas dari nama yang hanya mirip","featuresPage.compare.note.similarWords":"kata-kata yang mirip di dalam dokumen","featuresPage.compare.row.cli":"Baris perintah untuk pencarian","featuresPage.compare.row.portable":"Berjalan tanpa dipasang, dari flashdisk USB","featuresPage.compare.row.duplicates":"Menemukan berkas duplikat","featuresPage.compare.legend.no":"tidak ada","featuresPage.compare.summaryTitle":"Singkatnya","featuresPage.compare.summary":"Versi singkatnya: hanya Sourcerer yang memiliki semuanya — ketiga sistem, indeks langsung, teks di dalam dokumen, audio berdasarkan kenyaringannya, apa yang dikatakan header berkas, dan nama yang hanya mirip.","featuresPage.compare.theyWinTitle":"Di mana mereka unggul","featuresPage.compare.theyWin":"Di mana mereka unggul: Everything tidak berbayar, dan versi beta 1.5-nya juga menemukan berkas berdasarkan hash-nya; FileLocator Pro mencari di berkas email Outlook; Copernic juga mencari di Google Drive, Dropbox, dan OneDrive; dan DocFetcher Pro menemukan kata-kata yang mirip dengan yang Anda ketik di dalam dokumen.","featuresPage.compare.asOf":"Kolom Sourcerer adalah versi 1.0, yang belum dirilis, dan harganya adalah harga saat ini: Sourcerer gratis saat ini, dan versi mendatang mungkin dijual. Produk lain juga berubah; tabel ini berlaku per 2 Oktober 2026.","featuresPage.why.title":"Mengapa ia dibuat seperti ini","featuresPage.why.journal.title":"Ia mendengarkan alih-alih memindai ulang","featuresPage.why.journal.body":"Setiap sistem sudah mencatat perubahan pada berkas-berkasnya. Sourcerer membaca catatan itu alih-alih menelusuri folder Anda secara berkala, sehingga indeks tetap mutakhir tanpa membaca disk lagi.","featuresPage.why.lazy.title":"Ia hanya membaca apa yang dibutuhkan sebuah pertanyaan","featuresPage.why.lazy.body":"Properti sebuah berkas dibaca pertama kali saat pencarian menanyakannya, dari header-nya saja, dan disimpan sampai berkas itu berubah. Tidak ada yang mendekode gambar atau membuka baris basis data untuk menjawab seberapa lebar sebuah gambar.","featuresPage.why.honest.title":"Ia menyatakan apa yang tidak dapat dilihatnya","featuresPage.why.honest.body":"Folder yang tidak dapat dibaca tampak sama persis dengan folder kosong, jadi Sourcerer menyebutkan folder yang dilewatinya dan alasannya. Jumlah yang mencapai batasnya ditampilkan sebagai nilai minimum, tidak pernah sebagai angka pasti.","featuresPage.why.careful.title":"Ia berhati-hati dengan berkas Anda","featuresPage.why.careful.body":"Ganti nama dipratinjau dan terjadi sekaligus atau tidak sama sekali, penghapusan masuk ke Tempat Sampah atau Recycle Bin, dan perintah buatan Anda sendiri berjalan sebagai program dengan argumen, tidak pernah sebagai baris shell, setelah meminta konfirmasi Anda sekali.","featuresPage.why.local.title":"Ia tetap di komputer Anda","featuresPage.why.local.body":"Tanpa telemetri. Indeks tersimpan di disk Anda sendiri, dan tidak ada apa pun tentang berkas atau pencarian Anda yang dikirim ke mana pun. Pemeriksaan pembaruan hanya menanyakan apakah ada versi yang lebih baru, dan Anda dapat mematikannya.","featuresPage.why.everything.title":"Ia menghargai apa yang sudah Anda ketahui","featuresPage.why.everything.body":"Sintaks, filter, dan daftar berkas Everything berperilaku seperti di sana, diperiksa oleh tes, sehingga kebiasaan bertahun-tahun ikut terbawa — ke dua sistem operasi lagi.","featuresPage.coming.title":"Apa yang masih akan datang","featuresPage.coming.intro":"Dinyatakan terus terang, karena daftar fitur yang menyembunyikan kekurangannya tidak layak dibaca. Halaman ini menjelaskan versi 1.0, dan Sourcerer dibangun satu versi demi satu versi: versi setelah 0.23 masih akan datang. Setiap versi di jalan menuju 1.0 ditandai dengan statusnya. Dua dari lima lensa — teks di dalam berkas dan nama yang hanya mirip — sudah dibangun tetapi belum tersambung ke pencarian. Keduanya ada di halaman ini karena termasuk dalam 1.0.","featuresPage.limits.title":"Apa yang tidak dilakukan 1.0","featuresPage.limits.headers":"Ia hanya membaca properti dari header berkas: ia tidak mendekode gambar, memutar video, atau merender dokumen untuk menemukannya, sehingga properti yang tidak dibawa oleh header tidak dapat dicari.","featuresPage.limits.firstIndex":"Di macOS dan Linux, indeks pertama menelusuri setiap folder, sehingga pada disk yang besar prosesnya memakan waktu menit, bukan detik.","featuresPage.limits.portable":"Salinan portabel tidak memperbarui dirinya sendiri: ganti foldernya dengan versi yang lebih baru.","featuresPage.coming.downloads":"Tidak ada unduhan sebelum versi 1.0, dan tidak ada di halaman ini.","docs.intro":"Cara memakai Freally Sourcerer sebagaimana dibangun saat ini, di jalan menuju 1.0; panduan ini bertambah di setiap versi. Di macOS, baca Ctrl sebagai Cmd: menu menampilkan tombol milik sistem Anda sendiri.","docs.start.title":"Memulai","docs.search.title":"Mencari","docs.lenses.title":"Lima lensa","docs.syntax.title":"Sintaks kueri","docs.filters.title":"Filter cepat","docs.bookmarks.title":"Markah dan bilah sisi","docs.results.title":"Bekerja dengan hasil","docs.rename.title":"Ganti nama massal","docs.preview.title":"Pratinjau dan Lihat Cepat","docs.drives.title":"Drive yang dicabut dan daftar berkas","docs.health.title":"Kesehatan Indeks dan folder yang dilewati","docs.portable.title":"Mode portabel","docs.settings.title":"Pengaturan dan tombol pintas","docs.language.title":"Bahasa","docs.cli.title":"Baris perintah","docs.privacy.title":"Privasi dan jaringan","docs.faq.title":"Pertanyaan","docs.start.p1":"Sourcerer berjalan dalam dua bagian: pengindeks latar belakang, <code>freally-indexd</code>, yang menjaga indeks tetap mutakhir, dan aplikasi tempat Anda mencari. Installer menyiapkan keduanya, dan pengindeks mulai berjalan saat Anda masuk ke akun.","docs.start.id":"ID aplikasi ini adalah <code>com.freallyproducts.sourcerer</code>, dan pengaturan, markah, serta indeks Anda disimpan dengan nama itu di folder data aplikasi sistem Anda. Versi hingga 0.23.2 memakai <code>io.mikeweaver.freally</code>; versi yang lebih baru memindahkan folder itu ke nama baru saat pertama kali dijalankan, sehingga tidak ada yang diindeks ulang.","docs.start.p2":"Saat aplikasi pertama kali dibuka, penyiapan singkat menanyakan folder mana yang akan diindeks, tombol pintas yang memunculkan aplikasi, serta bahasa dan tema Anda. Anda dapat mengubah semuanya nanti di Pengaturan.","docs.start.p3":"Kemudian ia membangun indeks. Di Windows ia membaca change journal NTFS, yang cepat; di macOS dan Linux ia menelusuri folder Anda, yang memakan waktu beberapa menit pada disk yang besar. Anda dapat mencari selama prosesnya berjalan: hasil terisi seiring berjalannya proses.","docs.start.p4":"Tidak ada unduhan sebelum versi 1.0.0, dan kode sumbernya privat.","docs.search.type":"Ketik di bilah pencarian. Hasil muncul sambil Anda mengetik, dikelompokkan per lensa, masing-masing grup dengan lama waktu yang dibutuhkannya. Setiap karakter mempersempitnya; tidak ada yang perlu dikirim.","docs.search.move":"Telusuri hasil dengan tombol panah, dan tekan Enter atau klik ganda sebuah baris untuk membuka berkas dengan aplikasi yang biasa membukanya.","docs.search.within":"<kbd>Ctrl+Shift+F</kbd> mencari di dalam hasil yang sudah ada. Setiap istilah menjadi chip yang dapat dihapus satu per satu, sehingga Anda dapat mundur tanpa mengetik ulang.","docs.search.bold":"Apa yang Anda ketik ditampilkan <strong>tebal</strong> di nama dan path. Pengubah seperti <code>ext:json</code> mempersempit daftar alih-alih menjadi sesuatu yang Anda cari, sehingga tidak ditandai.","docs.search.clear":"<kbd>Esc</kbd> mengosongkan bilah pencarian.","docs.lenses.intro":"Sourcerer memiliki lima lensa, semuanya membaca indeks yang sama. Saat ini lensa nama berkas, audio, dan properti menjawab pencarian Anda; lensa konten dan kemiripan sudah dibangun tetapi belum tersambung ke bilah pencarian — itu akan datang di jalan menuju 1.0.","docs.lenses.filename":"Nama berkas: nama dan path, dengan wildcard, ekspresi reguler, dan pengubah Everything. Yang tercepat di antara kelimanya.","docs.lenses.content":"Konten: teks di dalam berkas PDF, Word, Excel, dan PowerPoint, teks polos dan Markdown, kode sumber dalam 32 bahasa, JSON, CSV, dan YAML, email, serta arsip zip, 7z, dan tar, tanpa membongkarnya. Belum tersambung ke bilah pencarian.","docs.lenses.audio":"Audio: apa yang terukur dari sebuah berkas audio — kenyaringan dalam LUFS, keheningan, rentang dinamis, durasi, codec, dan sample rate — dihitung pertama kali saat pencarian menanyakannya, dan disimpan sampai berkas itu berubah.","docs.lenses.properties":"Properti: apa yang dikatakan header berkas itu sendiri — tujuh puluh dua properti untuk gambar, data kamera, video, dokumen, program, installer, shortcut, arsip, font, email, dan basis data SQLite.","docs.lenses.similar":"Kemiripan: nama yang dekat dengan yang Anda ketik, untuk saat Anda hanya mengingat sebuah berkas secara samar. Belum tersambung ke bilah pencarian; sampai saat itu, pencarian yang tidak menemukan apa pun menawarkan nama nyata yang paling dekat sebagai gantinya.","docs.lenses.prefix":"Lensa dapat diaktifkan dan dinonaktifkan di <strong>Tampilan → Lensa</strong>.","docs.syntax.intro":"Sourcerer memahami sintaks Everything dari voidtools, dan menambahkan pengubah untuk lensa-lensa lainnya.","docs.syntax.basics":"Dasar-dasarnya","docs.syntax.terms":"Kata biasa cocok di bagian mana pun dari nama, dan setiap kata harus cocok: <code>report 2024</code>.","docs.syntax.wildcards":"<code>*</code> cocok dengan deretan karakter apa pun dan <code>?</code> dengan satu karakter, terhadap seluruh nama: <code>invoice_202?.pdf</code>.","docs.syntax.boolean":"Spasi atau <code>AND</code> berarti keduanya, <code>|</code> atau <code>OR</code> berarti salah satunya, <code>!</code> atau <code>NOT</code> berarti bukan, dan tanda kurung mengelompokkan: <code>(budget | forecast) !draft</code>.","docs.syntax.regex":"<code>regex:</code> memulai ekspresi reguler: <code>regex:^report-\\d+</code>. Sintaksnya adalah sintaks Rust, sehingga tidak ada referensi balik dan tidak ada lookaround.","docs.syntax.modifiers":"Pengubah","docs.syntax.modifiersIntro":"Pengubah mempersempit hasil berdasarkan apa yang diketahui tentang sebuah berkas. Gabungkan sebanyak yang Anda mau.","docs.syntax.col.modifier":"Pengubah","docs.syntax.col.matches":"Apa yang dicocokkannya","docs.syntax.col.example":"Contoh","docs.syntax.mod.size":"Ukuran, dengan kb, mb, dan gb, perbandingan, dan rentang","docs.syntax.mod.date":"Tanggal diubah; <code>dc:</code> dibuat, <code>da:</code> diakses","docs.syntax.mod.ext":"Ekstensi, satu atau beberapa yang dipisahkan titik koma","docs.syntax.mod.attrib":"Atribut berkas, seperti tersembunyi","docs.syntax.mod.path":"Path lengkap memuat teks tersebut","docs.syntax.mod.parent":"Berkas berada langsung di dalam folder itu","docs.syntax.mod.anchors":"Nama diawali, atau diakhiri, dengan teks tersebut","docs.syntax.mod.loudness":"Kenyaringan terukur dalam LUFS, dan rentang dinamis dalam dB","docs.syntax.mod.length":"Durasi sebuah berkas audio","docs.syntax.mod.codec":"Codec audio, dan sample rate dalam Hz","docs.syntax.mod.silence":"Seberapa banyak bagian berkas audio yang hening, dari 0 hingga 1","docs.syntax.mod.property":"Salah satu dari tujuh puluh dua properti; <code>property:</code> adalah bentuk panjangnya","docs.syntax.mod.dupe":"Berkas yang memiliki nama dan ukuran yang sama; <code>name-dupe:</code> dan <code>size-dupe:</code> mencocokkan salah satu dari keduanya","docs.syntax.mod.empty":"Berkas dan folder kosong; <code>empty:roots</code> menemukan puncak setiap rantai folder yang tidak memuat berkas","docs.syntax.mod.children":"Folder berdasarkan jumlah item yang langsung dimuatnya; <code>descendant-count:</code> di kedalaman mana pun","docs.syntax.mod.volume":"Berkas di satu drive, berdasarkan namanya, bahkan saat drive itu dicabut","docs.syntax.modes":"Mode pencocokan","docs.syntax.modesMenu":"Menu <strong>Cari</strong> mengalihkan Cocokkan Huruf Besar/Kecil (<kbd>Ctrl+I</kbd>), Cocokkan Seluruh Kata (<kbd>Ctrl+B</kbd>), Cocokkan Path (<kbd>Ctrl+U</kbd>), dan Cocokkan Diakritik (<kbd>Ctrl+M</kbd>).","docs.syntax.ignore":"<strong>Abaikan tanda baca</strong> membuat <code>foobar</code> menemukan <code>foo-bar</code>, dan <strong>Abaikan spasi</strong> membuat <code>myreport</code> menemukan <code>my report</code>. Keduanya nonaktif secara bawaan.","docs.syntax.cjk":"<strong>Cocokkan fonetik CJK</strong> menemukan nama Tionghoa, Jepang, dan Korea berdasarkan cara bacanya: <code>wenjian</code> menemukan 文件.","docs.syntax.regexBuilder":"<strong>Aktifkan Regex</strong> (<kbd>Ctrl+R</kbd>) memperlakukan seluruh kueri sebagai ekspresi reguler. Pembuat ekspresi reguler di samping bilah pencarian menguji pola terhadap nama-nama di layar sambil Anda mengetiknya, dengan pesan galat dari mesin itu sendiri jika polanya tidak valid.","docs.filters.p1":"Filter cepat membatasi hasil ke satu jenis berkas dengan satu klik: Audio, Terkompresi, Dokumen, Berkas Eksekusi, Folder, Gambar, dan Video. Masing-masing memuat setiap ekstensi yang dimuat filter milik Everything, dan lebih banyak lagi — 65 jenis audio, 79 video, 77 gambar, 86 dokumen, dan 70 arsip.","docs.filters.p2":"Anda juga dapat mengetiknya, dengan alias yang mudah ditebak: <code>audio:</code>, <code>video:</code>, <code>image:</code>, <code>document:</code>, <code>executable:</code>, dan <code>archive:</code>, atau <code>music:</code>, <code>photos:</code>, <code>docs:</code>, dan <code>zip:</code>.","docs.filters.p3":"Kode sumber tidak dimasukkan ke Dokumen, tidak seperti di Everything; <code>ext:c;cpp;h</code> mengembalikan himpunan itu. Untuk menyimpan pencarian Anda sendiri sebagai filter, pilih <strong>Cari → Tambahkan ke Filter…</strong>, dan sunting filter-filter itu dengan <strong>Atur Filter…</strong> (<kbd>Ctrl+Shift+O</kbd>).","docs.bookmarks.add":"<kbd>Ctrl+D</kbd> menyimpan pencarian saat ini sebagai markah, dan <kbd>Ctrl+Shift+B</kbd> membuka pengaturan markah-markah itu.","docs.bookmarks.recall":"Ketik <code>:</code> diikuti nama sebuah markah untuk menjalankannya.","docs.bookmarks.sidebar":"<strong>Tampilan → Bilah sisi</strong> menampilkan kolom berisi markah, filter cepat, drive, dan pencarian terbaru Anda. Seret markah untuk mengubah urutannya; klik sebuah drive untuk mencari hanya di drive itu.","docs.bookmarks.history":"Pencarian terbaru tidak direkam selama Mode privasi aktif atau riwayat pencarian dinonaktifkan.","docs.results.intro":"Setiap baris adalah berkas nyata di disk Anda. Klik kanan sebuah baris untuk melihat apa yang dapat Anda lakukan dengannya:","docs.results.open":"Buka, Tampilkan di pengelola berkas, dan Buka dengan, yang mencantumkan aplikasi yang didaftarkan sistem Anda untuk jenis berkas itu.","docs.results.copy":"Salin isi untuk isi berkas teks, Salin sebagai berkas untuk menempelkan berkas itu sendiri ke sebuah folder, dan Salin daftar jalur — satu per baris, dalam tanda kutip, dipisahkan spasi, atau di-escape untuk shell.","docs.results.hits":"Lihat kecocokan dalam konteks menampilkan setiap kecocokan di sebuah dokumen; <kbd>F3</kbd> dan <kbd>Shift+F3</kbd> menelusurinya.","docs.results.terminal":"Buka terminal di sini membuka terminal di folder berkas tersebut.","docs.results.commands":"Perintah buatan Anda sendiri, dari <strong>Pengaturan → Umum → Perintah khusus</strong>, dengan <code>{path}</code>, <code>{dir}</code>, <code>{name}</code>, <code>{stem}</code>, dan <code>{ext}</code> di argumennya. Masing-masing berjalan sebagai program dengan argumen, tidak pernah sebagai baris shell, dan aplikasi meminta konfirmasi sekali sebelum sebuah program dijalankan untuk pertama kalinya.","docs.results.delete":"Hapus mengirim berkas ke Tempat Sampah atau Recycle Bin.","docs.results.view":"Seret sebuah baris ke aplikasi lain seperti dari pengelola berkas Anda. Klik header kolom untuk mengurutkan, atau gunakan <kbd>Ctrl+1</kbd> hingga <kbd>Ctrl+9</kbd>; tombol <strong>+</strong> di ujung baris header menambahkan properti sebagai kolom. Menu <strong>Tampilan</strong> beralih antara Detail dan Gambar Mini. Klik jumlah hasil di bilah status untuk statistik seluruh himpunan hasil: ukuran dan jumlah menurut jenis, serta berkas terbesar, terlama, dan terbaru.","docs.rename.intro":"Pilih hasil yang akan diganti namanya lalu tekan <kbd>F2</kbd>. Anda menjelaskan perubahannya sekali, dan setiap nama lama dan baru ditampilkan sebelum apa pun menyentuh disk.","docs.rename.find":"Cari dan ganti, sebagai teks biasa atau ekspresi reguler, dengan <code>$1</code>, <code>$2</code> untuk apa yang ditangkapnya.","docs.rename.number":"<code>{n}</code> dalam teks pengganti memberi nomor pada berkas sesuai urutan pratinjau; <code>{n:03}</code> melengkapi nomor itu menjadi tiga digit.","docs.rename.case":"Ubah huruf besar/kecil, dan pilih apakah aturan berlaku hanya untuk nama atau juga untuk ekstensi. Secara bawaan ekstensi dibiarkan apa adanya.","docs.rename.check":"Baris yang akan bertabrakan, menimpa berkas, atau menghasilkan nama yang ditolak sistem ditandai, dan tidak ada yang diganti namanya selama masih ada baris yang ditandai: batch itu terjadi seluruhnya atau tidak sama sekali.","docs.rename.undo":"<kbd>Ctrl+Z</kbd> mengurungkan ganti nama, bahkan setelah Anda memulai ulang aplikasi, dan <kbd>Ctrl+Shift+Z</kbd> mengulanginya. Di Windows dan Linux, Urungkan juga mengembalikan berkas yang dihapus dari Recycle Bin atau Tempat Sampah. Di macOS tidak bisa: pulihkan sendiri berkas itu dari Tempat Sampah.","docs.preview.pane":"<strong>Tampilan → Pratinjau</strong> (<kbd>Alt+P</kbd>) menampilkan berkas yang dipilih di samping hasil: gambar, teks dan kode, serta dokumen.","docs.preview.play":"Audio dan video diputar di panel, dengan putar dan jeda, seek, pengulangan, dan volume. Audio menggambar waveform yang dapat diklik, dengan codec, sample rate, kanal, dan kenyaringannya di bawahnya.","docs.preview.quickLook":"<kbd>Space</kbd> membuka Lihat Cepat, pratinjau besar di atas jendela. Tombol panah tetap menelusuri hasil selama pratinjau terbuka, dan <kbd>Space</kbd> atau <kbd>Esc</kbd> menutupnya.","docs.preview.mac":"Di macOS, Lihat Cepat juga menawarkan untuk membuka berkas di Lihat Cepat milik macOS sendiri, untuk format yang dapat ditampilkan sistem tetapi tidak dapat ditampilkan Sourcerer.","docs.drives.unplugged":"Saat Anda mencabut sebuah drive, semua yang terindeks di dalamnya tetap dapat dicari. Hasilnya membawa lencana berisi nama drive, sehingga hasil itu juga menjawab di drive mana sebuah berkas berada, dan <code>volume:</code> mencari di satu drive berdasarkan namanya. Drive yang kembali dengan huruf atau titik mount yang berbeda tetap dikenali.","docs.drives.lists":"<strong>Berkas → Ekspor Hasil…</strong> (<kbd>Ctrl+S</kbd>) menyimpan hasil sebagai daftar berkas <code>.efu</code> milik Everything, CSV, teks polos, playlist M3U berisi berkas audio, atau NDJSON untuk skrip. <strong>Berkas → Buka Daftar Berkas…</strong> (<kbd>Ctrl+O</kbd>) mencari di dalam sebuah daftar, termasuk milik Everything, alih-alih di indeks, sampai Anda memilih <strong>Tutup Daftar Berkas</strong>.","docs.health.index":"<strong>Alat → Pemeliharaan indeks → Kesehatan Indeks…</strong> menampilkan, untuk setiap lokasi yang dipantau, apakah perubahan tiba secara langsung atau hanya saat dipindai ulang, seberapa jauh indeks tertinggal, dan berapa banyak perubahan yang terbuang. Saat ada yang salah, panel ini menyebutkan apa masalahnya, dengan pembangunan ulang sekali klik jika itu solusinya.","docs.health.permissions":"Folder yang tidak dapat dibaca aplikasi tampak sama persis dengan folder kosong. <strong>Status izin…</strong>, di menu yang sama atau dari lencana \"folder dilewati\" di bilah status, mencantumkan folder yang dilewati, alasan dari sistem, dan cara memperbaikinya. Di macOS, panel ini memeriksa apakah Akses Disk Penuh sudah diberikan dan membuka halaman pengaturan yang tepat jika belum.","docs.portable.p1":"Untuk menjalankan Sourcerer dari flashdisk USB, letakkan berkas kosong bernama <code>portable.flag</code> di samping aplikasi, atau jalankan dengan <code>--portable</code>. Indeks, pengaturan, markah, dan log kemudian disimpan di folder <code>Data</code> di samping aplikasi, dan tidak ada yang didaftarkan ke komputer: tanpa layanan latar belakang, tanpa handler tautan, dan tanpa updater. Perbarui salinan portabel dengan mengganti foldernya.","docs.portable.mac":"Di macOS, folder <code>Data</code> dibuat di samping aplikasi, bukan di dalamnya, karena menulis di dalam aplikasi merusak tanda tangannya.","docs.settings.open":"<strong>Alat → Opsi…</strong> (<kbd>Ctrl+,</kbd>) membuka Pengaturan, yang ditata seperti jendela Options milik Everything: pohon panel di sebelah kiri, kotak di atasnya yang memfilter panel dan opsi sambil Anda mengetik, serta <strong>OK</strong>, <strong>Batal</strong>, dan <strong>Terapkan</strong>.","docs.settings.panels":"Panel-panelnya mencakup tampilan aplikasi, perilaku pencarian, hasil, pintasan papan ketik, folder, drive, dan pengecualian yang membentuk indeks, setiap lensa, privasi dan pembaruan, log, pencadangan dan reset, serta bahasa.","docs.settings.hotkey":"Tombol pintas global memunculkan aplikasi dari mana saja, dengan bilah pencarian siap dipakai. Setel di <strong>Pengaturan → Umum → Papan Ketik</strong>. Tautan berbentuk <code>freally://search?q=…</code> membuka aplikasi dengan pencarian tersebut.","docs.language.p1":"Sourcerer tersedia dalam delapan belas bahasa. Pilih salah satunya di <strong>Pengaturan → Lokal</strong> dan seluruh aplikasi — menu, pengaturan, dialog, dan bilah status — langsung berganti, tanpa restart. Bahasa Arab menata jendela dari kanan ke kiri.","docs.cli.intro":"Perintah <code>freally</code> mencari di indeks yang sama dengan aplikasi, melalui pengindeks yang sama, dalam bahasa kueri yang sama.","docs.cli.formats":"<code>--json</code>, <code>--ndjson</code>, dan <code>--csv</code> mencetak hasil untuk skrip, <code>-0</code> mencetak path yang dipisahkan NUL untuk <code>xargs -0</code>, dan <code>--fields</code> memilih kolom. Kode keluarnya menyatakan apakah ada yang cocok.","docs.cli.strict":"<code>--strict-everything</code> menolak kueri apa pun yang memakai sesuatu yang tidak dimiliki Everything, dan menyebutkannya — cara untuk memastikan sebuah kueri berfungsi di keduanya.","docs.cli.manage":"<code>freally index</code> menampilkan status pengindeks dan dapat menjeda, melanjutkan, memverifikasi, memadatkan, atau membangunnya ulang; <code>freally bookmark</code> menyimpan, mencantumkan, dan menghapus markah.","docs.cli.completions":"<code>freally completions</code> mencetak pelengkapan untuk bash, zsh, fish, dan PowerShell, termasuk nama pengubah dan markah Anda.","docs.privacy.telemetry":"Tidak ada telemetri. Indeks dibangun dan disimpan di komputer Anda sendiri, dan tidak ada apa pun tentang berkas atau pencarian Anda yang dikirim ke mana pun.","docs.privacy.updates":"Aplikasi menanyakan apakah ada versi yang lebih baru sekali sehari; di <strong>Pengaturan → Privasi &amp; Pembaruan</strong> Anda dapat mengubahnya menjadi mingguan, bulanan, atau tidak pernah, atau memeriksa sekarang. Aplikasi meminta konfirmasi sebelum memasang apa pun, dengan menyebutkan kedua versi, dan salinan portabel tidak pernah memeriksa.","docs.privacy.mode":"Mode privasi berhenti merekam pencarian terbaru dan menonaktifkan lensa properti, yang membaca isi berkas.","docs.privacy.reports.title":"Melaporkan masalah","docs.privacy.reports.where":"Saat aplikasi mengalami galat, pesannya memiliki tombol <strong>Laporkan</strong> di sampingnya. Setelah crash, peluncuran berikutnya menawarkan <strong>Laporkan</strong> atau <strong>Tutup</strong>.","docs.privacy.reports.page":"<strong>Laporkan</strong> membuka halaman laporan, <code>freallyproducts.com/freally-sourcerer/report/</code>, di browser Anda, dengan fakta teknis yang sudah terisi: Anda dapat membacanya tetapi tidak dapat mengubahnya. Anda menambahkan apa yang sedang Anda lakukan dan, jika mau, alamat email.","docs.privacy.reports.send":"Tidak ada yang dikirim kecuali Anda menekan <strong>Kirim</strong> di halaman itu, dan tidak ada apa pun yang pernah dikirim di latar belakang.","docs.faq.missing.title":"Mengapa sebuah berkas tidak ada di hasil?","docs.faq.missing.indexing":"Indeks pertama mungkin masih berjalan: bilah status akan menyatakannya.","docs.faq.missing.roots":"Foldernya mungkin tidak diindeks: periksa folder, drive, dan pengecualian di bawah <strong>Pengaturan → Indeks</strong>.","docs.faq.missing.permissions":"Foldernya mungkin tidak dapat dibaca: buka <strong>Status izin…</strong>.","docs.faq.smaller.title":"Bagaimana cara memperkecil indeks?","docs.faq.smaller.body":"Kecualikan folder yang penuh dengan berkas yang tidak pernah Anda cari, seperti <code>node_modules</code> dan <code>.git</code>, di bawah <strong>Pengaturan → Indeks → Kecualikan</strong>.","docs.faq.rebuild.title":"Bagaimana cara membangun ulang indeks dari awal?","docs.faq.rebuild.body":"<strong>Alat → Pemeliharaan indeks → Paksa Bangun Ulang Indeks…</strong> mengosongkan indeks dan membangunnya lagi dari awal. <strong>Verifikasi Indeks…</strong> dan <strong>Padatkan Indeks…</strong> di menu yang sama memeriksanya dan memperkecilnya.","kit.skip":"Lompat ke konten","kit.nav.site":"Situs","kit.nav.home":"Beranda","kit.nav.features":"Fitur","kit.nav.documentation":"Dokumentasi","kit.nav.changelog":"Log perubahan","kit.nav.language":"Bahasa","kit.nav.allApps":"Semua aplikasi Freally","kit.badge.progress":"v0.23.0 selesai · berikutnya v0.24.0","kit.cta.features":"Lihat semua fitur","kit.cta.docs":"Baca dokumentasi","kit.price":"Freally Sourcerer gratis saat ini, tetapi mungkin tidak gratis selamanya: versi mendatang mungkin dijual.","kit.noDownloads":"Belum ada unduhan, dan kode sumbernya bersifat pribadi.","kit.label.overview":"Ikhtisar","kit.label.inside":"Di dalamnya","kit.label.roadmap":"Peta jalan","kit.ladder.done":"Selesai","kit.ladder.planned":"Direncanakan","kit.ladder.goal":"Tujuannya","kit.label.honesty":"Kejujuran","kit.family.label":"Keluarga Freally","kit.family.title":"<span class=\"hl-muted\">Satu keluarga.</span> <span class=\"hl-bright\">Delapan aplikasi.</span>","kit.cta.label":"Apa yang berubah","kit.cta.title":"<span class=\"hl-muted\">Setiap versi,</span> <span class=\"hl-bright\">tercatat.</span>","kit.cta.lede":"Log perubahan mencatat semua yang berubah di Freally Sourcerer, versi demi versi, dalam kedelapan belas bahasa.","kit.cta.changelog":"Baca log perubahan","kit.footer.thisApp":"Aplikasi ini","kit.footer.family":"Keluarga Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"Dalam pengembangan · v0.23.2","kit.head.features":"<span class=\"hl-muted\">Semua yang dilakukannya,</span> <span class=\"hl-bright\">berdampingan.</span>","kit.label.numbers":"Dalam angka","kit.label.free":"Gratis hari ini","kit.label.compare":"Perbandingan","kit.label.principles":"Prinsip","kit.label.limits":"Batasan","kit.states.title":"Arti setiap status","kit.states.done":"sudah dibangun dan diberi tag, tetapi bukan unduhan di situs ini","kit.states.planned":"masih akan dibangun","kit.states.goal":"versi yang menjadi tujuan jalan ini","kit.states.ladder":"Lihat setiap anak tangga di jalan ini","kit.head.documentation":"<span class=\"hl-muted\">Cara kerjanya,</span> <span class=\"hl-bright\">langkah demi langkah.</span>","kit.search.placeholder":"Cari dalam dokumentasi","kit.docs.contents":"Daftar isi","kit.head.changelog":"<span class=\"hl-muted\">Setiap perubahan,</span> <span class=\"hl-bright\">versi demi versi.</span>","kit.changelog.lede":"Terbaru lebih dulu: semua yang berubah di Freally Sourcerer, dalam setiap bahasa situs ini.","kit.changelog.versions":"Versi","kit.changelog.unreleased":"Belum dirilis","kit.search.none":"Tidak ada yang cocok di situs ini.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">Belum Dirilis</span></span>","changelog.6b02e0d363a4":"Ditambahkan","changelog.1e07f27ea3ab":"<strong>[semua platform]</strong> <strong>Lensa properti</strong> (SRC-N01 … SRC-N15) — lensa kelima yang membaca <em>header kontainer</em>. <code>width:&gt;1920</code>, <code>camera-model:R5</code>, <code>author:lovelace</code>, <code>binary-type:arm64</code>, <code>package-version:0.23</code>, <code>broken-link:</code>, <code>entry-count:&gt;1000</code>, <code>font-scripts:cyrillic</code>, <code>from:ada@example.com</code>, <code>table-names:notes</code> — tujuh puluh dua properti dalam sebelas grup, masing-masing dapat diketik sebagai pengubah dan masing-masing juga tersedia sebagai kolom hasil. Crate baru <code>freally-properties</code>; namespace DSL baru <code>property:</code> untuk bentuk generiknya (<code>property:duration&gt;60</code>, yang menjadi cara menjangkau kunci yang namanya sudah dipakai oleh pengubah yang lebih lama).","changelog.a87ab2c792bf":"<strong>Malas dan diinvalidasi oleh journal.</strong> Tidak ada yang berjalan saat pengindeksan. Sebuah properti dibaca pertama kali saat kueri menanyakan berkas tersebut, lalu di-cache terhadap <code>mtime_ns</code>-nya, sehingga journal menginvalidasi lensa ini tanpa lensa itu pernah berlangganan padanya — kontrak yang sama yang dimiliki lensa audio sejak Fase 9. Hasil yang kosong juga di-cache: folder berisi berkas <code>.txt</code> hanya memakan satu <code>open</code> per berkas untuk setiap generasi indeks, bukan satu per ketukan tombol.","changelog.ca8eac0102ce":"<strong>Hanya header.</strong> Tidak ada parser yang mendekode gambar, men-demux stream, merender halaman, atau membaca satu baris pun dari basis data siapa pun. Batas itulah yang membuat <code>width:&gt;1920</code> tetap dapat dijawab secepat Anda mengetik pada folder berisi berkas RAW.","changelog.982e60011610":"<strong>Total.</strong> Tidak ada berkas yang dapat membuat kueri properti gagal. Header yang terpotong, <code>.png</code> yang ternyata berkas teks, path yang tidak dapat dibaca: semuanya berarti &quot;baris ini tidak memiliki properti&quot;, yang merupakan alasan yang sepenuhnya sah untuk tidak cocok.","changelog.020bc33d94a7":"<strong>Format.</strong> Dimensi dan detail internal PNG / JPEG / GIF / WebP / BMP / TIFF / AVIF-HEIC (SRC-N02, N04); data pengambilan EXIF dengan penanda has-GPS dan <strong>tanpa menyimpan koordinat</strong> (N03); detail teknis MP4 / MOV / MKV / WebM / AVI (N05); kamus info PDF serta <code>core.xml</code> / <code>app.xml</code> OOXML (N08); arsitektur PE / ELF / Mach-O, string VERSIONINFO Windows, dan status Authenticode (N09); metadata paket MSI / deb / rpm / pkg (N10); target <code>.lnk</code> / <code>.desktop</code> / symlink dengan pencari <code>broken-link:</code> (N11); jumlah entri, rasio kompresi, enkripsi, dan deteksi multi-volume untuk zip / 7z / tar (N12); keluarga font, ketebalan, jumlah glyph, dan skrip yang didukung untuk TTF / OTF / WOFF, dibaca dari <em>cmap</em> alih-alih dari rentang yang dideklarasikan (N13); header RFC-822 dan mbox (N14); skema SQLite (N15).","changelog.2f4f9e89e8ed":"<strong>Dua pengekstrak konten baru.</strong> Header dan isi <code>.eml</code> / <code>.mbox</code> mengisi lensa konten, dengan lampiran dicantumkan sebagai entri virtual dalam ejaan <code>container!inner</code> milik archive-peek — <em>byte</em> lampiran tidak pernah didekode (N14). <code>.db</code> / <code>.sqlite</code> selalu menyumbangkan nama tabel dan kolomnya, sedangkan baris-baris pertama kolom teks <strong>hanya</strong> di balik pengaturan yang nonaktif secara bawaan (N15): basis data di folder unduhan adalah data aplikasi milik seseorang.","changelog.58bf7de69c7c":"<strong>Kolom properti</strong> (SRC-N06) — properti apa pun dapat menjadi kolom hasil lewat menu <code>+</code> di baris header, dapat diurutkan, dengan tata letak otomatis per filter cepat (Gambar menampilkan dimensi, Video menampilkan durasi dan resolusi). ID kolom kini <code>name</code> … <code>ext</code> ditambah <code>prop:&lt;key&gt;</code>, digerakkan oleh data dari registri alih-alih union yang tetap.","changelog.aa4087512231":"<strong>Statistik hasil</strong> (SRC-N07) — mengklik jumlah hasil di bilah status membuka total byte, jumlah dan ukuran menurut ekstensi dan menurut jenis, baris terbesar / terlama / terbaru, serta histogram untuk setiap properti yang benar-benar dimiliki himpunan hasil itu. Dihitung di sisi daemon atas seluruh himpunan hasil, bukan atas halaman di layar, dan dibatasi pada 200 000 baris dengan catatan &quot;ini adalah batas bawah&quot; saat batas itu tercapai.","changelog.47c227c9a823":"<strong>Pengaturan → Lensa → Properti</strong> — lensa aktif atau nonaktif, sakelar per grup, batas waktu ekstraksi per berkas, sakelar baris SQLite, dan sakelar kolom otomatis. Mode privasi menonaktifkan seluruh lensa, karena lensa ini membaca isi berkas, dan justru itulah yang dijaga oleh mode privasi.","changelog.2662e0d9c21f":"<strong>Penyimpangan, dinyatakan alih-alih ditutupi.</strong> Verifikasi tanda tangan di macOS melaporkan tanda tangan yang <em>tertanam</em> alih-alih yang tervalidasi: pemeriksaan notarisasi lewat <code>Security.framework</code> adalah FFI unsafe terhadap framework yang tidak dapat diuji oleh mesin mana pun di proyek ini, dan <code>valid</code> yang tidak dapat diverifikasi lebih buruk daripada <code>embedded</code> yang jujur. Font WOFF2 tidak menghasilkan apa pun — brotli ditambah transformasi glyf/loca berarti pustaka font kedua, bukan sekadar membaca header. Biner ELF sama sekali tidak mendapat properti <code>signature</code>, karena Linux menandatangani paket, bukan biner, dan jawabannya ada di SRC-N10. <em>Nama</em> properti diturunkan dari kuncinya (<code>aspect-ratio</code> → &quot;Aspect ratio&quot;) di setiap lokal alih-alih diterjemahkan; elemen UI di sekitarnya dilokalkan seperti biasa.","changelog.bc802b748761":"<strong>[semua platform]</strong> <strong>Apa yang Anda ketik ditampilkan tebal di hasil</strong>, seketika saat Anda mengetik, di kolom Nama maupun Path. Hanya istilah pencarian Anda yang ditandai: pengubah seperti <code>ext:json</code> mempersempit daftar alih-alih menjadi sesuatu yang Anda cari, sehingga <code>json</code> tidak ditebalkan di dalam setiap nama berkas. Ditandai dengan ketebalan huruf, bukan blok sorotan, sehingga tetap terbaca pada baris terpilih dan di kedua tema.","changelog.0a3eaf604faf":"<strong>[semua platform]</strong> <strong>Laporkan bug</strong> — <code>Help → Report a Bug…</code>, ditambah prompt yang muncul pada peluncuran berikutnya setelah aplikasi crash. Sebuah panic hook menulis laporan crash yang <strong>sudah dibersihkan</strong> secara lokal (path beranda dan nama pengguna disamarkan sebelum berkas menyentuh disk), dan dialognya menampilkan teks yang <strong>persis</strong> akan dikirim — hanya versi aplikasi dan OS — sebelum menawarkan untuk membuka isu GitHub atau draf email yang sudah terisi. <strong>Tidak ada yang terkirim otomatis</strong>; tidak ada telemetri dan tidak ada server yang kami jalankan. Dua latihan tersedia di Pengaturan → Log &amp; Debug.","changelog.09c294b4b464":"<strong>[semua platform]</strong> <strong>Periksa pembaruan</strong> — Pengaturan → Privasi &amp; Pembaruan kini bertanya kepada updater alih-alih membuka halaman web. Fitur ini melaporkan versi yang sedang Anda jalankan, menampilkan catatan rilis dengan tautan yang berfungsi, dan saat ada pembaruan menampilkan <strong>kotak Ya/Tidak yang menyebutkan kedua versi</strong> sebelum memasang apa pun. Jika Anda memilih ya, fitur ini menghentikan daemon pengindeks, memasang pembaruan, lalu menutup aplikasi; di Windows, halaman akhir installer menawarkan untuk menjalankan versi baru. Pemeriksaan saat peluncuran mematuhi pengaturan frekuensi, mundur saat ada laporan crash yang menunggu, dan tetap <strong>diam</strong> saat mesin sedang luring.","changelog.59f3ea0ca50a":"<strong>[Windows]</strong> <code>freally-indexd status</code> melaporkan apakah daemon terdaftar sebagai layanan dan bagaimana service manager memandangnya. Sebelumnya install dan uninstall sudah ada tanpa cara untuk menanyakan apa yang terjadi.","changelog.5b14114e2f2b":"<strong>[dokumentasi]</strong> <code>docs/EVERYTHING_MIGRATION_GUIDE.md</code> — apa yang terbawa dari Everything milik voidtools, apa yang baru, dan tiga hal yang akan mengejutkan Anda. <code>docs/MENU_REFERENCE.md</code> — seluruh 112 item menu beserta pintasannya, dihasilkan dari spesifikasi menu sehingga tidak bisa usang.","changelog.2643567f0f72":"<strong>[pengemasan]</strong> <code>packaging/</code> berisi manifes winget, Chocolatey, Homebrew Cask, Flathub, dan Snap, yang dihasilkan dari rilis yang telah diterbitkan oleh <code>scripts/gen-packaging.mjs</code> sehingga checksum-nya adalah checksum yang disajikan GitHub.","changelog.013883122f3c":"<strong>[rilis]</strong> <code>scripts/verify-updater-chain.mjs</code> membuktikan bahwa rilis yang diterbitkan benar-benar dapat diperbarui: skrip ini membandingkan ID kunci di dalam setiap tanda tangan platform dengan kunci publik yang dikompilasi ke dalam biner. Updater gagal secara tertutup <strong>dan diam</strong>, sehingga tidak ada hal lain yang akan menangkap rilis yang ditandatangani dengan kunci yang salah.","changelog.0c8009384b06":"<strong>[semua platform]</strong> Penghapusan berkas kini dapat diurungkan. <code>files_delete</code> mengirim baris ke tempat sampah OS, yang dapat dipulihkan, tetapi tidak mencatat apa pun — sehingga Urungkan milik aplikasi sendiri tidak pernah menawarkan untuk mengembalikan penghapusan di platform mana pun. Kini penghapusan dicatat dalam journal, dan Ctrl+Z memulihkan dari Recycle Bin (Windows) atau tempat sampah freedesktop (Linux).","changelog.e370b0fcd2c3":"<strong>[khusus macOS]</strong> Penghapusan dicatat sebagai <strong>tidak dapat diurungkan, dengan alasannya ditampilkan</strong>, karena Put Back dimiliki Finder dan tidak menyediakan API untuk itu. Urungkan kini menyatakannya alih-alih diam saja: <code>next_undo</code> dengan benar menolak melompati entri yang tidak dapat diurungkan, yang berarti Ctrl+Z sama sekali tidak melakukan apa pun setelah penghapusan dan tidak pernah menjelaskan alasannya.","changelog.63589b7d0b3f":"<strong>[semua platform]</strong> Perintah khusus meminta konfirmasi sekali, lewat dialog native OS, sebelum menjalankan sebuah program untuk pertama kalinya. Persetujuan dikaitkan dengan programnya, sehingga mengganti nama perintah tidak memicu permintaan ulang, dan permintaan itu menyebutkan argumen sekaligus programnya. Persetujuan disimpan di luar <code>settings.json</code> — menyimpannya di sana akan menempatkan allowlist di balik jalur yang sama yang dapat ditulisi webview, yang justru hendak dilindungi oleh permintaan konfirmasi itu. Lihat <code>docs/SECURITY.md</code>.","changelog.549a5f40d4d8":"<strong>[semua platform]</strong> Pegangan pengubah ukuran kolom kini dapat dioperasikan dari papan ketik: tombol panah menggesernya sedikit, Home/End melompat ke batasnya. Sebelumnya pegangan ini dapat difokuskan tetapi tidak melakukan apa pun, yang lebih buruk daripada tidak dapat difokuskan sama sekali.","changelog.2a6141e43be0":"Diubah","changelog.484caa95cf9c":"<strong>[semua platform]</strong> <strong>Pencarian nama berkas jauh lebih cepat untuk kueri yang difilter.</strong> Diukur pada satu juta berkas, <code>ext:json</code> turun dari 229 ms → 11 ms (20.7×), <code>regex:^report-</code> 76 ms → 9.5 ms (7.9×), <code>*.rs</code> 60 ms → 19 ms (3.1×), dan <code>report path:horizon</code> 31 ms → 12 ms (2.6×). Pencarian satu kata biasa memang sudah cepat dan tidak berubah. Empat hal yang membuatnya: bentuk-bentuk kueri tersebut kini menghasilkan seed trigram alih-alih menelusuri setiap nama yang terindeks; indeks nama membawa ekstensi, ukuran, tanggal, dan bit atribut setiap baris sehingga filter-filter itu dijawab dari memori alih-alih dengan mengambil setiap baris yang cocok dari SQLite; path sebuah direktori disimpan sekali, bukan sekali untuk setiap berkas di dalamnya, sehingga <code>path:</code> dapat menolak baris sebelum baris itu diambil; dan mengetik kata yang lebih panjang kini mempersempit hasil dari ketukan sebelumnya alih-alih mulai dari awal. Di Linux pada 200 000 berkas, setiap skenario benchmark kini di bawah 8 ms. Lihat bagian <strong>Search performance</strong> (kinerja pencarian) di README untuk tabel lengkapnya, mesin tempat pengukuran dilakukan, dan alasan hasil di mesin Anda akan berbeda.","changelog.89b30b76bb7e":"<strong>[semua platform]</strong> <strong>Filter cepat mencakup jauh lebih banyak isi disk Anda.</strong> Audio bertambah dari 22 ekstensi menjadi 65, Video 23 → 79, Gambar 24 → 77, Dokumen 25 → 86, Arsip 23 → 70. Setiap ekstensi yang dimiliki filter bawaan Everything kini tersedia — diperiksa oleh tes yang menyebutkannya satu per satu — sehingga tidak ada yang bisa Anda temukan di bawah sebuah filter di Everything yang hilang di sini. Tambahannya adalah format yang lebih baru daripada bawaan Everything: Opus, AVIF, JXL, HEIC, RAW kamera dari setiap produsen besar, zstd, OpenDocument, ebook, dan format Apple iWork. Anda juga dapat mengetiknya, dengan alias yang mudah ditebak — <code>music:</code>, <code>movies:</code>, <code>photos:</code>, <code>docs:</code>, <code>compressed:</code>, <code>zip:</code>. Kode sumber tetap tidak masuk ke <strong>Dokumen</strong> (Everything memasukkan <code>c</code>/<code>cpp</code>/<code>h</code>/<code>java</code>); <code>ext:c;cpp;h</code> memberi Anda himpunan lama.","changelog.170d6493da10":"<strong>[semua platform]</strong> <strong>Filter yang mencakup porsi besar disk Anda tidak lagi lambat.</strong> Memilih Audio atau Terkompresi dulu menelusuri setiap baris terindeks satu per satu, karena gabungan enam puluh ekstensi tidak dapat memakai indeks trigram — mempersempit pada salah satunya akan membuang kecocokan dari lima puluh sembilan lainnya. Kini Freally membaca kolom ekstensinya langsung secara berurutan di memori, empat byte per baris. Diukur pada 2.7 juta berkas, filter yang cocok dengan seperlimanya berubah dari bentuk kueri paling lambat menjadi yang paling cepat.","changelog.30a936879584":"<strong>[semua platform]</strong> <strong>Jumlah hasil kini adalah jumlah kecocokan, bukan jumlah baris di layar.</strong> Filter yang cocok dengan setengah juta berkas akan menyatakannya, seperti &quot;531,129 objects&quot; milik Everything, sambil tetap hanya mengambil halaman yang dapat Anda lihat. Saat kueri cukup luas hingga mencapai batas atas kandidat, jumlahnya dilaporkan sebagai batas bawah alih-alih angka yang tampak pasti padahal tidak.","changelog.6af3be76b723":"<strong>[semua platform]</strong> Filter cepat kini mencocokkan ekstensi asli berkas alih-alih apa pun yang mengikuti titik terakhir di namanya. Dotfile seperti <code>.jsonrc</code> tidak memiliki ekstensi, sehingga tidak lagi muncul di bawah filter cepat JSON — itulah yang selalu dilakukan <code>ext:json</code>, dan kini keduanya sepakat.","changelog.d37659a5fceb":"<strong>[semua platform]</strong> <strong>Pengindeksan disk besar kira-kira 20× lebih cepat.</strong> Setiap commit selama pemindaian membangun ulang indeks terurut atas setiap nama berkas yang sudah terlihat — pada 200 000 berkas, itu memakan 1.34 detik dari commit 1.4 detik, dan makin buruk semakin jauh pemindaian berjalan. Tidak ada yang membaca hasilnya. Pemindaian pertama atas drive berisi jutaan berkas berubah dari hitungan jam menjadi hitungan menit.","changelog.e2099089ef3b":"<strong>[semua platform]</strong> Submenu kini <strong>klik-untuk-menyematkan</strong>. Satu klik menahan submenu tetap terbuka ke mana pun penunjuk kemudian bergerak, sesuai kebutuhan trackpad dan tes otomatis; mengarahkan kursor tetap membukanya.","changelog.fb8d168729ab":"<strong>[semua platform]</strong> <code>freally index pause</code> dan <code>resume</code> kini benar-benar menjeda dan melanjutkan, dengan menyetel <code>monitor_changes</code> pada setiap volume yang terdeteksi. Sebelumnya masing-masing mengirim satu kunci pengaturan yang tidak berkaitan lalu mencetak pesan sukses.","changelog.1246fc93bca0":"Diperbaiki","changelog.40cc68328345":"<strong>[semua platform]</strong> Panel Kesehatan Indeks membebani thread utama hingga penuh dan membombardir daemon dengan panggilan <code>index_health</code> secepat daemon dapat menjawab, alih-alih melakukan polling setiap 2 s. <code>$effect</code>-nya memulai poller secara inline, dan poller membaca serta menulis state yang kemudian dilanggani oleh effect tersebut, sehingga setiap jawaban memulainya ulang. Panel itu tidak dapat dipakai dan aplikasi berhenti merespons selama panel terbuka. Bug ini sudah ikut dirilis sejak M13; spesifikasi e2e yang seharusnya menangkapnya berstatus <code>test.fixme</code> karena alasan yang tidak berkaitan.","changelog.3e288bea5aec":"<strong>[semua platform]</strong> <code>path:</code> dan <code>parent:</code> mengalokasikan string huruf kecil untuk setiap baris yang di-hydrate, padahal <code>path:</code> sudah memiliki salinan yang di-cache.","changelog.760a29ec7c23":"<strong>[semua platform]</strong> Dialog memiliki dua radius sudut dan tiga bayangan, karena prop <code>style</code> inline milik <code>Modal</code> diam-diam mengalahkan class milik shell sendiri. Prop itu kini hanya untuk metrik, dan upaya untuk melewatinya dilaporkan dalam mode dev.","changelog.adfeb89fa1aa":"<strong>[semua platform]</strong> Dua dari enam pilihan <strong>Tampilan → Format Tampilan → Format ukuran</strong> tidak melakukan apa pun. Skema pengaturan menawarkan <code>b | kb | mb | gb | auto_binary | auto_decimal</code>; <code>formatBytes</code> menerima kosakata lima nilai yang berbeda, dan setiap pemanggil memaksakan cast untuk melewati ketidakcocokan itu, sehingga <code>b</code> dan <code>auto_decimal</code> jatuh ke cabang otomatis biner. Kini hanya ada satu kosakata, <code>auto_decimal</code> menghitung dalam kelipatan seribu, dan setiap pilihan dikunci oleh sebuah tes.","changelog.8fe7422dc893":"<strong>[semua platform]</strong> Menambahkan kolom properti akan gagal diam-diam pada instalasi sungguhan. <code>ColumnId</code> di TypeScript mendapat bentuk <code>prop:&lt;key&gt;</code>; yang di Rust tetap berupa enum tertutup dengan enam varian, sehingga <code>settings_set</code> menolak seluruh patch — bukan hanya kolom itu — dengan <code>unknown variant</code>, dan UI mencatatnya ke log lalu melanjutkan begitu saja. Sisi Rust kini memvalidasi <code>prop:&lt;key&gt;</code> terhadap registri properti, sehingga skemanya tetap tertutup. Tes Playwright yang menambahkan kolom berjalan terhadap mock IPC dan tidak mungkin menangkapnya; kini tiga tes round-trip di <code>settings.rs</code> menangkapnya.","changelog.c4182c80506c":"<strong>[semua platform]</strong> Tidak ada properti teks atau boolean yang dapat dijangkau lewat namespace <code>property:</code>. Pemisah <code>=</code> dari tata bahasanya ikut diteruskan ke nilai, sehingga <code>property:camera-make=canon</code> mencari literal <code>=canon</code> dan tidak mengembalikan apa pun, sementara <code>property:has-alpha=yes</code> menghasilkan galat. Hanya jenis numerik dan tanggal yang pernah membuangnya.","changelog.9d558fa75e7e":"<strong>[semua platform]</strong> Pencocokan properti teks peka huruf besar/kecil ke satu arah untuk nilai non-ASCII apa pun: kata yang dicari dilipat dengan <code>to_ascii_lowercase</code> saat parsing, sedangkan nilai baris dengan <code>to_lowercase</code> Unicode penuh saat pencocokan, sehingga <code>camera-model:MÜLLER</code> tidak pernah menemukan <code>Müller</code>.","changelog.a37ae4d3cefc":"<strong>[semua platform]</strong> Mengurutkan berdasarkan kolom properti menempatkan baris <em>tanpa</em> properti itu di urutan pertama pada urutan menurun, bukan di akhir seperti yang didokumentasikan — komparatornya mengembalikan <code>1</code> yang tetap, yang kemudian dinegasikan oleh pengali arah. Satu halaman berisi baris kosong muncul di tempat yang seharusnya berisi nilai-nilai terbesar.","changelog.1847045d095f":"<strong>[semua platform]</strong> Mengklik chip filter tipe meminta set kolom lama kepada daemon: tata letak otomatis diterapkan setelah perubahan pilihan sudah memicu pencarian, sehingga kolom properti baru tampil kosong sampai ketukan tombol lain yang tidak berkaitan memicu pencarian lagi.","changelog.39af32b4d343":"<strong>[semua platform]</strong> Pengaturan lensa properti tidak bertahan setelah daemon dimulai ulang. Tidak ada yang disimpan secara permanen di sisi daemon, dan hanya <em>penyimpanan</em> pengaturan yang pernah mengirimkannya, sehingga lensa yang dinonaktifkan pengguna — atau yang dinonaktifkan oleh mode privasi — aktif kembali saat daemon dimulai berikutnya sementara UI masih menampilkannya nonaktif. Pengaturan yang dimuat kini dikirim ulang ke daemon saat startup.","changelog.426b2fbb21fa":"<strong>[semua platform]</strong> Menu tambah kolom terbuka di luar layar. Tombol <code>+</code> yang membukanya disematkan di tepi kanan jendela, sehingga <code>left: clientX</code> yang tidak dibatasi menempatkan seluruh menu kecuali secuil melewati tepi itu, tanpa ada yang bisa digulir.","changelog.1be320f46969":"<strong>[semua platform]</strong> Header gambar yang rusak dapat membuat <code>i64</code> overflow saat menghitung megapiksel — <code>0xFFFFFFFF</code> kuadrat melampaui <code>i64::MAX</code> — sehingga build debug panic dan build rilis mendapat angka negatif.","changelog.ffa5958e11a4":"<strong>[semua platform]</strong> <code>property_budget_ms</code> bernilai <code>0</code> yang dikirim lewat wire diam-diam membuat seluruh lensa tidak melakukan apa pun: setiap ekstraksi dimulai dalam keadaan sudah melewati tenggatnya dan setiap berkas kembali tanpa properti dan tanpa galat. Spinner pengaturan memberlakukan nilai minimum; wire tidak. Kini nilainya diberi batas bawah saat diterima.","changelog.065a03b57ec4":"<strong>[semua platform]</strong> Saat ada grup properti yang dinonaktifkan, setiap cache hit menyalin-dalam (deep copy) seluruh peta properti — alokasi per baris yang justru hendak dihindari oleh <code>Arc</code> bersama, dan harganya dibayar pada setiap baris dari setiap kueri selama pengaturan itu berlaku. Tampilan yang difilter kini di-memoize per entri dan dibuang saat himpunannya berubah.","changelog.1f99920ac00d":"<strong>[semua platform]</strong> Penulisan ulang <code>length:</code> menelusuri dan menyalin-dalam seluruh AST kueri pada setiap ketukan tombol di setiap pencarian, termasuk pencarian yang sama sekali tidak memuat <code>length:</code>, karena daemon selalu memasang penyedia properti.","changelog.8f6fb4eb7f42":"Keamanan","changelog.1a1f843d10c5":"<strong>[Windows]</strong> Target sebuah shortcut adalah byte dari berkas yang tidak tepercaya, dan menjawab <code>broken-link:</code> berarti memanggil <code>Path::exists</code> padanya. Di Windows, itu menyerahkan path UNC ke SMB redirector, yang menyambung ke host yang disebutkan dan menyodorkan kredensial NTLM milik pengguna yang sedang login — primitif klasik forced authentication lewat shell link, dan pengindeksan saja sudah cukup untuk memicunya, satu handshake per berkas, tanpa ada yang diklik. Cukup dengan menaruh folder berisi berkas <code>.lnk</code> yang menunjuk ke <code>\\attacker\\share\\x</code> ke direktori mana pun yang dipantau. Target kini diperiksa apakah berbentuk UNC atau URL sebelum di-resolve, dan target jarak jauh membuat <code>broken-link</code> tetap tidak diisi alih-alih diperiksa. Pelindung yang sama mencakup target symlink, yang datang dengan cara yang sama di dalam arsip apa pun.","changelog.c599b83df9e1":"<strong>[Windows]</strong> Verifikasi Authenticode berjalan dengan <code>dwProvFlags: 0</code>. <code>WTD_REVOKE_NONE</code> menekan CRL dan OCSP tetapi tidak menekan pengambilan AIA oleh chain engine, sehingga biner yang ditandatangani sendiri dengan sertifikat yang menyebut <code>http://attacker/&lt;unique&gt;.cer</code> akan mengubah pengindeksan menjadi tanda terima baca — sudah tiba, IP ini, waktu ini — dari daemon yang panel Privasinya menjanjikan tidak ada permintaan keluar. Kini dikunci ke <code>WTD_CACHE_ONLY_URL_RETRIEVAL | WTD_REVOCATION_CHECK_NONE</code>.","changelog.4118fb4fed0e":"Dihapus","changelog.7e47a128e1ba":"<strong>[semua platform]</strong> Pengaturan <strong>Hapus volume luring secara otomatis</strong>. Pengaturan ini tidak menggerakkan apa pun — tidak ada kode yang pernah membacanya — dan yang dijelaskannya justru kebalikan dari perilaku yang dirilis: volume yang dicabut sengaja <em>dipertahankan</em> sebagai katalog luring agar barisnya tetap dapat dicari dan diberi lencana. Menerapkannya seperti yang tertulis, dengan bawaan aktif, akan menghapus indeks setiap drive yang dicabut.","changelog.706f136720e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.2</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">Rotasi kunci updater dan perbaikan CI</span>","changelog.31b4f34d5ada":"Aplikasi yang sama dengan <code>0.23.1</code>, yang sudah diberi tag tetapi rilisnya diganti alih-alih diterbitkan. Semua yang ada di bagian <code>0.23.1</code> di bawah ikut dirilis di sini; berikut ini adalah perubahan di atasnya.","changelog.965ce76814aa":"<strong>Kunci penandatanganan updater baru.</strong> Rilis hingga <code>0.23.1</code> ditandatangani dengan <code>9F291C936CFA28B7</code>, yang separuh privatnya hanya ada sebagai secret repositori GitHub. Secret repositori tidak dapat dibaca kembali, sehingga kunci itu tidak dapat disalin, dipindahkan, atau dipulihkan — dan kini kunci itu sudah hilang. Rilis mulai <code>0.23.2</code> ditandatangani dengan <code>E5035E2194EB7E04</code>, yang separuh privat, kata sandi, dan separuh publiknya disimpan bersama di luar GitHub.","changelog.926a99810869":"<strong>Ini merusak updater pada setiap instalasi <code>0.23.1</code> atau yang lebih lama</strong>: biner lama memverifikasi terhadap kunci publik yang tidak lagi menandatangani apa pun, sehingga pembaruan akan gagal dalam verifikasi tanda tangan alih-alih terpasang. Pasang ulang dari unduhan di bawah. Tidak ada instalasi yang diketahui terdampak — jumlah unduhan pada setiap rilis sebelumnya sesuai dengan pemeriksaan tautan rutin.","changelog.95ee6438be83":"<strong><code>apt-get update</code> dapat membuat build Linux macet tanpa batas waktu.</strong> Mirror Ubuntu yang diutamakan image runner, <code>azure.archive.ubuntu.com</code>, tidak mengembalikan apa pun untuk seluruh set indeks jammy selama beberapa jam, dan karena tidak ada timeout yang dikonfigurasi, langkah itu menunggu alih-alih gagal — hingga satu jam dibandingkan baseline 72 detik, sebanyak empat kali, masing-masing perlu dibatalkan secara manual. Build kini memakai <code>archive.ubuntu.com</code>, membatasi langkah itu pada sepuluh menit, dan mencoba ulang. Langkah yang sama kemudian berjalan dalam 41 detik.","changelog.7f5127beca31":"<strong><code>workflow_dispatch</code> pada workflow rilis membangun tree yang salah.</strong> Workflow ini menerima tag sebagai input dan merupakan cara terdokumentasi untuk membangun ulang sebuah rilis, tetapi langkah checkout-nya tidak memiliki <code>ref</code>, sehingga yang di-checkout adalah branch mana pun tempat workflow itu dijalankan, sementara artefaknya dinamai sesuai tag input.","changelog.e492554f1e26":"<strong>Tes anggaran waktu nyata (wall-clock) berjalan di bawah beban paralel penuh di CI.</strong> <code>scripts/ci-local.mjs</code> sudah diubah agar menjalankannya sendirian — karena model satu-proses-per-tes milik nextest membuat mesin terus terbebani dan asersinya jadi mengukur beban itu — tetapi CI tetap menjalankannya bersama semua tes lain, sehingga gate lokal tidak lagi memprediksi CI justru untuk tes yang paling sulit direproduksi. CI kini memisahkan langkah nextest-nya dengan cara yang sama, dan batas atasnya dilonggarkan pada runner bersama, tempat pengukuran itu kurang bermakna.","changelog.17a56bd3bbd4":"<strong>Dua galat clippy khusus OS</strong> di <code>shell_actions/macos.rs</code> dan <code>shell_actions/linux.rs</code>, yang tidak dikompilasi oleh build Windows mana pun dan baru pertama kali dijangkau oleh gate lint <code>src-tauri</code> pada putaran ini.","changelog.c205924de0fe":"Dokumentasi","changelog.9c50b38011d4":"<code>README.md</code> mengiklankan <code>v0.19.84</code> sebagai rilis pertama yang akan datang, padahal sudah empat rilis berlalu, dan menautkan lima dokumen yang bukan bagian dari repositori ini.","changelog.4395f6d7c73f":"Ukuran unduhan di situs masih milik <code>0.23.0</code>, terbawa bersama tautannya.","changelog.b2bfece1a5c5":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.1</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">Fondasi Build 4 · serah terima Build 3, dituntaskan</span>","changelog.957188896a81":"Fondasi Build 4 — menuntaskan serah terima Build 3","changelog.4dce861a35f4":"Semua yang dibiarkan terbuka oleh serah terima sebelumnya setelah v0.23.0, ditambah tiga bug yang ditemukan selama mengerjakannya. Tidak ada fitur baru; ini adalah putaran pembersihan yang menjadi landasan pekerjaan lensa properti Build 4.","changelog.116b07733767":"<strong>Menu <code>Search →</code> tidak melakukan apa pun.</strong> SRC-M23 mengirim ketujuh flag mode pencocokan dari <code>query.ts</code> dan mengajari <code>QueryRunParams</code> milik daemon untuk membaca ketujuhnya — tetapi perintah Tauri di antara keduanya tidak mendeklarasikan satu pun, dan Tauri membuang argumen invoke yang tidak disebutkan oleh perintah, secara diam-diam. Setiap flag tiba di eksekutor sebagai nilai bawaan <code>serde</code>-nya, sehingga Cocokkan Huruf Besar/Kecil, Cocokkan Seluruh Kata, Cocokkan Path, Cocokkan Diakritik, Cocokkan fonetik, Abaikan tanda baca, dan Abaikan spasi masing-masing hanya memindahkan tanda centang tanpa mengubah hal lain. <code>commands/query.rs</code> kini memiliki tempat pendaratan <code>QuerySearchOpts</code>, dan <code>tests/unit/query_wire.test.ts</code> mengunci nama argumen di kedua sisi.","changelog.3258356b0cdb":"<strong>Cocokkan Huruf Besar/Kecil salah ke dua arah.</strong> Saat aktif, kueri huruf besar tidak mengembalikan <em>apa pun</em> dan kueri huruf kecil tetap cocok tanpa memedulikan huruf besar/kecil. Indeks nama menyimpan kunci dalam huruf kecil, sehingga pra-filter kandidat tidak memiliki teks berhuruf asli untuk diuji dan menolak setiap baris sebelum hydration sempat melihat nama aslinya. Hal ini sudah diketahui dan ditunda — sebuah tes menegaskan perilaku yang rusak itu dan merujuk pada perubahan indeks di Fase 13. Ternyata tidak perlu: Cocokkan Huruf Besar/Kecil kini melewati pra-filter, persis seperti yang sudah dilakukan Cocokkan Path, dan predikatnya dijalankan terhadap nama asli baris. Seed trigram tetap berlaku, karena dibangun dari kata yang dicari dalam huruf kecil sehingga memilih superset dari jawaban yang peka huruf, yang berarti biayanya adalah satu hydration, bukan pemindaian penuh. <code>child:</code>, <code>name^:</code>, dan <code>name$:</code> dialihkan dengan cara yang sama.","changelog.3fdb374f585c":"<strong>Tidak ada pengaturan yang tersimpan.</strong> <code>custom_commands</code> memiliki nilai bawaan dan seluruh panel Pengaturan → Perintah khusus, tetapi tidak tercantum di <code>ALLOWED_PATCH_KEYS</code>. <code>settings_set</code> menolak sebuah patch pada kunci tingkat atas pertama yang tidak dikenalnya, dan <code>flush()</code> milik UI mengirim seluruh state — yang selalu memuat <code>custom_commands</code> — sehingga setiap penyimpanan gagal dan hanya berakhir sebagai peringatan di konsol. Allowlist kini diturunkan dari skema (<code>allowed_patch_keys()</code>), dan dari situlah celah ini terungkap.","changelog.be64658b8045":"<strong><code>child:</code> / <code>name^:</code> / <code>name$:</code> memberi jawaban berbeda tergantung sisa kuerinya.</strong> Tahap indeks nama menjalankannya melalui seluruh tangga normalisasi, sedangkan tahap hydration membandingkan string mentah, dan kedua tahap berjalan pada setiap kueri — sehingga menambahkan pengubah apa pun yang memaksa hydration menyerahkan keputusan kepada tahap yang lebih ketat. <code>name^:cafe</code> menemukan <code>café-notes.txt</code> jika berdiri sendiri, dan berhenti menemukannya begitu <code>size:</code> ditambahkan.","changelog.35d326e420f1":"<strong>Escape tidak pernah menutup dialog.</strong> Handler-nya terpasang pada backdrop, sebuah div <code>role=&quot;presentation&quot;</code> tanpa tabindex, sehingga tidak dapat menerima keydown — dan panelnya toh menghentikan propagasi. Kini handler itu berada di <code>window</code>, di dalam <code>&lt;Modal&gt;</code> bersama.","changelog.4f4a3883a9bb":"<strong>Pengurutan alami hanya berlaku di sisi klien.</strong> <code>SortSpec.natural</code> bernilai bawaan <code>true</code> dan tidak pernah disetel oleh apa pun, sehingga Pengaturan → Hasil → <em>Pengurutan alami</em> mematikan komparator UI tetapi membiarkan <code>freally search --json</code> tetap terurut secara alami. Pengaturan ini kini ikut dikirim lewat wire.","changelog.1eb006c07967":"<strong><code>src-tauri</code> tidak di-lint.</strong> Folder ini dikecualikan dari workspace, sehingga <code>cargo clippy --workspace</code> tidak pernah melihatnya dan tiga galat gagal secara diam-diam. Kini CI memiliki langkah tersendiri untuk manifest itu. Perintah <code>log_event</code> yang mati — didokumentasikan sebagai jembatan debug TS→Rust tetapi tidak pernah didaftarkan, sehingga setiap panggilan ke sana gagal — dihapus.","changelog.17d4993eb122":"<strong>Perintah khusus kini dibatasi dan diperiksa bentuknya.</strong> <code>custom_commands</code> adalah satu-satunya pengaturan yang nilainya menyebut <em>program yang akan dijalankan</em>, dan pengaturan ini sampai ke <code>settings_set</code> tanpa validasi sama sekali — karena hingga build ini pengaturan itu memang tidak pernah sampai ke <code>settings_set</code> (lihat di atas). Kini ia memiliki jenis batas yang sama seperti setiap bidang tak terbatas lainnya — pada jumlah perintah, pada panjang <code>id</code>/<code>name</code>/<code>program</code>, dan pada kedua daftar string-nya, <code>args</code> dan <code>extensions</code>.","changelog.efc94af8b3c4":"<strong>Mengimpor berkas pengaturan tidak lagi memasang peluncur secara diam-diam.</strong> Pengaturan → Cadangkan → <em>Impor pengaturan</em> membaca JSON yang diberikan pengguna langsung ke penyimpanan pengaturan. Karena itu, &quot;preset Freally&quot; yang dibagikan dapat menambahkan perintah khusus — sebuah program untuk dijalankan — ke menu konteks setiap hasil, dengan label pilihan pembuatnya, tanpa pemberitahuan apa pun. Impor kini menyebutkan program-program tersebut dan meminta konfirmasi; jika ditolak, semua yang lain tetap diimpor. <code>docs/SECURITY.md</code> menyatakan batas yang tersisa dengan gamblang: apa pun yang dapat menulis pengaturan dapat menyebut sebuah program.","changelog.442aded87a55":"Kinerja","changelog.ee0c64c3999a":"<strong>Abaikan tanda baca / Abaikan spasi tidak lagi memindai seluruh indeks.</strong> Mode-mode itu menulis ulang teks sebelum membandingkan, sehingga trigram dari nama mentah tidak lagi menggambarkan kata yang dicari dan eksekutor terpaksa menelusuri setiap nama. Kini seed diambil dari set posting paralel yang dibangun atas nama-nama yang sudah dibuang tanda baca dan spasinya. Dibangun secara malas pada pemakaian pertama dan dipelihara secara inkremental sejak itu, sehingga pengguna yang tidak pernah mengaktifkan salah satu mode tersebut tidak pernah menanggung biayanya.","changelog.2bfd60f4ad05":"<strong>Satu tangga normalisasi alih-alih tiga.</strong> <code>substring_match</code>, <code>anchored_match</code>, dan <code>literal_match</code> masing-masing menjalankan case-fold → strip-diacritics → strip-ignored dan sudah mulai berbeda satu sama lain. Kini ketiganya memakai <code>normalized</code> bersama, yang meminjam alih-alih mengalokasikan saat sebuah anak tangga tidak punya pekerjaan — kasus umum berupa nama ASCII huruf kecil dalam mode bawaan kini tidak mengalokasikan apa pun per baris.","changelog.40253ba25a46":"<strong>Kata yang dicari dinormalisasi sekali per kueri, bukan sekali per baris kandidat.</strong>","changelog.23f1c76bd888":"Pembagian bucket waveform membawa batas bucket-nya alih-alih melakukan pembagian per frame yang didekode (~8 M pembagian pada trek stereo tiga menit); buku catatan izin menghapus duplikat lewat <code>HashSet</code> alih-alih pemindaian linear; dan merekam pencarian terbaru tidak lagi melakukan spread dan menugaskan ulang root pengaturan berisi ~180 kunci pada setiap ketukan tombol.","changelog.64ff3a4bbdfd":"<strong>Freally Central dihapus</strong> — tree yang di-vendor, stanza <code>.gitmodules</code> yang menyebut submodule yang tidak pernah terdaftar di git, island React beserta lima dependensinya, dialog dan item menu <em>Aplikasi Freally lainnya</em>, string lokalnya, dan entrinya di situs dokumentasi.","changelog.36e12a600874":"<strong><code>&lt;Modal&gt;</code> bersama</strong> menggantikan ritual backdrop / panel / Escape / <code>tabindex</code> yang ditulis ulang sendiri-sendiri oleh tujuh dialog, dan menuntaskan keenam peringatan <code>a11y_interactive_supports_focus</code> yang tersisa. <code>HitViewer</code>, <code>QuickLook</code>, <code>RegexBuilder</code>, dan wisaya jalankan pertama sengaja mempertahankan shell masing-masing — backdrop bersaudara, navigasi tombol panah, popover, dan gerbang yang tidak dapat ditutup bukanlah komponen yang sama.","changelog.05849c3f2c94":"<code>portable::open_log</code>, <code>service::scan</code>, <code>app_data_root</code>, dan <code>resultsStore.hitById</code> menggantikan salinan-salinan duplikatnya.","changelog.fe8ee15bb86d":"CI","changelog.44ad89dc0cf1":"<code>cargo nextest</code> menggantikan <code>cargo test</code>: sebagian besar dari 760 tes membangun indeks Tantivy sendiri, dan satu proses per tes menjauhkan mereka dari lock satu sama lain. Diukur dalam kondisi hangat di mesin pengembangan, 100s → 37s.","changelog.2892b412468b":"Sebuah grup tes nextest membatasi paket yang membangun indeks pada empat proses bersamaan. Tanpanya, konkurensi tambahan mengubah race condition Windows Defender / Tantivy <code>Access is denied (os error 5)</code> yang sudah dikenal dari sesekali menjadi dapat direproduksi — dua run berturut-turut gagal pada tiga tes berbeda. Batas itu memakan ~2s dan suite tetap berjalan dalam seperlima waktu <code>cargo test</code>.","changelog.f600da3213ca":"Run yang sudah digantikan pada sebuah branch dibatalkan; <code>main</code> dikecualikan agar tetap mengisi cache yang dipulihkan oleh setiap branch.","changelog.6811b6eaa5cb":"<code>CARGO_INCREMENTAL=0</code>, cache hanya ditulis dari <code>main</code>, <code>--locked</code> di semua tempat, instalasi pnpm yang dibekukan, dan gate yang tidak bergantung pada OS (<code>i18n-lint</code>, doctest) pada satu runner alih-alih tiga.","changelog.8266aee5f502":"<code>scripts/ci-local.mjs</code> mendapat gate <code>src-tauri</code> yang sebelumnya tidak ada dan menjalankan jalur Rust dan UI-nya secara bersamaan: pekerjaan 133s selesai dalam 89s.","changelog.b9b12625c2fd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.0</span><time class=\"release__date\" datetime=\"2026-08-03\">2026-08-03</time></span><span class=\"release__title\">Build 3 · Gerbang stabil Must-Have, irisan 3 dari 3</span>","changelog.c5819508ac2c":"Build terakhir dari tiga build Must-Have: SRC-M17 … SRC-M24. Dirilis sebagai v0.23.0, tag <strong>stabil</strong>.","changelog.7c2c8aacfd91":"<strong>SRC-M17 — mode portabel.</strong> <code>freally --portable</code>, atau berkas <code>portable.flag</code> kosong di samping biner, menyimpan indeks, pengaturan, markah, kursor journal, dan log di folder <code>Data/</code> di sebelah berkas eksekusi, dan mencegah aplikasi mendaftarkan apa pun ke OS. Ketiga biner menerima sakelar ini; berkas flag itulah yang membuat zip atau AppImage yang diklik ganda menjadi portabel tanpa baris perintah sama sekali.","changelog.c081711c3fde":"Tata letaknya berada di <code>freally_rpc::portable</code> — satu-satunya crate yang sudah menjadi dependensi shell Tauri, daemon, dan CLI sekaligus.","changelog.260a841f6090":"Hal-hal yang sengaja <em>tidak</em> dilakukan mode portabel, masing-masing karena alasan konkret, bukan demi kerapian:","changelog.e53f7037be43":"<strong>Tidak ada service, plist launchd, atau unit systemd.</strong> <code>freally-indexd install</code> / <code>uninstall</code> / <code>service</code> semuanya menolak dalam mode portabel. Masing-masing menulis registrasi yang bertahan lebih lama daripada flashdisk USB dan menunjuk ke path yang tidak akan ada pada boot berikutnya. <code>uninstall</code> ditolak karena alasan sebaliknya: salinan portabel tidak pernah mendaftarkan apa pun, sehingga membiarkannya lolos akan menghapus registrasi salinan yang <em>terpasang</em> di host.","changelog.d1f534b3e627":"<strong>Tidak ada registrasi skema <code>freally://</code>.</strong> Registrasi itu menulis handler tingkat mesin yang menunjuk ke path berkas eksekusi saat ini; cabut flashdisknya dan setiap tautan <code>freally://</code> di mesin itu menggantung. Listener di dalam proses tetap berjalan, sehingga instance portabel tetap menangani URL yang diserahkan kepadanya — hanya saja ia tidak mengklaim skema tersebut.","changelog.6320d3fbbef5":"<strong>Tidak ada updater otomatis.</strong> Updater menerapkan sebuah <em>installer</em>. Mengarahkannya ke flashdisk akan memasang aplikasi ke mesin host, yang justru satu-satunya hal yang dihindari pengguna portabel. Instalasi portabel diperbarui dengan mengganti foldernya.","changelog.01ed92501ea3":"<strong>Tidak mengambil alih service Windows.</strong> Service tersebut memiliki indeks terpasang di bawah <code>%PROGRAMDATA%</code>; peluncuran portabel yang tersambung ke sana akan diam-diam mencari di indeks milik host dan menulis aktivitas flashdisk ke dalamnya.","changelog.9f519044c9bf":"<strong>Tidak ada <code>taskkill</code> lintas instance.</strong> Penegakan instance tunggal mematikan proses berdasarkan nama image. Flashdisk yang dicolokkan ke mesin yang sudah menjalankan Freally akan mematikan aplikasi yang sedang dipakai pengguna.","changelog.f0f408322071":"Dua bagian state perlu dialihkan secara eksplisit karena tidak bergantung pada root indeks:","changelog.ada349238a7a":"<strong>Kursor journal.</strong> Setiap subscriber OS secara bawaan memakai direktori per pengguna miliknya sendiri, sehingga instalasi portabel akan meninggalkan kursor di setiap mesin tempat ia dicolokkan. Kini kursor disimpan di <code>Data/cursors</code>.","changelog.8ea42f81060c":"<strong>Socket RPC, yang sengaja tidak disimpan di flashdisk.</strong> Flashdisk biasanya berformat FAT32 atau exFAT — sistem berkas yang sama sekali tidak dapat menampung Unix domain socket, dan tidak memiliki bit izin untuk pemeriksaan 0600 + peer-uid yang menjadi andalan transport. Socket itu berada di direktori temp milik host dengan nama yang diturunkan dari root portabel, sehingga instance portabel tidak pernah bertabrakan dengan instance terpasang atau dengan flashdisk kedua, dan skema autentikasinya tidak berubah.","changelog.f576d6d3c2e0":"Log dipindahkan karena biner yang diklik ganda tidak memiliki konsol untuk diwarisi: kedua proses menulis ke <code>Data/logs/</code>, dan beralih ke konsol jika berkas itu tidak dapat dibuka, alih-alih kehilangan diagnostik yang justru akan menjelaskan penyebabnya.","changelog.2af97df221d3":"Di macOS, <code>Data/</code> ditempatkan di samping <code>Freally.app</code>, bukan di dalamnya — menulis data pengguna ke dalam bundle merusak code signing dan langsung gagal pada mount yang hanya-baca.","changelog.8b231cae5059":"<strong>Juga dalam perubahan ini: panel Tentang melaporkan versi yang salah.</strong> Panel itu membawa <code>0.19.84</code> yang di-hardcode dan sudah tertinggal tiga rilis dari yang dirilis. Kini panel membaca versi dari proses yang sedang berjalan lewat perintah baru <code>app_environment</code>, yang juga melaporkan apakah ini instalasi portabel dan folder tempatnya menulis — sehingga pengguna yang mencolokkan flashdisk ke mesin orang lain dapat memastikan di aplikasi bahwa tidak ada yang ditulis ke host.","changelog.9ee660246eb6":"Smoke: <code>tests/smoke/build_03_portable.rs</code> menyiapkan salinan biner daemon yang asli di direktori sementara (mode portabel didefinisikan relatif terhadap berkas eksekusi, sehingga mengujinya di tempat akan membuat setiap biner lain di workspace menjadi portabel selama sisa run) dan membuktikan berkas flag, sakelarnya, ketiga penolakan registrasi, serta bahwa daemon portabel menulis indeks dan log-nya ke <code>Data/</code> dan tidak ke tempat lain.","changelog.b20d6ec3f044":"<strong>SRC-M24 — pengurutan alami.</strong> Deret angka di dalam nama dibaca sebagai bilangan, sehingga <code>file2</code> muncul sebelum <code>file10</code> dan <code>v1.9</code> sebelum <code>v1.10</code>. Aktif secara bawaan, dengan opsi untuk menonaktifkannya di Pengaturan → Hasil → <em>Pengurutan alami</em>.","changelog.88d62d00604a":"Ini berlaku untuk setiap kolom string — nama, path, tipe, dan ekstensi — bukan hanya nama, sehingga &quot;urutkan secara alami&quot; tidak diam-diam berarti &quot;urutkan kolom nama secara alami&quot;.","changelog.52f34cd037df":"Ada dua komparator karena ada dua pengurutan: daemon mengurutkan apa yang dikembalikannya (<code>crates/freally-query/src/natural.rs</code>) dan daftar hasil mengurutkan ulang di sisi klien (<code>apps/freally-ui/src/lib/util/natural.ts</code>). Keduanya sengaja tidak identik — UI menjalankan deret non-angka melalui <code>localeCompare</code> agar aksen dan huruf besar/kecil tetap berperilaku seperti sebelumnya, sedangkan daemon hanya pernah melihat nama dalam huruf kecil — sehingga sebuah vektor kasus bersama mengunci perilaku numerik yang harus mereka sepakati, diperiksa dari kedua sisi.","changelog.4ac049addd1f":"Detail yang layak dinyatakan, karena masing-masing adalah cara untuk membuat ini salah:","changelog.7548bb140901":"<strong>Deret angka dibandingkan tanpa di-parse.</strong> Parsing dibatasi pada <code>u64</code> (atau 2^53 di JS); deret 30 digit dalam nama berkas memang tidak lazim tetapi bukan tidak valid, dan dua deret kelewat panjang yang berbeda akan dianggap sama. Membandingkan jumlah digit signifikan lalu digit-digitnya bersifat tepat pada panjang berapa pun.","changelog.b4e5975dde5b":"<strong>Padding nol adalah penentu seri pilihan terakhir.</strong> <code>file07</code> dan <code>file7</code> adalah bilangan yang sama, sehingga padding hanya menentukan saat tidak ada hal lain yang menentukan — memutuskan berdasarkan padding begitu ia muncul akan membuat <code>file07b</code> mengalahkan <code>file7a</code>.","changelog.b682aa249886":"<strong>UI membandingkan bentangan non-angka hanya sejauh kedua sisi memilikinya.</strong> Sebuah deret dapat terpotong oleh digit di satu sisi tetapi tidak di sisi lain — <code>img.png</code> melawan <code>img1.png</code> menghasilkan deret sepanjang 7 dan 3 — dan membandingkan keduanya secara utuh akan memutuskan berdasarkan panjang alih-alih <code>.</code> melawan <code>1</code>, yang membuat <code>img.png</code> diurutkan paling akhir. Tertangkap oleh vektor bersama.","changelog.efabda690420":"<strong>String tanpa angka tetap melewati <code>localeCompare</code> secara utuh</strong>, sehingga kasus umum mempertahankan collation yang persis sama seperti sebelumnya.","changelog.e3d8b9588796":"<strong>Kolom path adalah satu-satunya tempat sakelar ini mengubah lebih dari sekadar angka.</strong> Saat pengurutan alami nonaktif, kolom ini tetap memakai <code>PathBuf::cmp</code>, yang mengurutkan per komponen, bukan per byte; pengurutan alami harus membaca path sebagai teks agar bisa melihat deret angka sama sekali.","changelog.52750ba0909a":"<strong>Berkas tanpa ekstensi tetap diurutkan paling awal</strong>, seperti yang dilakukan <code>Option::cmp</code>.","changelog.67df3bc8e4ae":"Deskripsi fitur meminta urutan itu &quot;dipatuhi oleh indeks fast-sort&quot;. Tidak ada indeks seperti itu untuk dipatuhi: pengurutan terjadi di <code>sort_rows</code> atas baris kandidat yang sudah dimaterialisasi oleh eksekutor, dan saat ini tidak ada indeks pemercepat pengurutan di penyimpanan. Membangunnya adalah pekerjaan berskala SRC-N, jadi hal ini dinyatakan alih-alih dilewati diam-diam.","changelog.bd0993897678":"Smoke: <code>tests/smoke/build_03_natural_sort.rs</code> mengindeks nama-nama yang urutan byte dan urutan alaminya berbeda pada setiap entri, dan mengunci nilai bawaan, opsi penonaktifan, urutan menurun, kolom path, serta bahwa kolom numerik dibiarkan apa adanya.","changelog.b190e0af1450":"<strong>SRC-M23 — abaikan tanda baca, abaikan spasi, dan pencocokan berjangkar.</strong> Dua sakelar baru di bawah <code>Search →</code> (<code>Ignore Punctuation</code>, <code>Ignore Whitespace</code>) dan dua pengubah DSL baru, <code>name^:report</code> (diawali dengan) dan <code>name$:final</code> (diakhiri dengan).","changelog.e35e30b09372":"<strong>Keempat sakelar pencocokan yang sudah ada kini benar-benar melakukan sesuatu.</strong> Hingga Build 2, hanya <code>match_phonetic</code> yang dikirim lewat wire: <code>Match Case</code>, <code>Match Whole Word</code>, <code>Match Path</code>, dan <code>Match Diacritics</code> memindahkan tanda centang tanpa mengubah apa pun, karena <code>query.run</code> hanya mengirim satu flag itu dan daemon membangun <code>MatchMode</code> dari <code>Default</code>. Eksekutor sebenarnya sudah mematuhi kelimanya sejak awal. Kini set lengkapnya dikirim dan dibaca.","changelog.827fa9647b52":"<strong>Bug terkait, ditemukan saat menyambungkannya: <code>Match CJK Phonetics</code> tidak pernah tersimpan.</strong> <code>settings_set</code> menserialisasi ulang struct pengaturan lalu mem-parse hasilnya kembali, dan <code>SearchOpts</code> di Rust tidak memiliki bidang <code>match_phonetic</code> — sehingga flag itu dibuang pada <em>setiap penulisan pengaturan</em>. Build 2 hanya menambahkannya di sisi TypeScript. Ketiga flag baru kini juga ada di struct Rust.","changelog.32c9128fe95e":"Catatan implementasi:","changelog.c4202016a76a":"<strong>Kedua sisi dibersihkan, bukan hanya targetnya.</strong> Membersihkan nama saja akan membuat <code>foobar</code> menemukan <code>foo-bar</code> sementara <code>foo-bar</code> tidak dapat menemukan <code>foobar</code> — itu terbaca sebagai bug, bukan sebagai mode pencocokan.","changelog.09e51f90e5b3":"<strong>Seed trigram dibuang saat sebuah mode menulis ulang teks.</strong> <code>foo-bar</code> mengindeks trigram <code>foo</code>, <code>oo-</code>, <code>o-b</code>, <code>-ba</code>, <code>bar</code>; kata yang dicari <code>foobar</code> meminta <code>oob</code> dan <code>oba</code>, yang tidak dimiliki baris itu, sehingga seeding tidak akan mengembalikan <em>apa pun sama sekali</em>, secara diam-diam. Eksekutor beralih ke pemindaian penuh, kompromi yang sama yang sudah diambil <code>match_path</code>. Flag-flag ini nonaktif secara bawaan, jadi tidak ada yang menanggung biayanya tanpa memintanya.","changelog.24e406c88eff":"<strong>Seluruh kata diabaikan selama mode pembersihan aktif</strong>, karena menghapus pemisah berarti menghapus batas kata yang mendefinisikannya.","changelog.c0189eb66ffc":"<strong><code>name:foo-bar</code> berperilaku seperti istilah polos <code>foo-bar</code>.</strong> Keduanya adalah kueri yang sama yang ditulis dengan dua cara, sehingga jalur <code>name:</code>/<code>child:</code> juga mematuhi mode pembersihan, bukan hanya jalur istilah literal.","changelog.5d357f0cb708":"<strong>Tanda baca mengikuti definisi Unicode, bukan daftar ASCII</strong>, sehingga <code>’</code> dan <code>–</code> ikut dibuang bersama <code>'</code> dan <code>-</code>.","changelog.8b12742c48b5":"Untuk pengubah berjangkar, <code>^</code> dan <code>$</code> diizinkan khusus untuk tepat dua kunci alih-alih ditambahkan ke himpunan karakter kunci umum — mekanisme yang sama yang dipakai kunci bertanda hubung, dan dengan alasan Aturan Tetap #8 yang sama: memperluas himpunan karakter akan mengubah <code>x^2:3</code> dan <code>total$:5</code> dari istilah literal menjadi galat parse yang keras. Keduanya ditolak di bawah <code>--strict-everything</code>, karena Everything milik voidtools tidak memiliki sintaks berjangkar. <code>name$:</code> berjangkar pada seluruh nama termasuk ekstensinya, sehingga <code>name$:report</code> tidak cocok dengan <code>report.txt</code>.","changelog.573c5bc71314":"Mendaftarkan pengubah baru menyentuh lebih dari sekadar parser, dan melewatkan salah satunya membuatnya hanya setengah berfungsi: varian AST, empat titik planner/evaluator di <code>exec.rs</code>, <code>optimizer::selectivity_rank</code> (pencocokan berjangkar lebih sempit daripada substring yang tersirat di dalamnya, sehingga peringkatnya di depan <code>child:</code>), daftar mode ketat di <em>dua</em> tempat, himpunan karakter kunci duplikat di <code>report.rs</code> — lewatkan yang satu itu dan kueri berjalan dengan benar sementara bilah pencarian mewarnainya sebagai literal — ditambah <code>modifier_name</code>, <code>ModifierDetail</code>, dan tabel <code>MODIFIER_KEYS</code> yang diiklankan dan dibaca oleh pelengkapan CLI.","changelog.5b298995d56c":"Yang terakhir itu memiliki celah yang patut dicatat: <code>every_advertised_modifier_is_known_to_the_parser</code> tidak mungkin menangkap kunci bersimbol yang hilang, karena kunci di luar himpunan karakter turun derajat menjadi <em>literal</em> alih-alih menjadi <code>UnknownModifier</code>, sehingga tesnya lolos dalam kedua kasus. Sebuah asersi positif ditambahkan.","changelog.7cd3e842fd15":"<strong>SRC-M20 — pembuat regex dan penguji langsung.</strong> Sebuah popover di samping sakelar regex baru di bilah pencarian: kolom pola, galat kompilasi dari mesin itu sendiri, contekan bercita rasa Rust, dan penyorotan langsung atas apa yang dicocokkan pola pada 50 nama hasil teratas saat ini, dengan hitungan &quot;3 dari 50 nama yang tampil cocok&quot;. Menerapkan pola akan menulis ulang kueri menjadi <code>regex:&lt;pattern&gt;</code> dan menyalakan Aktifkan Regex, sehingga menu tidak pernah bertentangan dengan apa yang dilakukan kueri.","changelog.fc32c438e9b3":"Pil galat parse dan hover AST sudah memvalidasi kueri yang telah Anda <em>tulis</em>; tidak ada yang membantu Anda menulis polanya. Di situlah waktu terbuang — Anda mengetik sesuatu, menjalankannya, tidak mendapat apa-apa, dan tidak dapat membedakan apakah polanya salah atau berkasnya memang tidak ada. Popover ini menampilkan kedua jawaban sekaligus.","changelog.8f5e99706420":"<strong>Pengujian dilakukan di Rust, dengan sengaja.</strong> Implementasi yang paling jelas memvalidasi dengan <code>RegExp</code> milik webview, dan itu akan salah tepat pada kasus-kasus yang ditemui orang yang sedang menyusun pola: eksekutor kueri menjalankan crate <code>regex</code>, yang tidak memiliki referensi balik maupun lookaround, memperlakukan <code>\\d</code> secara sadar-Unicode, dan menerima <code>(?i)</code> secara inline, bukan sebagai flag di akhir. Pembuat yang berbasis <code>RegExp</code> akan dengan senang hati menerima <code>(?&lt;=foo)bar</code> lalu gagal saat kueri dijalankan. <code>regex_test</code> mengompilasi dengan mesin yang sama, sehingga &quot;cocok di sini&quot; berarti &quot;akan cocok di sana&quot; — ada unit test yang memastikan lookaround ditolak, tepat karena alasan ini.","changelog.6e60e7b42f67":"Keputusan yang lebih kecil, masing-masing menjaga sesuatu yang nyata: span dikembalikan sebagai offset <strong>karakter</strong>, karena UI memotongnya dengan indeks string JavaScript dan offset byte akan membelah nama multi-byte menjadi dua; kecocokan selebar nol dibuang, karena <code>a*</code> cocok di setiap posisi dan menyorot ketiadaan di setiap posisi hanyalah gangguan; pola kosong sama sekali tidak melaporkan galat alih-alih memunculkannya pada ketukan pertama; dan batas ukuran automaton terkompilasi dikunci pada 256 KB alih-alih bawaan crate sebesar 10 MB. Mesinnya berbasis automaton hingga, sehingga pola jahat tidak dapat melakukan backtracking eksponensial — batas ukuran adalah satu-satunya tuas yang penting, dan tuas itu sudah disetel.","changelog.11270a28687b":"<strong>SRC-M19 — Lihat Cepat dengan Spasi.</strong> Spasi pada sebuah hasil membuka pratinjau modal berukuran besar; tombol panah menelusuri himpunan hasil sementara pratinjau tetap terbuka, dan Spasi atau Escape menutupnya. Header-nya menampilkan &quot;7 dari 50&quot; sehingga Anda tahu posisi Anda di himpunan itu.","changelog.d3e1342a48af":"Ini bukan implementasi pratinjau kedua — ia memanggil <code>files_preview</code> yang sama dengan panel yang tertambat, sehingga format apa pun yang dapat dirender di satu tempat juga dapat dirender di tempat lain. Yang ditambahkannya adalah ukuran dan alur papan ketik: panel tertambat adalah panel yang Anda lirik, sedangkan ini adalah gestur &quot;berkas <em>apa</em> ini?&quot;, dan intinya tangan Anda tidak pernah meninggalkan papan ketik.","changelog.273a049cb91a":"<strong>Spasi ditangani di pengikat tombol global, bukan di komponen</strong>, dan inilah bagian yang rumit: Spasi juga merupakan karakter, sehingga diabaikan setiap kali kursor teks berada di input, textarea, select, atau contenteditable. Salah menanganinya berarti kotak pencarian berhenti menerima spasi — bug yang jauh lebih buruk daripada pintasan yang tidak ada.","changelog.ca26390b3e56":"Navigasi menelusuri urutan yang benar-benar <em>dirender</em> oleh daftar (batch dalam urutan lensa, dengan store pengurutan diterapkan di dalam masing-masing, kecuali batch klaster duplikat yang barisnya sudah diurutkan oleh daemon dan pengurutan ulang akan memecah klaster tersebut). Menelusuri urutan lain apa pun membuat tombol panah tampak melompat-lompat. Langkahnya berhenti di kedua ujung alih-alih memutar, karena memutar dari baris terakhir ke baris pertama terasa seperti glitch saat tombol ditahan, dan langkah itu mengganti pilihan alih-alih memperluasnya.","changelog.f6f10923fe43":"<strong>Penyimpangan dari deskripsi fitur, dinyatakan alih-alih disamarkan.</strong> Deskripsi itu meminta QuickLook native di macOS dan host milik Freally sendiri di platform lain. <code>qlmanage -p</code> membuka <em>jendela OS terpisah</em> yang tidak dapat dikendalikan oleh penanganan tombol Freally, sehingga menjadikannya bawaan di macOS akan merusak alur tombol panah yang merupakan inti fitur ini. Karena itu, modal di dalam aplikasi menjadi antarmukanya di ketiga platform — yang juga membuat perilakunya dapat diuji dan identik di mana pun — dan macOS juga mendapat tombol eksplisit &quot;Buka di Lihat Cepat macOS&quot; untuk format yang dapat dirender sistem tetapi tidak dapat dirender host pratinjau Freally. Path-nya melewati gerbang <code>KnownPaths</code> yang sama seperti setiap perintah berkas lainnya dan diteruskan sebagai argumen <code>Command</code>, tidak pernah melalui shell.","changelog.6fba87d13646":"<strong>SRC-M22 — bilah sisi markah dan filter.</strong> Kolom kiri opsional (Tampilan → Bilah sisi, nonaktif secara bawaan) dengan empat bagian: markah yang dapat diurutkan ulang dengan seret, tujuh filter tipe, volume terindeks, dan pencarian terbaru. Keempatnya sudah ada di balik tiga menu turun dan satu menu, sehingga membatasi cakupan pencarian berarti harus tahu di mana dari empat tempat itu harus melihat; ini menempatkan semuanya dalam satu kolom berisi node yang dapat diklik.","changelog.2af93b3b0eaf":"<strong>&quot;Pencarian terbaru&quot; perlu diciptakan, karena pencarian di sini bersifat langsung.</strong> <code>run()</code> dipicu pada setiap ketukan tombol, sehingga merekam setiap run apa adanya akan menghasilkan <code>r</code>, <code>re</code>, <code>rep</code>, <code>repo</code>, <code>repor</code>, <code>report</code> dan mengubur satu entri yang diinginkan orang. Dua aturan memperbaikinya tanpa gestur konfirmasi eksplisit yang memang tidak dimiliki UI: kueri baru menyingkirkan entri yang ada yang merupakan awalan darinya (ketukan-ketukan dalam perjalanan ke sana), dan kueri yang sendirinya merupakan awalan dari entri terbaru tidak direkam (itu adalah backspace). Mengetik &quot;report&quot; lalu &quot;invoice&quot; menyisakan tepat <code>[&quot;invoice&quot;, &quot;report&quot;]</code>.","changelog.97fe3ffe9b63":"Daftar ini mematuhi <strong>Mode privasi dan sakelar Riwayat Pencarian</strong> — keduanya sudah berarti &quot;jangan simpan catatan tentang apa yang saya cari&quot;, dan bagian bilah sisi persis merupakan catatan semacam itu, sehingga ia tidak diam-diam menyimpan salinannya sendiri.","changelog.736397e92eea":"Urutan seret disimpan sebagai daftar ID markah di pengaturan alih-alih pada rekaman markah, sehingga pengurutan ulang tidak memerlukan jalur tulis baru melalui IPC markah. ID untuk markah yang sudah dihapus diabaikan alih-alih meninggalkan celah, dan markah yang ditambahkan sejak seretan terakhir ditambahkan di akhir alih-alih dibuang.","changelog.bb58e9012e27":"Node volume menghasilkan <code>volume:&quot;&lt;label&gt;&quot;</code> <strong>dengan tanda kutip</strong>, karena label sering kali memuat spasi (<code>Orange WD 4TB</code>) dan tanpa tanda kutip akan di-parse sebagai dua istilah.","changelog.3ce317440cef":"Bilah sisi dirender di dalam <code>.result-area</code>, berbagi satu baris flex dengan daftar hasil dan panel pratinjau, sehingga menampilkan atau menyembunyikannya tidak mengganggu elemen menu / pencarian / status di atas dan di bawahnya.","changelog.d5f690fcafa4":"<strong>Duplikat yang tertangkap saat menyambungkan ini</strong>, layak dicatat karena sudah salah sejak awal: navigasi Lihat Cepat yang ditambahkan di SRC-M19 menelusuri <code>resultsStore.batches</code> secara langsung. Batch disimpan dalam urutan <em>kedatangan</em> dan membawa hit dari lensa yang sudah dinonaktifkan pengguna serta baris yang sudah disaring oleh penyempitan — sementara daftar dirender melalui <code>viewForLens</code> dalam urutan lensa yang tetap. <code>resultsStore.visibleHits</code> sudah ada dan menanganinya dengan benar. Helper navigasi kini dibangun di atas <code>viewForLens</code> yang sama, sehingga tombol panah menelusuri apa yang ada di layar, bukan apa yang kebetulan dikirim daemon lebih dulu.","changelog.357a743ccb54":"<strong>SRC-M21 — laporan status izin + wisaya Akses Disk Penuh macOS.</strong> Alat → Status izin, ditambah lencana bilah status yang hanya muncul saat ada sesuatu untuk disampaikan, membuka rincian folder mana yang tidak dapat dibaca pemindai, di volume mana, dan karena alasan apa — dengan panduan perbaikan untuk platform tempat <em>indeks</em> berjalan.","changelog.b5aa6e1796c3":"<strong>Lencana yang menurut deskripsi fitur harus diperluas ternyata tidak ada.</strong> Tidak ada &quot;n path dilewati (izin)&quot; di mana pun: direktori yang tidak dapat dibuka pemindai hanya menghasilkan satu baris <code>warn!</code> dan tidak ada yang lain, sehingga subtree yang tidak dapat dibaca tampak sama persis dengan subtree yang kosong. Buku catatannya (<code>crates/freally-indexd/src/permissions.rs</code>) harus dibangun terlebih dahulu. Ini keempat kalinya dalam rangkaian gerbang stabil ini titik awal yang dinyatakan sebuah Must-Have ternyata tidak ada.","changelog.62ca3f92cd3e":"Apa yang dicatat buku catatan itu dan alasannya:","changelog.d8706bc2b337":"<strong>Root, bukan berkas.</strong> <code>walkdir</code> melaporkan satu galat untuk direktori yang tidak dapat dibukanya dan tidak masuk lebih dalam, sehingga yang masuk ke buku catatan secara alami adalah root dari setiap subtree yang tidak dapat dibaca. Itu juga jawaban yang berguna: &quot;beri akses ke folder ini&quot;, bukan sepuluh ribu nama berkas.","changelog.0917b96f248e":"<strong>Path yang lenyap bukan kesalahan.</strong> <code>NotFound</code> dibuang sepenuhnya — berkas yang dihapus di tengah pemindaian adalah hal normal pada sistem berkas yang aktif, dan menghitungnya akan membuat setiap laporan di mesin yang sibuk tampak mengkhawatirkan.","changelog.4df4fedc30d4":"<strong>Dibatasi pada 2,000 entri, dengan kelebihannya dihitung.</strong> Daftar ini disimpan di memori, diserialisasi, dan dikirim melalui IPC; lewat dari beberapa ribu, ia tidak lagi menjadi laporan yang dibaca orang. UI menyatakan &quot;dan 12,043 lainnya&quot; alih-alih menyiratkan bahwa daftarnya lengkap.","changelog.45a8fa9b22b3":"<strong>Pemindaian ulang menghapus entri root itu terlebih dahulu</strong>, sehingga izin yang benar-benar sudah diperbaiki pengguna tidak lagi dilaporkan. Tanpa itu, laporannya hanya akan terus bertambah.","changelog.8c83c3941420":"<strong>Disimpan secara permanen</strong> ke <code>config/permissions.json</code>, karena &quot;berkas yang tidak dapat saya indeks&quot; harus bertahan setelah restart agar ada gunanya.","changelog.2272ff2f607f":"Panduannya ditentukan <strong>di sisi daemon</strong>, bukan dari user-agent browser: indeks dapat berada di mesin yang berbeda dari jendela yang merender laporan setiap kali klien diarahkan ke endpoint jarak jauh, dan perbaikannya menjadi urusan mesin yang tidak dapat membaca folder tersebut.","changelog.7bd109d95768":"Di macOS, laporan ini <strong>mendeteksi Akses Disk Penuh</strong> dengan membaca direktori yang dilindungi TCC: berhasil berarti sudah diberikan, <code>PermissionDenied</code> berarti belum. Galat lain apa pun dilaporkan sebagai <em>tidak dapat ditentukan</em> alih-alih &quot;belum diberikan&quot; — menyuruh seseorang memperbaiki pengaturan yang sudah benar lebih buruk daripada tidak mengatakan apa-apa. Saat izin belum diberikan, sebuah tombol langsung membuka panel Akses Disk Penuh.","changelog.bea94a4860c8":"Smoke: <code>tests/smoke/build_03_permissions.rs</code> membuktikan bahwa pemindai benar-benar memegang buku catatan itu — tree yang bersih membuatnya kosong, dan pemindaian sungguhan membuang entri dari putaran sebelumnya untuk root tersebut sambil membiarkan root lain. Tes ini sengaja tidak mencoba membuat direktori yang ditolak aksesnya: itu tidak portabel (<code>chmod 000</code> tidak berpengaruh bagi root, dan Windows akan memerlukan operasi ACL), sehingga jalur penolakan diuji lewat unit test dengan membangun <code>io::Error</code> secara langsung alih-alih meminta OS menghasilkannya.","changelog.a0e48a175453":"<strong>SRC-M18 — pemutaran audio/video inline di panel pratinjau.</strong> Kontrol transport (putar/jeda, seek, ulang), penggeser volume, waveform yang dirender dan dapat diklik untuk menggeser posisi, serta lencana codec / sample rate / kanal / LUFS yang ditumpangkan di atasnya. Mendengarkan hasil <code>lufs:&lt;-14</code> tidak lagi berarti meninggalkan Freally, dan itulah alur kerja yang dijaga lensa audio agar Anda tetap berada di dalamnya.","changelog.5677c3279dd5":"<strong>Waveform tidak memerlukan decode tambahan.</strong> Sebuah <code>PeakCollector</code> menumpang pada proses analisis yang sudah ada di <code>freally-audio</code>: frame interleaved yang sama yang mengisi akumulator kenyaringan dan keheningan juga mengisinya, sehingga membuka trek di panel yang terbuka ulang pada setiap tombol panah tidak mendekode berkas untuk kedua kalinya hanya untuk menggambarnya. Jumlah bucket tetap, bukan per detik, karena kanvasnya memiliki lebar tetap — mengubah sampel envelope per detik agar pas justru membuang puncak-puncak yang membuat bentuknya terbaca — dan bucket mengambil puncak lintas kanal, karena waveform menunjukkan bunyi paling keras yang terjadi pada saat itu, bukan pendapat kanal kiri tentangnya.","changelog.cdfeb4ff1549":"<strong>Byte dikirim melalui IPC, bukan protokol aset — dengan sengaja.</strong> Cara konvensional untuk menyuplai elemen media adalah protokol aset Tauri, dan cara itu ditolak: mengaktifkannya berarti mendeklarasikan cakupan sistem berkas yang boleh dibaca langsung oleh <em>webview</em>, dan cakupan apa pun yang cukup luas untuk mencakup &quot;di mana pun media pengguna berada&quot; juga cukup luas untuk membatalkan gerbang <code>KnownPaths</code> yang diperkuat di Build 1 — jaminan bahwa dependensi frontend yang disusupi tidak dapat menjangkau berkas yang tidak pernah dikembalikan daemon. Mengalirkan byte melalui sebuah perintah menjaga setiap pembacaan berada di balik pemeriksaan yang sama dengan setiap operasi berkas lainnya.","changelog.92840d3c1b10":"Konsekuensinya, pemutaran di-buffer, bukan di-stream, sehingga ada batas 192 MB — dinyatakan di UI, yang menawarkan untuk membuka berkas di atas batas itu di pemutar sistem, alih-alih gagal secara diam-diam. Byte dikembalikan sebagai <code>tauri::ipc::Response</code> mentah alih-alih data URL base64, yang akan menggelembungkan payload sepertiganya dan memerlukan encode ulang penuh di kedua sisi.","changelog.712f85c29448":"Dua hal kecil yang masing-masing akan menjadi bug nyata: object URL dicabut saat pilihan berubah (tanpanya, setiap tombol panah membocorkan satu berkas utuh yang sudah didekode), dan kenyaringan terintegrasi yang tidak hingga dirender sebagai <em>tanpa lencana</em> alih-alih <code>-inf LUFS</code> — klip yang lebih pendek dari satu blok gating tidak memiliki nilai terintegrasi yang bermakna.","changelog.d91a498a29f7":"Kemampuan diputar ditentukan dari ekstensi hit, bukan dari payload pratinjau: payload berkas media bernilai <code>unsupported</code>, yang justru merupakan kasus yang layak diputar.","changelog.7c9e53ab0e65":"Penutupan Build 3 — apa yang diubah oleh putaran review","changelog.4519ec9bebde":"<code>/simplify</code> menjalankan empat peninjau atas seluruh diff build. Tiga di antaranya secara independen menandai hal yang sama, dan dua temuan adalah cacat nyata, bukan soal gaya:","changelog.8ce21698a623":"<strong>Bilah sisi membuang filter tersimpan milik markah.</strong> <code>applyBookmark</code> mengimplementasikan ulang alur muat menu turun dan melewatkan <code>typeFilterStore.setFromIds(...)</code>, sehingga membuka markah dari bilah sisi menyusun prefiks lensa yang berbeda dibanding membuka markah yang sama dari menu turun. Keduanya kini memanggil satu <code>bookmarksStore.apply</code>.","changelog.eac5108065c7":"<strong><code>visibleHits</code> ada dua kali, dengan jawaban berbeda.</strong> Salinan milik Lihat Cepat melakukan pengurutan; <code>resultsStore.visibleHits</code> — yang dibaca oleh ekspor, pilih semua, dan jumlah di bilah status — tidak. Keduanya berbeda begitu pengurutan kolom aktif. Pengurutan dipindahkan ke getter store dan salinannya dihapus, yang juga membuat komentar getter itu, &quot;satu-satunya jawaban atas apa yang sedang dilihat pengguna&quot;, menjadi benar alih-alih sekadar cita-cita.","changelog.c773525b8054":"<strong>Dua daftar mode ketat yang disinkronkan secara manual sudah mulai berbeda.</strong> Daftar pengubah khusus Freally milik parser memuat <code>volume:</code> sedangkan salinan di <code>report.rs</code> tidak, sehingga kueri strict-everything yang memakai <code>volume:</code> ditolak oleh parser sementara laporan yang menjadi dasar render bilah pencarian menganggapnya baik-baik saja. Kini hanya ada satu <code>is_freally_only_modifier</code>.","changelog.67e8b82d717f":"Temuan kinerja yang layak dicatat, semuanya pada jalur yang ditambahkan build ini:","changelog.193b3787c53e":"Effect milik lencana izin terpicu ulang pada setiap polling state indeks — <code>indexStateStore</code> menugaskan ulang seluruh objek state, sehingga &quot;membaca <code>phase</code>&quot; menjadi tidak valid terlepas dari apakah <code>phase</code> berubah. Akibatnya terjadi satu round-trip IPC setiap lima detik tanpa henti, masing-masing mengkloning seluruh buku catatan di bawah mutex. Kini dijaga berdasarkan fase polling terakhir.","changelog.25ff7799a027":"Komparator pengurutan alami menjalankan regex per <em>karakter</em> dan membangun collator baru per potongan. Kini memakai uji code point dan satu <code>Intl.Collator</code> bersama.","changelog.282cbf6f5b04":"Pengurutan berdasarkan path mengonversi kedua <code>PathBuf</code> pada setiap perbandingan — pemindaian WTF-8 sebanyak O(n log n). Kini memakai decorate-sort-undecorate, satu konversi per baris.","changelog.fa6395a85e8e":"Pemutar media memuat byte dan waveform secara berurutan padahal keduanya independen; dan membuat seluruh ~800 batang waveform bergantung pada progres pemutaran, sehingga setiap <code>timeupdate</code> mengevaluasi ulang 800 ekspresi. Kini keduanya berjalan tumpang-tindih ala <code>Promise.all</code> dan memakai satu overlay <code>--progress</code>.","changelog.1a1162f4da54":"Selain itu: <code>AnalysisOpts::peak_buckets</code> kini privat, karena sebagai bidang <code>pub</code> pemanggil dapat menyetelnya pada <code>analyze_with_opts</code>, yang tidak punya tempat untuk mengembalikan puncak dan akan membuangnya secara diam-diam; dan <code>media.rs</code> memanggil <code>files::verify_readable</code> bersama alih-alih salinannya sendiri, sehingga tingkat provenance untuk pembacaan yang diklaim frontend ditentukan di tepat satu tempat.","changelog.c70a3b9f1590":"Penutupan Build 3 — apa yang diubah oleh <code>/security-review</code>","changelog.ccce544a9b0c":"Dua temuan HIGH, keduanya diperkenalkan oleh build ini, keduanya diperbaiki.","changelog.de5618b9e06c":"<strong><code>media_bytes</code> dijaga pada tingkat yang dapat dicetak frontend untuk dirinya sendiri.</strong> Perintah ini mengembalikan isi <em>lengkap</em> sebuah berkas bernama ke webview, dan memakai <code>Provenance::FrontendAsserted</code> — tingkat yang diberikan <code>files_whitelist_user_chosen</code> untuk string apa pun yang diminta lapisan JS. Dependensi frontend yang disusupi dapat memasukkan <code>~/.ssh/id_ed25519</code> ke whitelist lalu membacanya, tanpa dialog dan tanpa melibatkan daemon. Dua perintah lain yang mengembalikan isi berkas, <code>content_document</code> dan <code>copy_file_contents</code>, sudah mensyaratkan <code>QueryHit</code>; kini kedua perintah ini juga demikian. Pemanggil yang sah digerakkan dari baris hasil, yang sudah membawa tingkat itu, sehingga tidak ada yang berubah bagi pengguna.","changelog.ec04c33c4cd8":"<strong>Socket mode portabel berada langsung di direktori temp bersama.</strong> <code>/tmp</code> bermode 1777 dan namanya adalah hash FNV dari path yang mudah ditebak, sehingga akun lokal mana pun dapat mengikatnya lebih dulu. Transport mengautentikasi <em>peer</em> dari listener yang dimilikinya; klien yang menyambung keluar tidak memeriksa apa pun, sehingga menduduki path itu berarti peniruan daemon secara penuh — dan <code>register_hit_paths</code> mengubah apa pun yang tiba dalam <code>query:batch</code> menjadi <code>Provenance::QueryHit</code>, yang merupakan gerbang untuk hapus, ganti nama, dan setiap perintah destruktif lainnya. Tiga perubahan:","changelog.7cf7132d7226":"Socket dipindahkan ke direktori per pengguna — <code>$XDG_RUNTIME_DIR</code> jika ada, jika tidak, subdirektori bertanda uid yang dibuat proses ini dan di-chmod 0700, yang langsung ditolak jika ternyata dimiliki orang lain.","changelog.aadc9d78386e":"<code>transport::unix::connect</code> kini menolak socket yang tidak dimiliki pengguna ini, atau yang mode-nya dapat dijangkau pihak lain. Ia memakai <code>symlink_metadata</code>, sehingga symlink yang menunjuk ke socket milik kita tidak memenuhi pemeriksaan itu. Ini adalah pasangan yang selama ini hilang dari pemeriksaan peer-uid milik listener.","changelog.0ed10670ac32":"<code>listen</code> tidak lagi gagal total saat tidak dapat memperketat direktori induk socket. <code>chmod 0700 /tmp</code> mengembalikan <code>EPERM</code> untuk setiap pengguna non-root, sehingga <strong>mode portabel sama sekali tidak dapat menjalankan daemon-nya di Linux</strong> — langkah pengerasan itu justru menjatuhkan hal yang seharusnya dilindunginya. Kini ia mencatat ke log dan mengandalkan mode 0600 milik socket itu sendiri.","changelog.d3ce18a2d574":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-02\">2026-08-02</time></span><span class=\"release__title\">Build 2 · Gerbang stabil Must-Have, irisan 2 dari 3</span>","changelog.9bd054757229":"Build kedua dari tiga build Must-Have: SRC-M09 … SRC-M16. Lintas platform kecuali ada catatan per OS yang menyatakan sebaliknya. Dokumentasi fitur lengkap ada di <code>docs/documentation.html</code>.","changelog.d9bb66b60223":"<strong>SRC-M09 — keluaran CLI yang dapat dibaca mesin.</strong> <code>freally search</code> mendapat <code>--json</code>, <code>--ndjson</code> (satu objek per hit, streaming), <code>--csv</code>, <code>--fields</code> untuk memilih kolom, <code>-0</code> untuk <code>xargs -0</code>, <code>--limit</code> / <code>--offset</code>, serta kode keluar yang bermakna (0 ada hit, 1 tidak ada, 2 galat).","changelog.758c601a0121":"<strong>SRC-M10 — pelengkapan shell.</strong> <code>freally completions &lt;shell&gt;</code> mencetak pelengkapan untuk bash, zsh, fish, dan PowerShell, mencakup subperintah, flag, dan — secara dinamis — kata kunci pengubah serta nama pencarian tersimpan.","changelog.88b57e0c662b":"<strong>SRC-M11 — &quot;apakah maksud Anda&quot; yang toleran terhadap salah ketik.</strong> Saat lensa nama berkas tidak mengembalikan apa pun, kandidat kemiripan diurutkan ulang berdasarkan jarak Damerau-Levenshtein terbatas dan yang paling dekat ditawarkan sebagai koreksi sekali klik.","changelog.651b223b2f18":"<strong>SRC-M12 — pencocokan fonetik CJK.</strong> Mengetik <code>wenjian</code> atau <code>wj</code> mencocokkan <code>文件</code>; romaji mencocokkan kana; jamo awal mencocokkan Hangul. Bacaan diindeks sebagai kunci nama tambahan dan bersifat opt-in melalui <strong>Cari → Cocokkan fonetik CJK</strong>. Setiap konversi adalah pencarian tabel atau aritmetika — dekomposisi Hangul murni aritmetika pada blok suku kata Unicode, kana memakai tabel di dalam tree, dan bacaan Han berasal dari crate <code>pinyin</code>.","changelog.1bd2b09ee538":"<strong>Pencatatan perubahan secara langsung.</strong> Indeks kini diperbarui saat berkas berubah, bukan hanya saat pemindaian dijalankan. Setiap subscriber OS sudah mengimplementasikan <code>subscribe()</code> dan <code>freally-index</code> sudah menyertakan <code>EventQueue</code> yang terbatas, tetapi tidak ada yang pernah menghubungkannya: <code>Index::apply</code> dan <code>EventQueue</code> hanya dapat dijangkau dari benchmark dan satu unit test. <code>freally-indexd::watcher</code> adalah pipeline tersebut — thread produsen yang menguras aliran perubahan OS ke dalam antrean, dan konsumen yang menerapkan serta meng-commit batch. Di Windows, journal USN bersifat per volume, sehingga folder-folder di satu drive digabung ke satu watcher yang memfilter berdasarkan prefiks path; FSEvents dan inotify memantau subtree secara langsung.","changelog.eaa3eb8d8d9f":"<em>Mengapa produsen membuang alih-alih memblokir:</em> memblokir tidak akan menyelamatkan peristiwa — buffer di sisi OS terus terisi selama kita menunggu, dan saat meluap, peristiwa itu hilang tanpa catatan. Membuang di batas kita sendiri kehilangan peristiwa yang sama tetapi meninggalkan buku catatan yang terhitung dan bertanda waktu, dan itulah yang dilaporkan oleh penasihat di bawah.","changelog.71e6a83277bd":"<strong>SRC-M13 — panel Kesehatan Indeks + penasihat pembangunan ulang.</strong> <strong>Alat → Pemeliharaan indeks → Kesehatan Indeks</strong> melaporkan, per lokasi yang dipantau, jeda dari peristiwa hingga terlihat di kueri, buku catatan peristiwa yang terbuang, perubahan terakhir yang terlihat, dan kedalaman antrean, ditambah saran berbasis aturan dengan pembangunan ulang sekali klik saat pembangunan ulang adalah solusinya. Tumpukan ekstraksi konten dilaporkan sebagai <em>tidak dilacak</em> alih-alih nol — daemon tidak menjalankan worker ekstraksi segera, dan &quot;0&quot; akan terbaca sebagai &quot;menganggur&quot;.","changelog.946db255ad4d":"<strong>SRC-M14 — katalog volume lepasan luring.</strong> Mencabut sebuah drive tetap membuat berkas-berkasnya dapat dicari, dan hasil dari perangkat yang terlepas membawa lencana <em>luring — Orange WD 4TB</em>. <code>volume:</code> memfilter berdasarkan nama yang Anda kenal untuk drive itu, atau berdasarkan ID volumenya. Drive yang kembali dengan huruf atau titik mount yang berbeda dikenali sebagai katalog yang sama.","changelog.f637da61fd70":"<em>Di balik layar:</em> kolom <code>volume</code>, indeks SQLite-nya, dan bidang Tantivy-nya semuanya sudah dirilis di Fase 4, tetapi satu-satunya konstruktor baris di jalur ingest meng-hardcode string kosong, sehingga seluruh kolom itu mati. Baris kini dicap lewat pencocokan prefiks terpanjang atas tabel mount yang sebenarnya, satu-satunya hal yang dapat membedakan titik mount dari direktori biasa.","changelog.4ec8be883d22":"<strong>SRC-M15 — ganti nama massal.</strong> Pilih berapa pun hasil, tekan <code>F2</code>, dan jelaskan perubahannya sekali: cari/ganti literal atau regex dengan grup tangkapan, penghitung <code>{n}</code> / <code>{n:03}</code>, transformasi huruf besar/kecil, dan pilihan untuk mengganti nama tanpa ekstensi atau seluruh nama. Tabel langsung menampilkan setiap pasangan sebelum/sesudah dan menandai baris yang akan bertabrakan satu sama lain, menimpa berkas yang sudah ada, atau menghasilkan nama yang tidak akan diterima sistem. Batch-nya bersifat semua-atau-tidak-sama-sekali, dan kegagalan di tengah batch akan di-rollback.","changelog.46851cce7744":"<em>Catatan:</em> roadmap mencatat ganti nama satu berkas sebagai sudah dirilis. Ternyata belum — yang ada hanya ganti nama <em>markah</em> — sehingga build ini menambahkan primitif ganti nama sekaligus lapisan massal di atasnya.","changelog.3fc85f03e023":"<strong>SRC-M16 — urungkan/ulangi untuk operasi berkas.</strong> <code>Ctrl+Z</code> membalikkan ganti nama atau ganti nama massal, <code>Ctrl+Shift+Z</code> mengulanginya, dan journal disimpan secara permanen oleh daemon sehingga 50 operasi terakhir bertahan setelah restart. Sebuah batch dibatalkan dalam urutan terbalik, sehingga ganti nama berantai (<code>a→b</code>, <code>b→c</code>) dapat diurungkan tanpa bertabrakan dengan dirinya sendiri.","changelog.51f9c128a973":"<em>Pengecualian yang didokumentasikan:</em> penghapusan dicatat dalam riwayat tetapi tidak dapat diurungkan. Freally menghapus ke tempat sampah OS, dan satu-satunya API pemulihan lintas platform (<code>trash::os_limited</code>) diimplementasikan untuk Windows dan Linux freedesktop tetapi <strong>tidak untuk macOS</strong>. Alih-alih menawarkan tombol yang gagal setelah ditekan, penghapusan membawa alasan yang menjelaskan bahwa pemulihan adalah tugas sistem operasi. Salin ke folder dan pindahkan ke folder tidak dicatat dalam journal karena keduanya belum benar-benar melakukan penyalinan atau pemindahan.","changelog.c75a49fc28b8":"<strong>Bentuk keamanan perintah sisi tulis.</strong> Ganti nama memiliki tujuan, dan tidak seperti sumber, tujuan itu tidak pernah ada di himpunan hasil mana pun — sehingga berdasarkan aturan Build 1 bahwa IPC sisi tulis tidak boleh menerima path pilihan pemanggil, frontend tidak pernah mengirimkannya. Frontend mengirim path yang dipilih dan <em>aturannya</em>; backend menurunkan setiap nama sendiri dan menurunkannya ulang saat diterapkan alih-alih memercayai pratinjau, sehingga tabel pratinjau yang dimanipulasi tidak mengubah apa pun. Nama turunan ditolak jika memuat pemisah path, berupa <code>.</code> atau <code>..</code>, memuat karakter yang tidak diterima platform mana pun, akan diam-diam ditulis ulang oleh Windows (titik atau spasi di akhir, yang akan membuat nama yang diterapkan berbeda dari yang disetujui), atau cocok dengan nama perangkat yang dicadangkan. Tujuannya kemudian dibangun ulang dari direktori induk milik sumber itu sendiri.","changelog.b2289135440f":"<strong>Tes.</strong> <code>tests/smoke/build_02_index_health.rs</code>, <code>build_02_volume_catalogs.rs</code>, dan <code>build_02_rename_undo.rs</code> menjaga antarmuka-antarmuka baru secara agnostik OS; unit test mencakup mesin ganti nama, journal operasi, aturan penasihat, penggabungan peristiwa, penghitungan jeda, peta volume, dan registri katalog. <code>apps/freally-ui/tests/unit/build_02.test.ts</code> mencakup penyambungan frontend.","changelog.b1d319c1818b":"<strong>i18n.</strong> 68 kunci baru di seluruh 18 lokal (total 782); <code>xtask i18n-lint</code> hijau.","changelog.7d87f19cc769":"<code>volume:</code> adalah pengubah khusus Freally, sehingga ditolak dalam mode strict-Everything bersama <code>similar:</code> dan keluarga audio.","changelog.7df7bfeaffe7":"<code>freally-journal</code> menyediakan <code>JournalPosition</code> (<code>generation</code> + <code>offset</code>) yang agnostik OS pada ketiga subscriber, sehingga daemon dapat mendeteksi aliran perubahan yang berputar ulang atau dibuat ulang tanpa perlu mengetahui tipe kursor per OS.","changelog.f787e991d5ac":"Celah yang diketahui","changelog.cea8b98efa00":"<code>auto_remove_offline</code> tetap tidak melakukan apa pun. Mengimplementasikannya secara harfiah berarti membersihkan baris perangkat luring dari indeks; itu destruktif, di luar cakupan SRC-M14, dan nilai bawaannya <code>true</code> akan berlaku diam-diam pada setiap instalasi yang ada. Mempertahankan data adalah yang diinginkan fitur ini dan yang memang sudah dilakukan daemon.","changelog.8d7633d7bfb2":"Keempat sakelar mode pencocokan yang sudah ada (huruf besar/kecil, seluruh kata, path, diakritik) masih hanya berlaku di UI — daemon membangun <code>ExecOpts::default()</code> dan hanya flag fonetik SRC-M12 yang dikirim lewat wire. Masalah ini sudah ada sebelum Build 2; menyambungkannya akan mengubah apa yang dikembalikan kueri yang sudah ada.","changelog.61109f3e67da":"<span class=\"release__meta\"><span class=\"release__ver\">v0.21.0</span><time class=\"release__date\" datetime=\"2026-07-31\">2026-07-31</time></span><span class=\"release__title\">Build 1 · Gerbang stabil Must-Have, irisan 1 dari 3</span>","changelog.d178abfc569c":"Build pertama dari tiga build Must-Have: SRC-M01 … SRC-M08. Lintas platform kecuali ada catatan per OS yang menyatakan sebaliknya. Dokumentasi fitur lengkap ada di <code>docs/documentation.html</code>.","changelog.8290eb7e3829":"<strong>SRC-M01 — penampil konten dengan hit dalam konteks.</strong> Tampilan dokumen penuh untuk berkas apa pun yang dapat dibaca pipeline pengekstrak: setiap kecocokan disorot, baris bernomor, lencana jumlah kecocokan, <code>F3</code> / <code>Shift+F3</code> untuk berpindah antarkecocokan, dan langsung melompat ke hit pertama saat dibuka. Dapat dibuka dari menu klik kanan hasil yang baru. Istilah yang disorot adalah atom literal dan berkutip dari kueri ditambah chip penyempitan yang aktif. Dibatasi pada 20,000 baris, dan menyatakannya.","changelog.90356999c878":"<strong>SRC-M02 — cari dalam hasil.</strong> <code>Ctrl+Shift+F</code> membuka kotak tahap kedua yang mempersempit himpunan yang sudah ada di layar alih-alih menjalankan ulang kueri. Setiap istilah menjadi chip yang dapat dihapus, sehingga kebablasan hanya memakan satu klik, bukan mengetik ulang. Istilah yang memuat pemisah path dicocokkan dengan path lengkap, jika tidak, dengan nama berkas. Ekspor dan Pilih Semua membaca himpunan yang sudah dipersempit, sehingga tidak pernah bertindak pada baris yang sudah disingkirkan chip. <em>(Atur Filter pindah ke <code>Ctrl+Shift+O</code>.)</em>","changelog.e01ea66e064f":"<strong>SRC-M03 — impor/ekspor yang interoperabel dengan Everything.</strong> <code>File → Export Results…</code> memilih formatnya dari ekstensi yang dipilih di dialog simpan: <code>.efu</code>, <code>.csv</code>, <code>.txt</code>, <code>.m3u</code> / <code>.m3u8</code>, <code>.ndjson</code>, <code>.json</code>. <code>.efu</code> kompatibel byte demi byte dengan Everything milik voidtools — header literal <code>Filename,Size,Date Modified,Date Created,Attributes</code>, baris CRLF, kutipan RFC-4180, dan tick FILETIME Windows yang dikonversi di batas, sehingga daftar yang ditulis di Linux atau macOS dapat dimuat ke Everything di Windows tanpa perubahan. Ekspor playlist hanya membawa audio dan menyatakan berapa baris dari berapa yang ditulis. <code>File → Open File List…</code> memuat sebuah daftar dan mencarinya <em>sebagai pengganti</em> indeks langsung — jawaban atas &quot;berkas itu ada di drive mana?&quot; untuk volume yang sudah dicabut. Pencocokan atas daftar yang dimuat berupa substring nama atau path, bukan DSL.","changelog.d5c8d8b6e6ed":"<strong>SRC-M04 — Buka dengan…</strong> Enumerasi per OS atas aplikasi yang terdaftar untuk tipe sebuah hasil: <code>SHAssocEnumHandlers</code> di Windows (sumber yang dipakai Explorer sendiri), pencocokan <code>MimeType=</code> pada <code>.desktop</code> terhadap basis data MIME bersama di Linux, serta tipe dokumen bundle yang dideklarasikan ditambah <code>/usr/bin/open -a</code> di macOS.","changelog.00c9693a1527":"<strong>SRC-M05 — perintah salin lanjutan.</strong> Salin <em>isi</em> berkas teks; salin berkasnya sendiri sebagai objek berkas papan klip OS (<code>CF_HDROP</code>, URL berkas <code>NSPasteboard</code>, <code>x-special/gnome-copied-files</code>); dan salin pilihan ganda sebagai daftar path dalam empat gaya kutipan.","changelog.678cdb17b71c":"<em>Pengecualian per OS yang didokumentasikan:</em> Linux tidak memiliki papan klip dalam proses yang bertahan setelah proses penulisnya keluar, sehingga penyalinan objek berkas memerlukan <code>wl-clipboard</code> atau <code>xclip</code>, dan menyatakannya saat keduanya tidak terpasang.","changelog.c00e9441825d":"<strong>SRC-M06 — terminal di sini dan perintah khusus.</strong> &quot;Buka terminal di sini&quot; meluncurkan terminal platform di folder hasil. Perintah buatan pengguna berada di <strong>Pengaturan → Umum → Perintah khusus</strong> dengan placeholder <code>{path}</code> / <code>{dir}</code> / <code>{name}</code> / <code>{stem}</code> / <code>{ext}</code> dan cakupan per ekstensi yang opsional. Setiap ekspansi menjadi satu slot <code>argv</code>.","changelog.561fa38bf46d":"<strong>SRC-M07 — keluarga <code>dupe:</code> mulai berfungsi.</strong> <code>dupe:</code> (nama <em>dan</em> ukuran sama), <code>name-dupe:</code> / <code>dupe:name</code>, serta <code>size-dupe:</code> / <code>dupe:size</code> kini dieksekusi alih-alih di-parse menjadi <code>ModifierKind::Reserved</code>. Deteksi berjalan langsung dari indeks — tanpa hashing, yang merupakan tugas SRC-N22. Baris yang cocok dikelompokkan di bawah header grup. Direktori tidak pernah masuk ke dalam grup. Seperti <code>similar:</code>, keluarga ini hanya boleh berada di posisi root.","changelog.0610973d550f":"<em>Catatan Aturan Tetap #8:</em> <code>dupe:foo</code> dulu berhasil di-parse lalu gagal saat dieksekusi. Kini ia gagal saat <em>parse</em> dengan <code>InvalidModifierValue</code> — promosi yang sama yang didapat pengubah audio di Fase 9. Tidak ada kueri yang pernah mengembalikan hasil yang berubah perilakunya.","changelog.761324a5cfcc":"<strong>SRC-M08 — pengubah kekosongan.</strong> <code>empty:</code> (polos, atau dengan cakupan <code>empty:file</code> / <code>empty:folder</code> / <code>empty:roots</code>), <code>child-count:</code>, dan <code>descendant-count:</code>, dijawab dari data indeks tanpa menelusuri sistem berkas. <code>empty:roots</code> melaporkan <em>puncak</em> dari setiap rantai folder yang tidak memuat berkas di kedalaman mana pun; pengubah hitungan hanya pernah mencocokkan direktori. <code>freally_index::DirStats</code> yang baru menurunkan bentuk direktori indeks dalam satu kali lintasan atas <code>files.db</code>, di-memoize terhadap penghitung peristiwa yang diterapkan.","changelog.b3468cd50e03":"<strong>UI pendukung.</strong> Menu klik kanan hasil, area toast di jendela utama, dan bilah penyempitan — semuanya dapat dijangkau dengan papan ketik.","changelog.53d34aa4b652":"<strong>Tes.</strong> <code>tests/smoke/build_01_dsl.rs</code> dan <code>build_01_interop.rs</code> menjaga kedua keluarga pengubah dan format wire <code>.efu</code>; unit test mencakup <code>DirStats</code>, codec, kutipan, ekspansi placeholder, parsing <code>.desktop</code>, lokasi hit, gerbang provenance, dan keselarasan tabel lintas crate; <code>tests/unit/build_01.test.ts</code> mencakup store frontend.","changelog.73bc8a5d676f":"<strong>i18n.</strong> 55 kunci baru di seluruh 18 lokal; <code>xtask i18n-lint</code> hijau.","changelog.f56c4fe5f08d":"<strong>[semua platform]</strong> <code>KnownPaths</code> tidak memiliki penulis. Fase 12 memindahkan hit kueri ke notifikasi daemon dan tidak ada yang mengambil alih pendaftarannya, sehingga setiap operasi berkas yang dijaga menolak setiap baris hasil. <code>daemon.rs</code> kini mendaftarkannya saat <code>query:batch</code> melintas.","changelog.fe76b18c0f5e":"<strong>[semua platform]</strong> <code>finalize_bootstrap</code> tidak memajukan <code>applied_events</code>, sehingga <code>DirStats</code> yang diturunkan di tengah pemindaian tetap di-cache terhadap indeks yang sudah selesai — membuat <code>empty:folder</code> cocok dengan setiap direktori sampai batch journal berikutnya.","changelog.83072c3967c3":"<strong>[semua platform]</strong> <code>dupe:</code> di posisi yang tidak didukung dibuang diam-diam setiap kali ada satu lagi di tingkat atas (<code>dupe:name !size-dupe:</code> mengembalikan nol hit tanpa galat). Penjaga posisi kini menghitung node alih-alih sekadar memeriksa ketiadaannya.","changelog.abf1376b827c":"<strong>[semua platform]</strong> <code>empty:roots</code> tidak melaporkan apa pun saat seluruh tree yang dipindai tidak memuat berkas: setiap baris menyintesis entri hitungan untuk induknya, sehingga induk dari root pemindaian itu sendiri tampak terindeks.","changelog.24ee98d1fa85":"<strong>[semua platform]</strong> Menegasikan predikat yang tidak dapat diputuskan oleh indeks nama (<code>!empty:file</code>, <code>!size:&gt;1mb</code>) mengembalikan nol baris — konvensi &quot;loloskan saja&quot; pada tahap nama terbalik menjadi penolakan di bawah <code>NOT</code>. Masalah ini sudah ada sebelumnya; Build 1 membuatnya menonjol.","changelog.8d60d2e391a7":"<strong>[semua platform]</strong> Penampil hit menemukan kecocokan pada <em>salinan</em> huruf kecil dari setiap baris sementara UI memotong teks aslinya, sehingga setiap sorotan bergeser pada baris yang memuat <code>İ</code>. Offset kini mengindeks teks asli, dan kata yang dicari serta teks sasarannya dilipat secara identik.","changelog.83b5581b542c":"<strong>[Linux]</strong> <code>wl-copy</code> yang gagal (saat berjalan di bawah X11) melaporkan sukses, sehingga &quot;Salin sebagai berkas&quot; mengklaim berhasil, tidak menyentuh papan klip, dan tidak pernah beralih ke <code>xclip</code>.","changelog.4695c56f4771":"<strong>[Windows]</strong> Penjaga COM memanggil <code>CoUninitialize</code> bahkan saat <code>CoInitializeEx</code> mengembalikan <code>RPC_E_CHANGED_MODE</code> — meruntuhkan COM di bawah pihak yang sebenarnya menginisialisasi thread itu.","changelog.e39b26f32960":"<strong>[CI]</strong> <code>vendor/freally-central</code> (panel Aplikasi Freally lainnya) adalah submodule yang menunjuk ke repositori yang sudah tidak ada, sehingga setiap run di setiap OS gagal saat <em>checkout</em>. Panel itu kini di-vendor sebagai kode sumber biasa dan kedua workflow menyetel <code>submodules: false</code>, sehingga repositori dapat di-build dari clone tanpa memerlukan apa pun lagi.","changelog.0cb6b784b78e":"<strong>[semua platform]</strong> <code>wasmtime</code> 44.0.1 → 47.0.3 di host pengekstrak kustom, menutup <strong>RUSTSEC-2026-0222</strong> (indeks tipe dapat tertukar antar-engine). Hanya dapat dijangkau melalui pengekstrak WASM yang dipasang pengguna, tetapi <code>cargo-deny</code> tetap menjadikannya syarat build.","changelog.e131be0feec2":"<strong>[semua platform]</strong> Ekspor dan impor daftar berkas kini membuka dialog OS-nya <strong>di Rust</strong> dan bertindak atas path yang dibacanya kembali. Mengalirkan tujuan melalui webview berarti <code>file_list_export</code> — perintah sisi <em>tulis</em> pertama di Build 1 — akan menimpa path apa pun yang disebut frontend, dan entri registri yang dijadikan acuan pemeriksaannya adalah entri yang dapat dicetak oleh frontend sendiri. <code>KnownPaths</code> juga mendapat dimensi <code>Provenance</code> sehingga izin yang dapat dijangkau frontend tidak pernah dapat memberikan hak tulis.","changelog.d1a9848c839b":"<strong>[semua platform]</strong> <code>run_custom_command</code> menerima <strong>ID</strong> perintah dan me-resolve-nya terhadap pengaturan backend yang tersimpan. Menerima bidang <code>program</code> lewat IPC menjadikannya primitif eksekusi proses sembarang: meneruskan argumen melalui <code>Command::arg</code> bukanlah perlindungan saat pemanggil juga memilih berkas eksekusinya.","changelog.ed41b394f8fd":"Lihat <code>docs/SECURITY.md</code> untuk perubahan model ancaman selengkapnya.","changelog.c99d8fed1d7c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.1</span><time class=\"release__date\" datetime=\"2026-07-10\">2026-07-10</time></span>","changelog.2cd4002ecd32":"Rilis patch tanpa fitur baru. Rilis ini ada karena v0.20.0 tidak dapat memperbaiki dirinya sendiri: endpoint updater dikompilasi ke dalam biner yang dirilis, sehingga setiap instalasi memeriksa repositori yang tidak ada dan tidak akan pernah ditawari pembaruan. Inilah build yang memperbaikinya, dan build ini membawa peningkatan keamanan yang belum ada saat v0.20.0 dibuat.","changelog.4bffda6c3827":"<strong>[semua platform]</strong> <code>quick-xml</code> 0.39.4 → 0.41.0, menutup <strong>RUSTSEC-2026-0194</strong> (waktu eksekusi kuadratik saat memeriksa start tag untuk nama atribut duplikat) dan <strong>RUSTSEC-2026-0195</strong> (alokasi deklarasi namespace tanpa batas di <code>NsReader</code>, denial of service berupa kehabisan memori). Keduanya dapat dijangkau: pengekstrak docx dan pptx di <code>freally-extractors</code> menyalurkan XML Office yang tidak tepercaya langsung ke <code>quick_xml::Reader</code>. Dokumen jahat dapat membuat host pengekstrak macet atau kehabisan sumber daya. Lisensi tidak berubah (MIT).","changelog.68001f921152":"<strong>[semua platform]</strong> <code>calamine</code> 0.34.0 → 0.36.0 — rilis pertama yang menerima <code>quick-xml ^0.41</code>, sehingga ini merupakan prasyarat dari perubahan di atas, bukan perubahan tersendiri. Lisensi tidak berubah (MIT). Dependensi transitifnya, <code>zip</code>, naik 7 → 8; <code>zip</code> milik workspace sendiri tetap dipatok di 5.","changelog.d7a4cb594270":"<strong>[semua platform]</strong> <code>crossbeam-epoch</code> 0.9.18 → 0.9.20, menutup <strong>RUSTSEC-2026-0204</strong> (dereferensi pointer tidak valid dalam impl <code>fmt::Pointer</code> untuk <code>Atomic</code> dan <code>Shared</code> saat pointer yang mendasarinya tidak valid). Transitif dan kompatibel secara semver. Lisensi tidak berubah (MIT OR Apache-2.0).","changelog.4aabc8b9de68":"Ketiganya diperbaiki dengan peningkatan versi. Tidak ada advisory yang ditambahkan ke daftar abaikan <code>deny.toml</code>.","changelog.6fd7a68afb1a":"<strong>[semua platform]</strong> Updater otomatis kini menunjuk ke repositori tempat proyek ini sebenarnya berada. <code>tauri.conf.json</code> menyebut <code>MikesRuthless12/Freally</code>, yang tidak ada, sehingga <code>latest.json</code> menghasilkan 404 dan <strong>pembaruan otomatis tidak pernah berfungsi di build mana pun yang pernah dirilis</strong>. Karena endpoint-nya tertanam di dalam biner, v0.19.84 dan v0.20.0 terus melakukan polling ke URL yang mati; hanya instalasi rilis ini atau yang lebih baru yang dapat menemukan pembaruan.","changelog.4a77c5b010f4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span>","changelog.ff6c265c78c6":"Tidak ada catatan yang ditulis untuk rilis ini. Apa yang diubahnya hanya dapat dipulihkan dari rentang commit antara <code>v0.19.84</code> dan <code>v0.20.0</code>; rilis ini dicatat di sini sebagai kosong alih-alih direkonstruksi, karena ringkasan masuk akal yang ditulis lima bulan kemudian hanyalah tebakan yang mengenakan format yang sama dengan fakta. Satu-satunya hal yang diketahui pasti tentangnya ada di <code>[0.20.1]</code> di bawah: endpoint updater-nya menyebut repositori yang tidak ada, dan rilis itu tidak dapat memperbaiki dirinya sendiri.","changelog.648e810f75b8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-21\">2026-06-21</time></span><span class=\"release__title\">Fase 0–12 · build publik pertama</span>","changelog.abfb5e516e09":"Catatan ini berada di bawah <code>## [Unreleased]</code> dari 2026-05-11 hingga 2026-08-21, melewati lima rilis bertag. Isinya bukan pekerjaan yang belum dirilis dan memang tidak pernah — entri Fase 0 di bawah berakhir dengan &quot;Tag publik pertama akan menjadi <strong>v0.19.84</strong>&quot;, dan itulah yang didokumentasikan bagian ini. Tag-nya dibuat pada 2026-06-21 tanpa ada yang mengganti nama judulnya, dan setiap rilis setelahnya mewarisi blok yang sama.","changelog.c8dfea56f286":"Itu adalah bahaya nyata, bukan sekadar ketidakrapian. Workflow rilis menyusun catatan yang diterbitkannya dengan mengganti nama <code>## [Unreleased]</code> menjadi versi yang sedang dibuat, sehingga rilis berikutnya akan merilis 533 baris pekerjaan Fase 0–12 — berumur lima bulan, sudah ada di setiap instalasi — seolah-olah baru. Bagian ini diberi tanggal sesuai tag tempat ia dirilis alih-alih dibagi antara <code>v0.19.84</code> dan <code>v0.20.0</code>, karena setiap entri di dalamnya lebih tua dari keduanya.","changelog.14161839f591":"Semua yang ada di bawah ini lebih tua dari rilis Build 1–3 dan tidak pernah dipindahkan ke bagian versi mana pun. Isinya dibiarkan di sini tanpa diubah alih-alih dimasukkan secara surut ke <code>0.21.0</code>–<code>0.23.0</code> berdasarkan tebakan; memilahnya adalah pekerjaan tersendiri.","changelog.f1873f116239":"TASK-098 — i18n Fluent penuh dari ujung ke ujung di seluruh 18 lokal (2026-05-11)","changelog.495b18f2f513":"Loader Fluent 18 lokal kini sudah tersambung. Mengganti bahasa di Pengaturan → Lokal (atau di wisaya jalankan pertama) merender ulang setiap string terjemahan di UI — menu, bilah status, panel pengaturan, dialog, dan wisaya — tanpa restart.","changelog.78760917c35b":"<strong>Pemuat.</strong>","changelog.5f1a08de08be":"<code>apps/freally-ui/src/lib/i18n/bundle.ts</code> menggantikan string inline <code>EN_FTL</code> dari Fase 11 dengan <code>import.meta.glob(&quot;../../../../../locales/*/freally.ftl&quot;, { query: &quot;?raw&quot;, eager: true })</code>. Ke-18 berkas <code>.ftl</code> di-inline saat build; setiap <code>FluentBundle</code> menumpuk <code>en</code> di bawahnya sebagai sumber cadangan sehingga kunci yang hilang akan muncul dalam bahasa Inggris, bukan sebagai string kunci mentah.","changelog.a9d6f49ee814":"<code>vite.config.ts</code> memperluas <code>server.fs.allow</code> ke root workspace agar mode dev dapat membaca tree lokal yang berada di luar root paket.","changelog.d354155cedc1":"<code>bundle.ts</code> mengekspor <code>loadedLocales()</code> agar rangkaian tes dapat memastikan glob benar-benar mengambil ke-18 berkas.","changelog.50aa545a0dff":"<strong>Data terjemahan — keselarasan Aturan Tetap #4.</strong>","changelog.c8b21089e4f2":"<code>en/freally.ftl</code> bertambah dari 314 menjadi 557 kunci. Ke-243 tambahan itu mencakup penyempurnaan wisaya (petunjuk, placeholder, &quot;Langkah N dari N&quot;), segmen bilah status, string lensa / pratinjau / markah, dialog Tentang / Sambungkan, setiap petunjuk panel + judul bagian + toast UI/Beranda/Cadangkan/Papan Ketik/Riwayat/Lokal/Folder/Volume, dan seluruh bilah menu PRD §8.28 (setiap label Berkas/Edit/Tampilan/Cari/Markah/Alat/Bantuan + setiap judul submenu + setiap petunjuk hover).","changelog.8f7a7778b776":"243 kunci yang sama dicerminkan ke ke-17 lokal lainnya secara paralel (es, de, fr, it, nl, pl, pt-BR, tr, vi, id, ru, uk, ar, hi, ja, ko, zh-CN). Setiap <code>.ftl</code> kini me-resolve 557 kunci yang sama; tes keselarasan baru <code>tests/unit/i18n.test.ts</code> memastikannya pada setiap run CI.","changelog.3b3366de3c39":"<strong>Konversi komponen.</strong>","changelog.c65098e5c147":"<code>menu_spec.ts</code> mendapat kunci <code>l10n</code> pada setiap <code>MenuItemSpec</code> dan <code>MenuSubmenu</code>, ditambah <code>hintL10n</code> untuk petunjuk hover di bilah status. <code>MenuBar.svelte</code> me-resolve-nya melalui helper <code>labelOf(spec)</code> / <code>hintOf(spec)</code> yang kembali ke <code>label</code>/<code>hint</code> literal saat kunci terjemahan tidak ada.","changelog.ef3a0f5b03d9":"FirstRunWizard merender judulnya, hitungan langkah, judul + petunjuk setiap langkah, kartu tema, dan tombol Kembali/Berikutnya/Selesai melalui <code>t()</code>. Langkah tombol pintas sudah dihapus pada putaran wisaya sebelumnya; konfigurasi tombol pintas tetap ada di Pengaturan → Papan Ketik.","changelog.4124e2c07aee":"StatusBar memakai <code>t()</code> untuk segmen fase indeks (&quot;Terindeks (N berkas)&quot; / &quot;Mengindeks… N/M&quot; / &quot;Dijeda&quot; / &quot;Galat&quot;), pluralisasi jumlah hasil (<code>status-result-count-one</code> vs <code>…-many</code>), lencana ukuran pilihan, waktu kueri, lencana waktu lensa, dan segmen DB lokal / endpoint jarak jauh. <code>aria-label</code> tombol putar tema dan petunjuk hover tombol pintas kini dapat diterjemahkan.","changelog.a3b5fe09b103":"Dialog pengaturan — <code>SettingsDialog.svelte</code>, <code>SettingsTreeNav.svelte</code>, <code>SettingsButtonBar.svelte</code>, <code>LocalePanel.svelte</code>, ditambah panel-panel di grup Indeks, Lensa, Jaringan, dan Lain-lain (UI / Beranda / Cari / Hasil / Tampilan / Menu Konteks / Font &amp; Warna / Papan Ketik / Indeks-atas / Volume / Folder / Daftar Berkas / Kecualikan / Nama Berkas / Konten / Audio / Kemiripan / Kustom / HTTPS / ETP / Riwayat / Privasi / Log / Cadangkan / Tentang).","changelog.f3afe9f2e294":"Markah, panel pratinjau, serta kontrol keadaan kosong / ciutkan <code>LensSection</code>.","changelog.7ad5ec734228":"<strong>RTL kini otomatis, bukan kotak centang.</strong>","changelog.adaca56bf336":"Kotak centang &quot;Pratinjau RTL&quot; di Pengaturan → Lokal sudah dihapus. RTL berlaku otomatis untuk lokal yang aksara aslinya RTL — saat ini <code>ar</code> adalah satu-satunya lokal rilis dalam kelompok itu. <code>applyRtlForLocale</code> merujuk allowlist internal <code>RTL_LOCALES</code>; bidang <code>locale_settings.rtl_preview</code> milik <code>bootstrap.ts</code> tetap ada di state tersimpan demi kompatibilitas mundur, tetapi UI tidak lagi menampilkannya.","changelog.b2a93dfa6039":"<strong>Tes.</strong>","changelog.cd3c3612b144":"<code>tests/unit/i18n.test.ts</code> yang baru mencakup: (a) glob benar-benar memuat ke-18 lokal, (b) <code>bundleFor(code)</code> mengembalikan bundle yang me-resolve kunci canary untuk setiap lokal, (c) ke-18 lokal selaras sempurna dalam himpunan kuncinya, (d) mengganti <code>settingsStore.state.locale</code> mengubah apa yang dikembalikan <code>t()</code>, (e) lokal yang tidak dikenal kembali melalui <code>en</code> alih-alih ke string kunci mentah, (f) kunci yang tidak dikenal mengembalikan kunci itu sendiri.","changelog.82baaedc9013":"Putaran penyempurnaan Fase 12 — UX, keandalan, dan penerapan langsung (2026-05-11)","changelog.2907b565b163":"Putaran perilaku besar selama sesi debugging yang panjang. Sebagian besar perbaikan adalah peningkatan kesetaraan langsung dengan voidtools-Everything ditambah pekerjaan keandalan mendasar yang membuat aplikasi desktop nyaman dijalankan berulang kali selama pengembangan.","changelog.f8b766536c97":"<strong>Instance tunggal + boot daemon yang tidak memblokir.</strong>","changelog.e7d0360bc90d":"<code>kill_other_freally_instances()</code> berjalan di awal <code>run()</code> di Windows (taskkill <code>/F /T</code> terhadap <code>freally-ui.exe</code> + <code>freally-indexd.exe</code>, difilter ke PID ≠ diri sendiri) sehingga meluncurkan ulang aplikasi selalu dimulai dari keadaan bersih tanpa perlu mematikan proses secara manual. Stub untuk macOS / Linux demi kesetaraan.","changelog.a731267547b9":"<code>Daemon::boot</code> kini menjalankan thread khusus <code>freally-daemon-boot</code> di dalam <code>tauri::Builder::setup</code>; hook setup langsung kembali dan jendela segera muncul. Sebelumnya, pemutaran ulang canonical store dapat memblokir thread GUI selama 10-15 s, memicu watchdog jendela tidak merespons di Windows dan meruntuhkan proses sebelum HWND apa pun ada.","changelog.59d90e38c9ea":"<code>Client::connect</code> dibungkus dalam loop percobaan ulang 500 × 40 ms di sisi konsumen sehingga boot daemon yang lambat tidak kalah oleh satu race koneksi.","changelog.2f85875a08d3":"<strong>Chip filter + menu Cari — pilihan ganda dengan komposisi OR.</strong>","changelog.9f34cca2f956":"<code>lib/stores/type_filter.svelte.ts</code> yang baru menyimpan <code>Set&lt;TypeFilterId&gt;</code>; bawaannya adalah himpunan penuh (mode Everything). <code>toQueryFragment()</code> menghasilkan grup tingkat parser <code>(audio: OR video: OR …)</code> untuk pilihan parsial, dan string kosong untuk &quot;semua&quot; atau &quot;tidak ada&quot;, sehingga jebakan AND-dari-prefiks di sisi daemon hilang.","changelog.8adb4f889882":"Chip <code>QuickFiltersPalette.svelte</code> langsung mengubah store; item menu di <code>Search → …</code> beralih dari <code>radio</code> ke <code>checkable</code>, dengan <code>MenuBar.isItemChecked</code> membaca store. &quot;Everything&quot; diturunkan dari <code>selected.size === ALL.length</code> — mengklik chip individual mana pun mematikan chip itu sekaligus Everything, dan membiarkan yang lain.","changelog.5246ff18704a":"<code>bookmarks.add</code> menyimpan set filter aktif bersama teks pencarian; DTO <code>Bookmark</code> di Rust mendapat <code>filters: Vec&lt;String&gt;</code> dengan <code>#[serde(default)]</code> sehingga berkas <code>bookmarks.json</code> yang sudah ada tetap dapat dideserialisasi. Mengklik markah memulihkan isi kotak teks (melalui <code>queryStore.setSource</code>) sekaligus pilihan chip (melalui <code>typeFilterStore.setFromIds</code>).","changelog.942a0601c778":"Token Arsip diperbaiki: <code>compressed: &quot;zip:&quot;</code> → <code>&quot;archive:&quot;</code> (alias <code>QuickFilter::Archive</code> yang sebenarnya dari <code>freally-query::quick_filters</code>). <code>zip:</code> yang lama hanyalah satu ekstensi di dalam grup, sehingga Arsip tidak pernah mencocokkan apa pun.","changelog.6de9bf011469":"<strong>Kueri Everything awal + kesetaraan mode Everything.</strong>","changelog.29e61abbcb91":"<code>runInitialEverythingQuery()</code> di <code>bootstrap.ts</code> dipicu sekali setelah hydrate dan melakukan polling <code>resultsStore.batches.length</code> hingga 60 × 800 ms, memicu panggilan <code>run()</code> baru hanya saat tidak ada yang sedang berjalan agar pemicuan otomatis tidak membatalkan kuerinya sendiri. Tampilan pertama setelah peluncuran langsung menampilkan hasil alih-alih &quot;Ketik kueri untuk memulai.&quot;","changelog.c323e4a1d454":"Saat seluruh himpunan filter tipe dipilih dan kotak pencarian kosong, <code>resultsStore.run()</code> menyusun wildcard <code>*</code> polos sehingga lensa nama berkas mencantumkan setiap entri yang terindeks (kesetaraan dengan voidtools-Everything).","changelog.2c27ce8face6":"Gerbang placeholder <code>ResultList.svelte</code> diperbarui: menampilkan &quot;Ketik kueri untuk memulai&quot; hanya saat sumbernya kosong DAN tidak ada filter tipe yang dipilih (yaitu pengguna secara eksplisit membatalkan pilihan setiap chip).","changelog.28ad0f2414d6":"<strong>Pengindeksan folder.</strong>","changelog.c21ab8d7106b":"<code>crates/freally-indexd/src/scanner.rs::scan_folder</code> kini mengindeks direktori bersama berkas; jalur walkdir memfilter dengan <code>is_file() || is_dir()</code> dan mencap <code>FILE_ATTRIBUTE_DIRECTORY (0x10)</code> ke bidang <code>attrs</code> peristiwa journal.","changelog.799bfffa54d6":"Jalur bootstrap MFT di <code>crates/freally-journal-win/src/subscriber.rs</code> tidak lagi melewati rekaman direktori — rekaman itu ikut diteruskan dengan bitmask <code>file_attributes</code> aslinya tetap utuh.","changelog.709c7429febd":"<code>QueryHit</code> (DTO Rust + interface TS yang sepadan) mendapat bidang <code>attrs: u32 #[serde(default)]</code> yang diisi daemon dari <code>FileRow.attrs</code>. UI membedakan berkas dan folder melalui bit <code>0x10</code>.","changelog.694ce7c4310f":"<strong>Ikon shell Windows asli + render per baris.</strong>","changelog.4479cd257069":"<code>apps/freally-ui/src-tauri/src/commands/icons.rs</code> yang baru — perintah Tauri async <code>icon_for_ext(ext, is_dir) -&gt; Option&lt;String&gt;</code> yang menjalankan <code>SHGetFileInfoW</code> Win32 dengan <code>SHGFI_USEFILEATTRIBUTES</code> (sehingga path tiruan seperti <code>_.xml</code> me-resolve ikon handler yang terdaftar tanpa berkas itu benar-benar ada di disk) → <code>GetIconInfo</code> → BGRA 32-bit melalui <code>GetDIBits</code> → penukaran kanal BGRA→RGBA → PNG melalui crate <code>image</code> → data URL base64. Untuk saat ini mengembalikan <code>None</code> di macOS / Linux.","changelog.6794e87b4eb5":"<code>src-tauri/Cargo.toml</code>: menambahkan <code>image = &quot;0.25&quot; --no-default-features --features png</code>, <code>base64 = &quot;0.22&quot;</code>, dan set fitur <code>windows = &quot;0.59&quot;</code> yang relevan di bawah <code>cfg(windows)</code>.","changelog.9e73805e7e38":"<code>lib/stores/icon_store.svelte.ts</code> yang baru — cache <code>Map&lt;(ext, is_dir), Promise&lt;dataUrl | null&gt;&gt;</code> sehingga 200 baris hasil memicu satu IPC per ekstensi unik, bukan per baris. Bidang reaktif <code>tick</code> yang bertambah pada setiap resolusi agar konsumen $derived merender ulang.","changelog.872e5a605907":"Kolom Nama di <code>ResultRow.svelte</code> merender <code>&lt;img class=&quot;row-icon&quot; src=…&gt;</code> yang diambil dari <code>iconStore.get(hit.ext, isDir)</code>, dengan emoji cadangan (<code>📁</code> / <code>📄</code>) selama data URL dimuat.","changelog.eb2ed58a295d":"<strong>Metadata asli dalam bootstrap MFT.</strong>","changelog.392710a87044":"Rekaman USN membawa FRN + attrs + satu stempel waktu tetapi tanpa ukuran berkas, sehingga jalur cepat MFT dulu menulis <code>size: 0</code> dan stempel waktu khusus USN ke indeks. <code>subscriber.rs</code> kini menjalankan <code>std::fs::metadata(&amp;full)</code> per peristiwa yang dipancarkan untuk mengisi <code>len</code>, <code>modified</code>, <code>created</code> yang sebenarnya. Lebih lambat daripada penelusuran USN murni tetapi benar — kolom Ukuran dan Diubah akhirnya menampilkan nilai bukan nol tanpa memaksa beralih ke walkdir.","changelog.693e07211105":"<strong>Visual kotak pencarian + baris hasil.</strong>","changelog.660ce86cdba0":"<code>SearchBar.svelte</code> kini mengikat <code>&lt;input value={queryStore.source}&gt;</code> sehingga pembaruan terprogram (klik markah, pembersihan dengan Escape, deep-link di masa depan) tercermin di kotak teks. Juga membuang <code>color: transparent</code> yang rusak pada <code>.raw</code> (lapisan sorotan sintaks &quot;cermin&quot; tidak sejajar, sehingga teks yang diketik praktis tidak terlihat dalam mode gelap) — input kini merender teksnya sendiri dan cermin disembunyikan.","changelog.40ca8d425ec9":"CSS baris di <code>ResultRow.svelte</code> membaca <code>--row-{state}-fg/bg/weight/style</code> sehingga kontrol per keadaan di panel Font &amp; Warna berlaku langsung. Keadaan yang tersambung: normal, tersorot (hover), terpilih, terpilih (tersorot).","changelog.5442f7a05dd7":"Memperbaiki bug spesifisitas baris berselang-seling + hover yang membuat baris terpilih tampak tidak terpilih saat aturan <code>:nth-child(even)</code>-nya mengalahkan <code>.row.selected</code>. Kedua selektor kini memakai <code>:not(.selected)</code> sehingga baris terpilih mempertahankan rona cyan-nya terlepas dari indeks atau hover.","changelog.1e3c5fb60489":"<strong>Penerapan langsung + persistensi Font &amp; Warna.</strong>","changelog.99c1c70df3e3":"<code>lib/stores/fonts_apply.svelte.ts::applyFontsAndColors()</code> yang baru menulis CSS custom property pada <code>&lt;html&gt;</code> dari <code>settings.fonts_and_colors</code>: <code>--font-ui</code> (dengan rantai cadangan lintas OS), <code>--app-font-size</code>, <code>--row-…-fg/bg/weight/style</code> per keadaan, dan override <code>--lens-…</code> per lensa. Dipanggil sekali saat bootstrap (setelah hydrate) dan lagi pada setiap patch panel — dipulihkan antarpeluncuran dan diterapkan langsung saat berubah.","changelog.bd2af6cb049b":"Input font di <code>FontsAndColorsPanel.svelte</code> diganti menjadi menu turun <code>&lt;select&gt;</code> yang diisi melalui <code>window.queryLocalFonts()</code> (Local Font Access API yang didukung runtime WebView2 Tauri 2 di Windows) dengan cadangan 25 keluarga font pilihan untuk webview non-Chromium. Setiap opsi dirender dengan font-nya sendiri sebagai pratinjau visual.","changelog.0f1775f6dcaa":"Menu turun Tema di UIPanel memanggil <code>themeStore.set(value)</code> bersama patch pengaturan sehingga peralihan terang/gelap diterapkan langsung saat dipilih — tanpa perlu Terapkan / restart.","changelog.e689bf04af40":"<strong>Sakelar panel Tampilan tersambung.</strong>","changelog.af26fe7a3745":"$effect di App.svelte mencerminkan pengaturan terpilih ke atribut <code>&lt;body data-*&gt;</code>; aturan CSS baru di <code>app.css</code> bereaksi terhadapnya: <code>data-alternate-rows</code>, <code>data-row-mouseover</code> (mengubah <code>.row:hover</code> menjadi tanpa efek saat false), <code>data-show-tooltips</code>, <code>data-show-lufs-badges</code>, <code>data-show-similarity-score</code>.","changelog.ba63c32bf658":"<code>title={hit.path}</code> pada baris <code>ResultRow</code> bergantung pada pengaturan Tampilkan tooltip.","changelog.be551e42463a":"<code>formatBytes</code> mematuhi pengaturan Format ukuran (<code>auto_binary</code> | <code>bytes</code> | <code>kb</code> | <code>mb</code> | <code>gb</code>).","changelog.eb09c95dc5e6":"<strong>Kontrol jendela — selalu di atas, ukuran, zoom.</strong>","changelog.f6f1716eda05":"<code>capabilities/default.json</code> menambahkan izin <code>core:window:allow-set-size</code>, <code>core:window:allow-set-always-on-top</code>, <code>core:window:allow-set-resizable</code>, <code>core:window:allow-inner-size</code>, <code>core:window:allow-outer-size</code> yang sebelumnya tidak ada. Tanpa izin ini, setiap panggilan <code>setSize</code> / <code>setAlwaysOnTop</code> ditolak diam-diam oleh gerbang izin IPC Tauri.","changelog.b60bdf35fa6a":"App.svelte mendapat <code>$effect</code> yang menerjemahkan <code>settings.on_top</code> + <code>queryStore.source</code> menjadi panggilan <code>setAlwaysOnTop(...)</code>: mode Tidak pernah / Selalu / Saat Mencari semuanya berfungsi, diterapkan ulang pada setiap perubahan pengaturan dan setiap ketukan tombol. Dipulihkan saat peluncuran.","changelog.1f927e0b3720":"Impor <code>setWindowSize</code> diperbaiki: <code>LogicalSize</code> berasal dari <code>@tauri-apps/api/window</code>, bukan <code>@tauri-apps/api/dpi</code> yang tidak ada. Ukuran yang dipilih juga menulis <code>settings.window_size = { w, h }</code> (masuk allowlist di <code>ALLOWED_PATCH_KEYS</code>), dan bootstrap memulihkan ukuran tersimpan pada peluncuran berikutnya.","changelog.293b3c2deb7d":"<code>zoomStore</code> beralih dari <code>document.documentElement.style.fontSize</code> ke properti CSS <code>zoom</code> milik WebView sehingga Ctrl+= / Ctrl+- benar-benar mengubah skala UI (yang berbasis px). Tajam di semua faktor.","changelog.7e52e273d7e8":"<strong>Pratinjau gambar.</strong>","changelog.6aa7a3ed566b":"<code>preview/windows_host.rs::preview</code> mengembalikan data URL gambar asli untuk PNG, JPG/JPEG/JFIF, GIF, WEBP, BMP, SVG, ICO, AVIF: membaca berkas (batas 4 MiB), meng-encode melalui <code>commands::files::base64_encode</code>, dan mengembalikan <code>PreviewPayload { kind: Image, data_url: &quot;data:image/…;base64,…&quot; }</code>. Ekstensi non-gambar tetap mengembalikan <code>None</code> sehingga cadangan text-head menangani berkas teks.","changelog.d2769be53d10":"<code>files_preview</code>, <code>files_thumbnail</code>, dan <code>icon_for_ext</code> kini menjadi <code>async fn</code> dan memindahkan pekerjaan sebenarnya ke <code>tokio::task::spawn_blocking</code>. Versi sinkronnya memblokir thread dispatch IPC Tauri selama beberapa detik saat ekstraksi ikon shell + encoding base64 berukuran beberapa MB, yang membekukan seluruh UI.","changelog.2e8adf41da90":"Memperbaiki <code>PreviewPane.svelte</code> yang memanggil <code>files.whitelistUserChosen</code> yang tidak ada — helper itu berada di <code>ipc/bookmarks.ts</code> tetapi panel mengimpor <code>* as files from &quot;ipc/files&quot;</code>. <code>whitelistUserChosen</code> diekspor ulang dari <code>ipc/files.ts</code> agar panggilan itu ter-resolve; <code>TypeError</code> sinkron tersebut membuat <code>loading = true</code> selamanya dan memblokir $effect pratinjau.","changelog.932173fca555":"Menambahkan tracing Rust pada jalur pratinjau / ikon ditambah perintah Tauri <code>log_event</code> untuk meneruskan peristiwa konsol TS ke log dev cargo, serta <code>std::panic::set_hook</code> yang memunculkan panic Rust di konsol.","changelog.6ef1e2ccf454":"<strong>Endpoint FTP + tombol Putuskan berwarna abu-abu.</strong>","changelog.5b6f4670d959":"<code>ConnectEndpointDialog.svelte</code> baru yang meniru dialog voidtools: Host (wajib), Port (bawaan 21), Nama pengguna, Kata sandi, menu turun Tipe tautan. Saat OK, menulis <code>settings.endpoint = { name: host, kind: &quot;ftp&quot; }</code>.","changelog.93d8e6c9ea7d":"<code>MenuBar.isItemEnabled</code> mengembalikan <code>false</code> untuk <code>tools.disconnect_endpoint</code> saat <code>settings.endpoint.kind === &quot;local&quot;</code>; CSS menambahkan gaya abu-abu <code>.item.disabled</code> dengan <code>pointer-events: none</code>.","changelog.dc6508212cbc":"<code>View → Filters</code> kini memilih panel <code>indexes.exclude</code> terlebih dahulu sebelum membuka dialog pengaturan (kesetaraan dengan voidtools-Everything).","changelog.8886320c4765":"<strong>Pengecualian — kelas ekstensi yang dapat dialihkan + penghapusan duplikat.</strong>","changelog.66be911445f7":"Tombol kelas ekstensi di <code>ExcludePanel.svelte</code> (Video / Audio / Gambar / Arsip / Berkas Eksekusi) kini berfungsi sebagai sakelar: klik menambahkan glob kelas itu dan menyorot tombolnya; klik lagi menghapusnya dan menghilangkan sorotan. &quot;Aktif&quot; dihitung sebagai &quot;setiap glob di kelas itu saat ini ada di himpunan berkas yang dikecualikan&quot; sehingga sorotan mencerminkan keadaan sebenarnya, bukan sekadar klik terakhir.","changelog.b4936ee1d7c7":"<code>Add Folder…</code> dan <code>Apply OS-recommended excludes</code> sama-sama menghapus duplikat sehingga entri yang sama tidak pernah ditambahkan dua kali.","changelog.fd67542ffabe":"<strong>Keandalan markah.</strong>","changelog.07a8ba50f22e":"<code>bookmarks.add</code> tidak lagi mensyaratkan kueri yang tidak kosong — markah dengan kueri kosong diizinkan (diberi nama &quot;Bookmark N&quot; agar pengguna dapat mengganti namanya di Atur Markah). Kunci penghapusan duplikat kini berupa (nama, kueri, set filter).","changelog.eccef664591a":"<code>bookmarksStore.hydrate()</code> mencoba ulang setiap 500 ms hingga ~10 s sehingga hydrate pertama tidak kehilangan daftar markah karena galat IPC daemon-belum-siap selama jendela boot di latar belakang.","changelog.002b1009c89f":"<code>bookmarks.organize</code> melakukan hydrate ulang sebelum membuka dialog Atur Markah sehingga menu turun yang basi tidak dapat menampilkan &quot;Belum ada markah&quot; padahal ada markah di disk.","changelog.c399ec40a64b":"<strong>Lain-lain.</strong>","changelog.0437b05ad147":"Filter bawaan <code>tracing_subscriber</code> dinaikkan menjadi <code>warn,freally=info,freally_ui_lib=info,freally_indexd=info</code> sehingga instrumentasi muncul tanpa harus memaksakan <code>RUST_LOG</code>.","changelog.64b28a5c4c3d":"<code>markDirty</code> di dialog pengaturan kini juga memanggil <code>applyFontsAndColors()</code> di dalam jalur patch panel Font &amp; Warna sehingga pratinjaunya instan.","changelog.1f355d627a40":"<code>ipc/types.ts::QueryHit</code> mendapat <code>attrs?: number</code>; <code>Bookmark</code> mendapat <code>filters?: string[]</code>. Keduanya opsional demi kompatibilitas ke depan.","changelog.3df684c915d5":"<strong>[semua platform]</strong> Dialog pengaturan Fase 12 + IPC daemon sungguhan + framework pengekstrak kustom + i18n. Menggantikan lapisan IPC tiruan Fase 11 dengan transport JSON-RPC berawalan panjang <code>freally-rpc</code> yang sungguhan melalui Unix socket / named pipe per pengguna, dan menghadirkan dialog pengaturan PRD §8.1-§8.27 secara penuh serta host pengekstrak kustom dengan kotak pasir Wasm.","changelog.cbb79fe44d28":"<strong>Crate baru <code>freally-rpc</code></strong> (di bawah <code>crates/freally-rpc/</code>) — fondasi yang memungkinkan UI Tauri dan CLI <code>freally</code> yang baru sama-sama berbicara dengan protokol yang sama ke satu instance <code>freally-indexd</code>.","changelog.b4d3e8bb408c":"<code>frame.rs</code>: framing berawalan panjang u32-BE dengan batas keras payload 16-MiB sehingga peer jahat tidak dapat membuat server kehabisan memori dengan satu awalan panjang 4-GiB.","changelog.9eee30718562":"<code>jsonrpc.rs</code>: amplop Request / Response / Notification JSON-RPC 2.0; enum untagged <code>ResponseEnvelope</code> membedakan satu frame sebagai respons atau sebagai notifikasi yang didorong server.","changelog.3cae329c5ea1":"<code>service.rs</code>: trait <code>Service</code> yang diimplementasikan <code>freally-indexd</code>; <code>NotificationSink</code> memungkinkan handler metode mendorong notifikasi asinkron melalui koneksi yang sama.","changelog.a60b3df0f5d6":"<code>server.rs</code>: loop accept per koneksi dengan antrean keluar terbatas (<code>PER_CONN_OUT_QUEUE = 256</code>); menjalankan satu task penulis per koneksi dan satu task fan-in notifikasi yang meneruskan <code>Notification</code> ke antrean penulis. <code>handle_connection_for_tests</code> menyediakan isi loop yang sama melalui <code>tokio::io::duplex</code> untuk tes integrasi di bawah satu detik.","changelog.829538dc4efb":"<code>client.rs</code>: <code>ClientHandle::call()</code> bertipe dengan kanal balasan oneshot per panggilan; <code>notifications()</code> mengembalikan langganan broadcast tokio. Task pembaca menguras pemanggil yang tertunda dengan bentuk <code>transport closed</code> yang bersih saat EOF.","changelog.91eab238f9d7":"<code>transport/unix.rs</code>: <code>UnixListener::accept_authenticated()</code> membaca kredensial peer melalui <code>tokio::net::UnixStream::peer_cred()</code> dan menolak peer mana pun yang UID-nya tidak sama dengan proses saat ini — dikombinasikan dengan mode berkas 0600 yang disetel di <code>listen()</code>, ini berarti pengguna lain di mesin yang sama tidak dapat tersambung meskipun mengetahui path-nya. Direktori induknya juga di-chmod 0700 sebagai pengaman ganda.","changelog.fcfcdf081a40":"<code>transport/windows.rs</code>: <code>ServerOptions::create_with_security_attributes_raw</code> dengan SECURITY_DESCRIPTOR yang dihasilkan dari string SDDL berbentuk <code>D:(A;;GA;;;&lt;userSid&gt;)(A;;GA;;;SY)</code> — hanya pengguna saat ini (di-resolve melalui <code>OpenProcessToken</code> + <code>GetTokenInformation(TokenUser)</code> + <code>ConvertSidToStringSidW</code>) dan SYSTEM yang memegang ACE Access-Allowed. Tanpa <code>Everyone</code>, tanpa <code>Authenticated Users</code>. <code>reject_remote_clients(true)</code> memblokir akses pipe lewat jaringan. <code>LocalFree</code> dibungkus dalam guard RAII <code>SdDrop</code> sehingga security descriptor tetap dibebaskan bahkan pada jalur galat yang kembali lebih awal.","changelog.336f8a676048":"<code>path.rs</code>: path socket / pipe bawaan konvensional per OS. macOS: <code>~/Library/Application Support/freally/indexd.sock</code>. Linux: <code>$XDG_RUNTIME_DIR/freally/indexd.sock</code> dengan cadangan <code>~/.local/share/freally/indexd.sock</code>. Windows: <code>\\\\.\\pipe\\freally-indexd-&lt;userSid&gt;</code> (diberi tanda SID sehingga dua pengguna di host Windows yang sama mendapat pipe terpisah).","changelog.81b6aadfed10":"<code>dto.rs</code>: DTO serde yang mencerminkan <code>apps/freally-ui/src/lib/ipc/types.ts</code> byte demi byte — varian enum <code>serde(rename_all = &quot;lowercase&quot;)</code> yang sama, <code>serde(rename = &quot;type&quot;)</code> yang sama untuk kunci JSON <code>kind</code>, bentuk bidang yang sama. Audit kesetaraan Fase 12 memastikan keluaran JSON yang stabil per byte terhadap fixture yang di-commit.","changelog.022aca1457de":"<strong>Crate baru <code>freally-extractor-host</code></strong> (di bawah <code>crates/freally-extractor-host/</code>) — framework pengekstrak kustom dengan kotak pasir Wasm. Tidak tepercaya secara bawaan sesuai model kepercayaan Fase 12.","changelog.9b6d93374feb":"<code>manifest.rs</code>: skema TOML dengan <code>id</code>, <code>display_name</code>, <code>version</code>, <code>formats: Vec&lt;String&gt;</code>, <code>magic: Vec&lt;String&gt;</code> opsional (spesifikasi khusus byte hex seperti <code>&quot;0x23 0x20&quot;</code>), <code>sidecar</code> (path ke biner <code>*.wasm</code>, divalidasi keberadaannya saat dimuat), <code>time_budget_ms</code> (bawaan 1000), <code>memory_budget_mb</code> (bawaan 64). Spesifikasi magic yang buruk ditolak saat dimuat.","changelog.bca0da3b05e5":"<code>registry.rs</code>: pemindai <code>&lt;index_root&gt;/extractors/</code> yang memuat <code>manifest.toml</code> dari setiap subdirektori. <code>registry.toml</code> mencatat status kepercayaan pengguna per pengekstrak, hash blake3 untuk deteksi manipulasi, dan penghitung crash yang otomatis menonaktifkan pengekstrak yang crash 3 kali atau lebih berturut-turut sampai pengguna memercayainya kembali. Persistensi memakai tulis-sementara-lalu-ganti-nama melalui <code>toml::to_string_pretty</code>. <code>set_trusted</code> mengosongkan penghitung crash saat dipercaya kembali.","changelog.b8bcebf716a9":"<code>sandbox.rs</code>: host <code>wasmtime</code> dengan jaminan ketat — <code>Config::consume_fuel(true)</code> memberlakukan anggaran CPU per panggilan (<code>fuel = time_budget_ms × 1_000_000</code>); pemeriksaan <code>Memory::data_size</code> setelah panggilan memberlakukan anggaran memori per panggilan. Hanya dua fungsi host yang terlihat oleh guest: <code>host_log(ptr: i32, len: i32)</code> (log debug, dipotong pada 4 KiB) dan <code>host_now_ms() -&gt; i64</code> (disuntikkan host, sama dengan <code>now_ms</code> milik permintaan sehingga guest tidak dapat mengamati waktu nyata secara mandiri). Tanpa <code>wasi:sockets</code>, tanpa <code>wasi:filesystem-write</code>, tanpa <code>wasi:clocks</code>. Guest mengekspor <code>alloc(size) -&gt; i32</code> dan <code>extract(ptr, len) -&gt; i64</code> (32 bit atas = pointer hasil, 32 bit bawah = panjang hasil). Batas 16-MiB pada panjang hasil sehingga sidecar jahat tidak dapat mengembalikan blob 4-GiB.","changelog.c9d6d857a602":"<strong>Refaktor library + biner <code>freally-indexd</code>.</strong> Biner khusus service dari Fase 1-3 menjadi library + shim tipis. Library-nya menyediakan <code>DaemonState</code> (wadah state bersama yang memegang <code>Arc&lt;Index&gt;</code>, <code>Arc&lt;AudioCache&gt;</code>, <code>Pipeline</code>, <code>Registry</code>, ditambah konfigurasi tersimpan <code>volumes / folders / excludes / network / history</code> di <code>&lt;index_root&gt;/config/</code> sebagai berkas TOML) dan <code>IndexdService</code> (impl <code>Service</code> yang mendispatch setiap metode yang dicantumkan di PRD §8.30). Modul baru:","changelog.2d2defa4d194":"<code>service.rs</code>: dispatch bertipe untuk <code>query.run</code> / <code>query.cancel</code> / <code>query.lens_timings</code> / <code>index.state</code> / <code>index.verify</code> / <code>index.compact</code> / <code>index.rebuild</code> / <code>extractors.list</code> / <code>extractors.set_mode</code> / <code>volumes.list</code> / <code>volumes.update</code> / <code>volumes.recreate_journal</code> / <code>volumes.reset_stream</code> / <code>volumes.upgrade_fanotify</code> / <code>volumes.remove</code> / <code>folders.list</code> / <code>folders.add</code> / <code>folders.remove</code> / <code>folders.update</code> / <code>folders.rescan</code> / <code>folders.rescan_all</code> / <code>excludes.get</code> / <code>excludes.set</code> / <code>network.status</code> / <code>network.start_https</code> / <code>network.stop_https</code> / <code>network.regen_token</code> / <code>network.start_api</code> / <code>network.stop_api</code> / <code>custom_extractors.list</code> / <code>custom_extractors.set_trusted</code> / <code>custom_extractors.refresh_hashes</code> / <code>history.get</code> / <code>history.set</code> / <code>history.clear</code> / <code>preview.text_head</code> / <code>preview.thumbnail</code> / <code>settings.apply</code> / <code>daemon.shutdown</code>. <code>query.run</code> mengalirkan notifikasi <code>query:batch</code> / <code>query:done</code> kembali ke klien (sisi Tauri memancarkannya ulang sebagai event Tauri yang dikonsumsi store Svelte).","changelog.d58ec7a0cdfb":"<code>state.rs</code>: <code>DaemonState::open(opts)</code> membuka indeks, cache audio, registri pengekstrak kustom, dan membaca TOML konfigurasi yang tersimpan. <code>DaemonState::persist()</code> menulis semuanya kembali secara atomik. Tipe <code>VolumesConfig</code>, <code>VolumeOverride</code>, <code>NetworkState</code>, <code>HistoryConfig</code> masing-masing menangani persistensi bagiannya sendiri.","changelog.089d7c21d524":"<code>volumes.rs</code>: deteksi volume lintas OS — Windows menelusuri <code>GetLogicalDrives</code> + <code>GetVolumeInformationW</code> + <code>GetDiskFreeSpaceExW</code> dan menghasilkan baris NTFS / ReFS / exFAT / FAT32; macOS memindai <code>/Volumes</code> + <code>statvfs</code>; Linux membaca <code>/proc/mounts</code> (melewati sistem berkas semu) + <code>statvfs</code>. Setiap baris membawa <code>id</code> yang stabil (mis. <code>win-C</code>, <code>lin-_home</code>, <code>mac-Macintosh_HD</code>) sehingga override per volume dapat disimpan dan dimuat kembali dengan utuh.","changelog.60cb08f577a8":"<code>settings.rs</code>: payload bertipe <code>SettingsApply</code> untuk IPC <code>settings.apply</code>; daemon mengubah state yang relevan lalu menyimpannya. <code>random_token_fingerprint()</code> menghasilkan sidik jari tampilan pendek yang tidak rahasia yang ditampilkan di panel Jaringan.","changelog.17b91de7bef9":"<code>history.rs</code>: payload bertipe <code>HistoryUpdate</code> + hook <code>take_clear</code> untuk Fase 13 mendatang guna menghapus riwayat di sisi daemon.","changelog.b566f0999042":"<strong><code>apps/freally-ui/src-tauri</code> menjadi klien RPC.</strong>","changelog.b3d45fd8ffa1":"<code>commands/canned.rs</code> (dataset tiruan Fase 11) dihapus. Smoke test Fase 12 <code>tests/smoke/phase_12_indexd_client.rs::no_canned_rs_in_tree</code> menjaga agar penghapusan itu tidak mundur.","changelog.a467ed4a6368":"<code>daemon.rs</code> baru: mem-boot <code>freally-indexd</code> di dalam proses pada path socket bawaan per OS (override env <code>FREALLY_RPC_SOCKET</code> untuk tes), membuka klien <code>freally-rpc</code>, dan menjalankan task pemancar ulang notifikasi yang mengubah setiap notifikasi dari server menjadi event Tauri melalui <code>app.emit(method, payload)</code>. <code>Daemon::call/call_void</code> mengkloning klien dan menjalankan future di runtime tokio milik daemon, sehingga menghindari konflik move/borrow yang akan ditimbulkan oleh <code>Arc&lt;Daemon&gt;::block_on(async move {…})</code>.","changelog.2b8987c2135e":"<code>commands/query.rs</code>, <code>commands/index_state.rs</code>, <code>commands/extractors.rs</code>, ditambah <code>commands/volumes.rs / folders.rs / excludes.rs / network.rs / custom_extractors.rs / history.rs</code> yang baru — setiap isi perintah Tauri kini dialirkan melalui daemon. <code>query_parse</code> adalah satu-satunya pengecualian dalam proses — tokenisasi secepat ketukan tombol tidak sanggup menanggung round-trip ke daemon.","changelog.6a7142ad49d6":"<code>commands/files.rs</code> mempertahankan gerbang known-paths <code>verify_path</code> di sisi UI, tetapi <code>files_thumbnail</code> / <code>files_preview</code> kini mendelegasikan ke modul <code>preview</code> baru yang mendispatch ke host pratinjau native OS.","changelog.b19dfedad0ec":"<code>commands/settings.rs</code> mempertahankan persistensi lokal berbasis JSON dan mendapat HashMap <code>#[serde(flatten)] extras</code> yang menampung 70+ bidang tingkat atas Fase 12 tanpa membengkakkan permukaan skalar bertipe; <code>ALLOWED_PATCH_KEYS</code> diperluas untuk mencakup setiap kunci baru demi kontrak allowlist dari tinjauan keamanan; <code>phase_12_default_extras()</code> mengisi nilai bawaan Fase 12 sehingga <code>settings.json</code> pada instalasi baru menyertakan setiap bidang. Kontrak TS di <code>lib/ipc/types.ts</code> tidak berubah.","changelog.1469ccfaba03":"<strong>Host pratinjau native OS</strong> (<code>apps/freally-ui/src-tauri/src/preview/</code>). Struktur modul platform sudah tersedia; integrasi penuh setiap host menyala secara bertahap sebagai peningkatan kualitas UX yang tidak mengubah kontrak data-URL.","changelog.b4df5b094937":"<code>preview/macos.rs</code> — jembatan QuickLook (<code>QLPreviewPanel</code> untuk pratinjau penuh, <code>QLThumbnailGenerator</code> untuk gambar mini). Fase 12 menyertakan permukaan modul dan probe runtime; urutan panggilan <code>objc2</code> lengkap hadir sebagai peningkatan pada putaran penyempurnaan.","changelog.7c608576f7b1":"<code>preview/windows_host.rs</code> — handler pratinjau Shell (<code>IPreviewHandler</code> + <code>IThumbnailProvider</code> melalui windows-rs). Sikap yang sama — permukaannya sudah ada, jembatan COM hadir secara bertahap.","changelog.2350b7e13cc7":"<code>preview/linux.rs</code> — GNOME Sushi melalui DBus jika tersedia, KDE KIO melalui shell-out subproses jika tersedia. Deteksi berupa probe <code>gdbus introspect</code> / <code>kioclient5 --version</code> yang di-cache dengan <code>OnceLock</code> sehingga biaya per pratinjau menjadi nol setelah panggilan pertama.","changelog.94e452c9cf02":"<code>preview/fallback.rs</code> — cadangan untuk Unix yang jarang dipakai. Selalu mengembalikan None sehingga pemanggil beralih ke jalur universal text-head + ikon bertipe.","changelog.3c9eec3f6c4b":"<code>preview/mod.rs</code> — dispatch host + <code>text_head_fallback</code> (membaca hingga 4 KiB, mengklasifikasikannya sebagai teks jika dan hanya jika tidak ada byte NUL dan rasio karakter pengganti ≤ 1%).","changelog.67698e29fe12":"<strong>Dialog pengaturan</strong> (<code>apps/freally-ui/src/components/settings/</code>) — setiap kontrol PRD §8.2-§8.27 tersambung tanpa stub.","changelog.a3361a51edd5":"<code>SettingsDialog.svelte</code>: modal yang dapat diubah ukurannya (min 800×620, bawaan 960×720), tata letak navigasi pohon di kiri + panel detail di kanan + bilah tombol di bawah. Menyimpan node terakhir yang dipilih + posisi gulir per panel melalui localStorage sehingga membuka ulang dialog akan kembali ke panel terakhir yang dibuka pengguna.","changelog.24b28d6fc11f":"<code>SettingsTreeNav.svelte</code>: pohon PRD §8.1.1 lengkap (Umum / Riwayat / Indeks / Lensa / Jaringan / Privasi &amp; Pembaruan / Log &amp; Debug / Cadangkan, Ekspor, Reset / Lokal / Tentang). Kotak pencarian opsi memfilter node berdasarkan label dan kumpulan kata kunci per node. Panel yang berubah diberi tanda <code>•</code> ungu sehingga pengguna dapat melihat mana yang memiliki perubahan belum disimpan.","changelog.4f8f836e7ec7":"<code>SettingsButtonBar.svelte</code>: Kembalikan ke Bawaan (kiri, per panel), OK / Batal / Terapkan (kanan). Terapkan hanya aktif saat <code>settingsDialog.dirty</code>; OK menerapkan + menutup; Batal membatalkan perubahan melalui <code>SettingsDialogModel.cancel()</code> (<code>snapshot()</code> setiap store diambil saat dialog dibuka, <code>rollback()</code> memulihkannya); Kembalikan ke Bawaan mereset panel aktif melalui <code>SettingsDialogModel.resetPanel(panelId)</code>.","changelog.57b1a742578b":"26 komponen panel, satu per bagian PRD §8.2-§8.27. Sorotan:","changelog.66c58219af20":"<strong>Umum → UI</strong>: pemilih tema (berganti langsung), sakelar baki, varian klik tunggal, kepadatan baris, transisi cross-fade beranimasi.","changelog.cfe484eb7c32":"<strong>Umum → Beranda</strong>: tiga pilihan Gunakan nilai terakhir | Nyala | Mati untuk setiap bawaan pencocokan; menu turun filter / urutan / tampilan / sumber indeks; visibilitas lensa bawaan + batas hasil per lensa.","changelog.434f9ca58ddb":"<strong>Umum → Cari</strong>: setiap sakelar perilaku DSL voidtools-Everything ditambah tambahan Freally (mode strict-Everything, regex otomatis, pelengkapan pengubah, parse-tree saat diarahkan).","changelog.1d3e0b8951a4":"<strong>Umum → Hasil</strong>: setiap perilaku + menu turun prioritas pemuatan + kelompokkan berdasarkan lensa.","changelog.66559820d7a5":"<strong>Umum → Tampilan</strong>: setiap sakelar tampilan (E) + lencana audio/kemiripan Freally + posisi panel pratinjau.","changelog.abfacc1cecb2":"<strong>Umum → Menu Konteks</strong>: Tampilkan / Tampilkan hanya saat Shift ditahan / Sembunyikan per perintah + string makro untuk seluruh 10 entri.","changelog.bcfbad5112f2":"<strong>Umum → Font &amp; Warna</strong>: font + ukuran + warna latar depan/latar belakang per keadaan (dengan <code>&lt;input type=&quot;color&quot;&gt;</code>) + tebal + miring untuk seluruh 8 keadaan item + aksen per lensa + sakelar pewarisan tema.","changelog.e1ece0afb46b":"<strong>Umum → Papan Ketik</strong>: tombol pintas global + tombol pintas per jendela + registri kombinasi tombol (baris Tambah/Hapus untuk pasangan perintah+pengikatan).","changelog.3ae2a3be31d0":"<strong>Riwayat</strong>: sakelar riwayat pencarian/jalankan + jumlah hari retensi + tombol Hapus Sekarang + mode privasi + sakelar riwayat per lensa.","changelog.04aa58c3b95c":"<strong>Indeks (tingkat atas)</strong>: setiap sakelar bidang tingkat indeks dari Everything + tombol Paksa Bangun Ulang / Padatkan / Verifikasi (operasi daemon sungguhan dengan umpan balik toast).","changelog.9c0402a55809":"<strong>Indeks → Volume</strong>: deteksi volume lintas platform dengan lencana sistem berkas (NTFS / ReFS / exFAT / FAT32 / APFS / HFS+ / ext4 / Btrfs / ZFS / XFS / F2FS) + titik status; per volume: Sertakan / Sertakan saja / Aktifkan langganan journal (labelnya berbeda per OS — USN / FSEvents / inotify) / Buffer / Delta alokasi (khusus NTFS) / Muat perubahan terbaru / Pantau perubahan; tombol per OS (Buat ulang journal di NTFS, Reset aliran di APFS, Tingkatkan ke fanotify di Linux); tombol Hapus.","changelog.a85227577e86":"<strong>Indeks → Folder</strong>: Tambah melalui pemilih folder OS + sakelar pemantauan per folder + buffer + jadwal pindai ulang (Pada waktu tertentu / Setiap N jam / Tidak pernah) + tombol Pindai Ulang Sekarang / Pindai Ulang Semua Sekarang.","changelog.7a5ae0347c10":"<strong>Indeks → Daftar Berkas</strong>: Tambah daftar berkas melalui pemilih + menu turun format (teks / JSON / .srcb) + sakelar ekspor otomatis pencarian tersimpan + tombol Editor Daftar Berkas.","changelog.e20f4ec8774d":"<strong>Indeks → Kecualikan</strong>: daftar folder + glob + Terapkan yang direkomendasikan OS (pengecualian konvensional per OS untuk Win / Mac / Linux) + chip Kecualikan berdasarkan kelas (video / audio / gambar / arsip / berkas eksekusi).","changelog.8fd5ecb1f212":"<strong>Lensa → Nama Berkas</strong>: agresivitas trigram + anggaran memori suffix-array + batas perluasan wildcard + batas waktu regex.","changelog.38b4c6105b69":"<strong>Lensa → Konten</strong>: aktifkan + mode per format untuk 11 format + anggaran + panjang cuplikan + bahasa stop-word (18 lokal rilis) + ekstrak ulang saat pengaturan berubah + verifikasi checksum blob.","changelog.299de69339e8":"<strong>Lensa → Audio</strong>: aktifkan + mode per format untuk 10 format + standar referensi LUFS + perhitungan puncak + ambang keheningan + ekstrak ulang saat dimodifikasi.","changelog.9b9db5aea8be":"<strong>Lensa → Kemiripan</strong>: aktifkan + ukuran tanda tangan (64/128/256) + pita (8/16/32) + ambang recall + batas hasil.","changelog.98316029b6fa":"<strong>Lensa → Kustom</strong>: registri pengekstrak komunitas dengan sakelar kepercayaan + tampilan hash blake3 + tampilan izin kotak pasir + Segarkan hash.","changelog.b244fd575e99":"<strong>Jaringan → Server HTTPS</strong>: mulai/hentikan + bind/port/paksa-https/autentikasi-lawas + buat ulang token (merotasi sidik jari secara langsung).","changelog.2b5f33d631fe":"<strong>Jaringan → API ETP/FTP</strong>: mulai/hentikan + port + sakelar FTP/ETP polos lawas.","changelog.acd0f3e9e295":"<strong>Privasi &amp; Pembaruan</strong>: frekuensi pembaruan otomatis + sakelar pra-rilis + kebijakan panggilan jaringan yang di-hardcode dan hanya-baca.","changelog.a7f925aabcc4":"<strong>Log &amp; Debug</strong>: tingkat log (mengubah filter tracing secara langsung) + retensi + buka folder log (melalui <code>tauri-plugin-opener</code>) + ekspor paket diagnostik.","changelog.71e2554230fe":"<strong>Cadangkan, Ekspor, Reset</strong>: Ekspor / Impor pengaturan (round-trip TOML melalui <code>tauri-plugin-fs</code>) + Ekspor / Impor paket markah (.srcb) + Reset semua (dengan konfirmasi).","changelog.af4a3d364535":"<strong>Lokal</strong>: menu turun 18 lokal rilis — <strong>bahasa Inggris disematkan di urutan pertama</strong> lalu urut abjad berdasarkan nama asli (pengelompokan Latin → Sirilik → RTL → aksara lain); setiap label adalah nama bahasa itu dalam bahasanya sendiri sehingga pengguna dapat memilih bahasanya bahkan saat UI berada dalam aksara yang tidak dapat dibacanya; peralihan RTL langsung melalui <code>applyRtlForLocale()</code> (menyetel <code>dir=&quot;rtl&quot;</code> dan <code>lang</code> pada <code>document.documentElement</code> saat lokalnya bahasa Arab atau pratinjau RTL aktif); format tanggal / angka (OS / ISO / RFC / kustom).","changelog.34eea5e6fc14":"<strong>Tentang</strong>: versi + commit + deteksi OS + lisensi + kredit voidtools + pemberitahuan sumber terbuka.","changelog.5db29baba331":"SettingsDialogModel (<code>lib/stores/settings_dialog.svelte.ts</code>) — mesin status perubahan. Melacak tanda perubahan per panel; saat dialog dibuka, mengambil snapshot setiap store; <code>apply()</code> menjalankan <code>flush()</code> setiap store sekaligus; <code>rollback()</code> memulihkan snapshot; <code>resetPanel(id)</code> hanya mengembalikan kunci-kunci milik panel itu. <code>PANEL_KEYS</code> memetakan setiap PanelId ke kunci SettingsState miliknya untuk reset yang presisi.","changelog.7d9367a4db32":"6 store baru yang dialirkan melalui daemon di bawah <code>lib/stores/</code>: <code>volumes / folders / excludes / network / custom_extractors / history</code>. Masing-masing memiliki <code>hydrate()</code> (dipanggil saat dialog dibuka), <code>snapshot()</code> / <code>rollback()</code>, <code>flush()</code>, <code>reset()</code>.","changelog.f76dd7e6a086":"<strong>Biner CLI <code>freally</code></strong> (<code>crates/freally-cli</code>) menjadi klien kedua dari transport <code>freally-rpc</code> yang sama — path socket yang sama, postur autentikasi yang sama. Subperintah: <code>search &quot;&lt;query&gt;&quot;</code> (dengan flag <code>--strict-everything</code> dan <code>--parse-only</code>); <code>index status / verify / compact / rebuild / pause / resume / add-root &lt;path&gt; / rm-root &lt;path&gt;</code>; <code>bookmark save / list / delete</code> (state di sisi UI — menampilkan pesan jelas &quot;dikelola oleh aplikasi yang sedang berjalan&quot; sampai Fase 13 memigrasikan markah ke transport daemon); <code>theme system | light | dark</code>. Subperintah <code>search</code> berlangganan notifikasi terlebih dahulu agar tidak melewatkan event <code>query:batch</code> awal, mencetak hit yang dikelompokkan per lensa saat tiba, dan mencetak waktu lensa akhir saat <code>query:done</code>.","changelog.af56538d34af":"<strong>i18n.</strong> Ke-18 berkas <code>.ftl</code> diperluas dengan kunci dialog pengaturan Fase 12 (~250 kunci per lokal, ~14 KiB per berkas). Bahasa: en / ar / de / es / fr / hi / id / it / ja / ko / nl / pl / pt-BR / ru / tr / uk / vi / zh-CN. Setiap lokal diterjemahkan sepenuhnya ke dalam bahasa aslinya (tidak ada draf terjemahan mesin yang dirilis). Bahasa Arab RTL diuji tata letaknya melalui peralihan langsung <code>applyRtlForLocale()</code> di <code>lib/bootstrap.ts</code> dan sakelar <strong>Lokal → Pratinjau RTL</strong>. Combobox dengan label nama asli memungkinkan pengguna yang terjebak dalam aksara yang tidak dapat dibacanya tetap memilih bahasanya.","changelog.3cd9ef6d9858":"<strong>Smoke test</strong> (<code>tests/smoke/phase_12_*</code> ditambah ekspor ulang per crate di bawah <code>crates/freally-rpc/tests</code>, <code>crates/freally-indexd/tests</code>, <code>crates/freally-extractor-host/tests</code>):","changelog.233c2ff71ae3":"<code>phase_12_rpc_transport.rs</code> — round-trip melalui UDS (Unix) / named pipe (Windows) sungguhan; asersi mode berkas 0600 pada berkas socket; perilaku EOF yang bersih; penolakan frame berukuran berlebih.","changelog.037808959a87":"<code>phase_12_indexd_client.rs</code> — <code>query.run</code> mengalirkan batch dan memancarkan <code>query:done</code>; <code>index.state</code> mengembalikan tampilan bertipe; round-trip <code>extractors.list</code> + <code>extractors.set_mode</code>; round-trip <code>excludes.get</code> / <code>excludes.set</code>; gerbang regresi <code>no_canned_rs_in_tree</code> yang menggagalkan build jika <code>canned.rs</code> muncul kembali.","changelog.c5cfbc1b43d4":"<code>phase_12_settings.rs</code> — round-trip JSON berbasis fixture untuk bentuk <code>SettingsState</code> Fase 12; flatten <code>extras</code> mempertahankan kunci yang tidak dikenal.","changelog.3f571f0f5d1b":"<code>phase_12_custom_extractor.rs</code> — nilai bawaan manifest; round-trip kepercayaan; penghitung crash menonaktifkan pada hitungan ketiga; manifest buruk dilewati; inisialisasi engine host.","changelog.3dbbc40cea55":"<code>phase_12_theme_switch.rs</code> — round-trip JSON pilihan tema melalui <code>settings.apply</code>.","changelog.972927dbd83f":"<code>phase_12_preview_hosts.rs</code> — klasifikasi cadangan text-head universal + tabel warna SVG ikon bertipe.","changelog.a578a3241000":"<code>phase_12_volumes.{ps1,sh}</code> — shell per OS yang menjalankan <code>cargo test -p freally-indexd --test phase_12_indexd_client</code> (invarian deteksi volume ada di unit test crate indexd; smoke shell adalah gerbang lintas OS).","changelog.c7b0c19f8b54":"<strong>Penyimpangan dari Build-Guide</strong> (satu): prompt meminta host pratinjau native OS (QuickLook / Shell / Sushi+KIO) <em>tersambung sepenuhnya</em> di Fase 12. Struktur modul lintas platform + cadangan universal dirilis di fase ini; integrasi COM/objc2/DBus per OS hadir sebagai peningkatan kenyamanan tanpa mengubah kontrak data-URL maupun permukaan perintah Tauri. Permukaan modul <code>preview</code> sudah tersedia sehingga penggantiannya bersifat lokal.","changelog.409ff5baabf9":"<strong>[semua platform]</strong> UI pencarian Fase 11 — momen ajaib (<code>apps/freally-ui</code>). Aplikasi desktop Tauri 2 + Svelte 5 + TypeScript + Tailwind CSS di atas backend IPC <em>tiruan</em> di <code>src-tauri/src/commands/</code>. Satu-satunya perintah yang berbicara dengan backend sungguhan adalah <code>query_parse</code>, yang langsung dialirkan ke <code>freally-query::parse_to_report</code> sehingga tokenisasi langsung di bilah pencarian persis sama dengan parser produksi. Fase 12 (TASK-086a/b/c) mengganti lapisan tiruan dengan transport RPC <code>freally-indexd</code> sungguhan tanpa mengubah kontrak tipe TS di <code>lib/ipc/types.ts</code>.","changelog.8c8596283703":"<strong>Permukaan UI (PRD §8.28 + §8.29 + §9):</strong> SearchBar dengan tokenisasi langsung melalui IPC <code>query.parse</code> + render span lapisan cermin yang diwarnai menurut jenis token + pil galat parse inline yang tertambat pada span galat pertama (Esc membersihkannya); hasil yang dikelompokkan per lensa (Nama Berkas / Konten / Audio / Kemiripan) dengan bagian yang dapat diciutkan, lencana waktu per lensa, sakelar visibilitas lensa melalui <code>View → Lenses</code>; hasil multi-kolom (nama | path | ukuran | diubah | tipe | ekst) dengan ubah ukuran lewat seret pointer-capture pada pegangan kolom, klik untuk mengalihkan urutan (siklus menaik / menurun), profil kolom tersimpan yang dipersistenkan melalui <code>settings.column_profiles[active]</code>, sakelar kepadatan baris padat (32 px) / nyaman (44 px); interaksi baris (Enter membuka / Ctrl+Enter menampilkan di folder / Shift+Enter menyalin path / Ctrl+C menyalin nama / Del konfirmasi+hapus; Ctrl+klik mengalihkan pilihan); panel pratinjau yang terikat ke <code>file_id</code> pertama yang dipilih (merender text head dari IPC <code>files_preview</code>, mendukung data-URL gambar, menampilkan &quot;Unsupported&quot; untuk berkas biner — host pratinjau native OS tersambung di Fase 12); kolom gambar mini (<code>ThumbnailCell</code> memanggil IPC <code>files_thumbnail</code> dengan kotak SVG berwarna tiruan per ekstensi); BookmarksDropdown di bilah menu diisi dari <code>bookmarks_list</code> (persistensi berbasis JSON sungguhan di bawah direktori app-data OS) + OrganizeBookmarksDialog dengan ganti nama + hapus (Ctrl+D menambahkan, Ctrl+Shift+B membuka Atur Markah); QuickFiltersPalette dengan 7 chip (audio / video / gambar / dokumen / berkas eksekusi / arsip / folder) yang mengalihkan token yang sesuai; tombol pintas global melalui <code>tauri-plugin-global-shortcut</code> (bawaan Alt+Space di macOS, Super+Space di Win/Linux) — saat dipicu, membawa jendela ke depan + memfokuskan input pencarian; protokol URL <code>freally://search?q=…</code> melalui <code>tauri-plugin-deep-link</code>; wisaya jalankan pertama (4 langkah: root / tombol pintas / lokal / tema) yang dijaga oleh <code>settings.first_run_complete</code>; sistem tema (PRD §9) dengan tiga status <code>system</code> / <code>light</code> / <code>dark</code> melalui atribut <code>&lt;html data-theme&gt;</code>, token menggerakkan setiap warna melalui CSS custom property (<code>tokens.{dark,light,shared}.css</code>), cross-fade 100 ms yang menghormati <code>prefers-reduced-motion</code>, listener <code>prefers-color-scheme</code> berganti langsung saat dalam mode <code>system</code>, konfigurasi Tailwind memetakan utilitas ke <code>var(--…)</code>.","changelog.ab4ea4f7502a":"<strong>Bilah menu utama (PRD §8.28)</strong> — menu lengkap setara Everything di Berkas / Edit / Tampilan / Cari / Markah / Alat / Bantuan, dengan semua submenu + sub-item + akselerator papan ketik + tambahan Freally (submenu Tampilan → Tema, submenu Tampilan → Lensa, Alat → Pemeliharaan indeks ▶ Verifikasi / Padatkan / Paksa Bangun Ulang, Alat → Pengelola Pengekstrak Kustom, Bantuan → Referensi Pengubah Audio / Kemiripan, Bantuan → Sponsori / Donasi). Penempatan per OS: macOS memakai <code>tauri::menu::MenuBuilder</code> untuk bilah menu global (dengan menu aplikasi <code>Freally →</code> yang diwajibkan macOS berisi Tentang / Preferensi / Keluar); Win/Linux merender <code>MenuBar.svelte</code> di dalam jendela yang mengonsumsi spesifikasi deklaratif yang sama melalui set CommandId yang sama. Event klik dari menu native macOS memancarkan <code>menu-command</code>; <code>bootstrap.ts</code> milik UI mendengarkannya dan mendispatch melalui registri perintah dalam proses — satu sumber kebenaran untuk kedua jalur render. Event hover memancarkan <code>MenuHoverEvent</code> → segmen petunjuk di bilah status. Petunjuk hover sama persis dengan string Everything (&quot;Berisi perintah untuk bekerja dengan Freally.&quot;, &quot;Berisi perintah untuk mengurutkan daftar hasil.&quot;, dll.) ditambah tambahan Freally (&quot;Beralih antara tema sistem, terang, atau gelap.&quot;, &quot;Alihkan visibilitas setiap lensa di daftar hasil.&quot;, &quot;Kelola pengekstrak kustom dengan kotak pasir Wasm.&quot;, &quot;Alat pemeliharaan indeks.&quot;).","changelog.d29275561d2e":"<strong>Bilah status (PRD §8.29)</strong> — dapat dialihkan melalui <code>View → Status Bar</code>. Tujuh segmen bawaan dari kiri → kanan: titik pengindeksan (Terindeks / Mengindeks N/M / Dijeda / Galat) yang menampilkan tombol pintas saat diarahkan, jumlah hasil + jumlah pilihan, ukuran pilihan (bergantung pada <code>show_size_in_status_bar</code>), waktu kueri aktif, latensi per lensa (bergantung pada <code>show_timing_badges</code>), indikator endpoint (DB Lokal / API: \\&lt;name\\&gt;), area petunjuk hover yang berlangganan store hover menu dengan teks diam <code>Ready · {indexed} indexed</code>. Tambahan khusus Freally: titik tema paling kanan (ikon matahari / bulan, klik tunggal berputar di antara 3 keadaan); tombol pintas yang ditampilkan saat mengarahkan ke titik pengindeksan adalah salah satu dari dua tambahan (+) PRD §8.29.","changelog.5bcf148b5b86":"<strong>Registri perintah + pintasan papan ketik:</strong> <code>lib/commands/ids.ts</code> membawa union string <code>CommandId</code> yang lengkap saat kompilasi dan mencakup ~95 item menu; <code>isCommandId</code> adalah pemeriksaan himpunan tertutup yang dipakai <code>bootstrap.ts</code> untuk memvalidasi payload event <code>menu-command</code> dari menu native macOS (menolak payload yang cacat). <code>lib/commands/registry.ts</code> mendispatch melalui <code>Map&lt;CommandId, CommandHandler&gt;</code> — setiap CommandId memiliki handler terdaftar saat startup; jalur bootstrap memancarkan <code>console.warn</code> jika ada yang hilang. <code>lib/commands/menu_spec.ts</code> (TS) + <code>src-tauri/src/menu_spec.rs</code> (Rust) — pohon menu deklaratif yang dikonsumsi kedua renderer, dijaga tetap selaras oleh tes kesetaraan <code>tests/menubar_parity.rs::rust_spec_covers_every_command_id</code> + <code>does_not_introduce_unknown_command_ids</code> (langkah codegen saat build akan memberi imbal hasil negatif dibanding cakupannya; tes kesetaraan menjadi gerbang regresinya). <code>lib/commands/shortcuts.ts</code> sadar OS — <code>mod</code> di-resolve menjadi ⌘ di macOS, Ctrl di Win/Linux saat runtime melalui <code>isMac()</code>. Handler sungguhan yang tersambung di fase ini: zoom (font-size root), ukuran jendela (Tauri <code>WebviewWindow::setSize</code>), urutan (bidang <code>sortStore</code> + state urutan), di atas (<code>set_always_on_top</code>), gambar mini/detail (row_density), tema (round-trip tema + pengaturan), visibilitas lensa, segarkan (menjalankan ulang kueri), sakelar pratinjau/bilah status, file.close / file.exit (menutup jendela), tools.options (dialog placeholder pengaturan), tools.verify/compact/rebuild_index (IPC sungguhan), help.\\* (membuka URL melalui plugin opener), help.about (dialog Tentang), bookmarks.add/organize (store + dialog), ID perintah filter cepat (menambahkan token di depan + menjalankan ulang), edit.cut/copy/paste/select_all/invert_selection, edit.advanced.copy_full_name/path/filename/as_json/with_metadata/as_bundle_ref. Handler placeholder yang tersisa (file.new_window / file.open_file_list / file.export_results / view.go_to / search.advanced / search.add_to_filters / search.organize_filters / sakelar pencocokan pencarian / tools.file_list_editor / edit.copy_to_folder/move_to_folder) secara eksplisit ditandai <code>Phase 12</code> di kode — semuanya menunggu IPC daemon sungguhan atau dialog Pengaturan lengkap, keduanya dalam cakupan Fase 12.","changelog.a2506592845e":"<strong>Backend IPC tiruan di Rust</strong> (<code>apps/freally-ui/src-tauri/src/commands/</code>): <code>query.rs</code> mengalirkan <code>query_parse</code> melalui <code>freally-query::parse_to_report</code> sungguhan (permukaan Fase 10, sungguhan); <code>query_run</code> / <code>query_cancel</code> / <code>query_lens_timings</code> / <code>query_fetch_batches</code> menghasilkan batch kalengan yang deterministik di keempat lensa dengan LensTimings sintetis tetapi berbentuk realistis (8 ms nama berkas / 22 ms konten / 5 ms audio / 11 ms kemiripan / 14 ms total). <code>canned.rs</code> menyintesis 12 / 8 / 4 / 6 hit di keempat lensa per kueri (deterministik sehingga smoke test dapat dikunci terhadap keluarannya; konstanta total terindeks 5 234 123 berkas mengisi teks diam titik pengindeksan). <code>index_state.rs</code> bergerak dari <code>Indexing N/total</code> ke <code>Indexed (total)</code> selama jendela pemanasan 4 detik. <code>bookmarks.rs</code> menyertakan persistensi berbasis JSON sungguhan di bawah <code>app.path().app_data_dir()</code> (root yang telah diperiksa Tauri). <code>extractors.rs</code> membawa registri kalengan berisi tujuh pengekstrak Fase 7–9 dengan <code>ExtractorMode</code> per pengekstrak (segera / malas / dinonaktifkan). <code>settings.rs</code> berbasis JSON dengan round-trip deep-merge <code>settings_set(patch)</code> melalui <code>serde_json::to_value</code> + deserialisasi ulang bertipe; <code>settings_reset</code> memulihkan nilai bawaan; skemanya mencakup tema / lokal / sakelar bilah status / sakelar lencana waktu / pratinjau / kepadatan baris / profil kolom / visibilitas lensa / tombol pintas / endpoint / flag jalankan pertama / mode privasi. <code>files.rs</code> memakai <code>tauri-plugin-opener</code> untuk handler buka/tampilkan OS sungguhan, <code>tauri-plugin-clipboard-manager</code> untuk copy_path / copy_name, <code>std::fs::remove_file</code> untuk hapus (setelah konfirmasi UI), data-URL SVG berwarna untuk gambar mini (tiruan), dan text head atau <code>Unsupported</code> untuk pratinjau (tiruan).","changelog.7d2b902ad7ff":"<strong>Integrasi native:</strong> <code>native_menu.rs</code> secara rekursif membangun <code>tauri::menu::Menu</code> dari <code>menu_spec.rs</code> dan di macOS menetapkannya sebagai menu aplikasi melalui <code>app.set_menu(...)</code> (menu aplikasi <code>Freally →</code> yang diwajibkan macOS berisi Tentang / Preferensi / Keluar dengan akselerator HIG yang tepat). <code>hotkey.rs</code> mendaftarkan kombinasi bawaan (Alt+Space di macOS, Super+Space di Win/Linux) melalui <code>tauri-plugin-global-shortcut</code>; saat dipicu, ia menampilkan + memfokuskan jendela utama dan memancarkan <code>hotkey:fired</code> agar UI memfokuskan input pencarian; konflik ditampilkan sebagai log <code>warn</code> (pengguna dapat mengganti kombinasinya di pengaturan Fase 12). <code>url_protocol.rs</code> mendaftarkan skema <code>freally://</code> melalui <code>tauri-plugin-deep-link</code> dan memancarkan <code>url:opened</code> untuk URL yang masuk; listener UI mem-parse-nya dengan <code>new URL(...)</code> dan hanya bertindak atas bentuk <code>?q=</code>.","changelog.dfae438bb9e9":"<strong>i18n</strong> (Aturan Tetap #4): bundle en inline (Fase 12 menyambungkan loader Fluent penuh terhadap <code>locales/&lt;code&gt;/freally.ftl</code> untuk ke-18 lokal). Ke-18 berkas <code>.ftl</code> diperluas dengan kunci Fase 11 (grup status / menu / tema / lensa / galat parse / tindakan / filter cepat / wisaya) — draf terjemahan mesin menunggu tinjauan manusia sebelum v0.19.84. <code>xtask i18n-lint</code> tetap hijau pada jumlah kunci baru × 17 lokal non-sumber.","changelog.d61b34326782":"<strong>Tes + validasi:</strong> <code>tests/smoke/phase_11_ui_e2e.rs</code> (7 kasus — diekspor ulang di bawah <code>crates/freally-query/tests/phase_11_ui_e2e.rs</code>) mencakup invarian aliran token <code>parse_to_report</code> yang menjadi andalan <code>highlight.ts</code> milik bilah pencarian, pemunculan galat mode strict-everything untuk pil galat parse, stabilitas round-trip JSON <code>LensId</code> + <code>IndexPhase</code> IPC untuk penggantian di Fase 12, dan <strong>gerbang kinerja momen ajaib</strong> (TASK-085): <code>parse_to_report</code> rata-rata jauh di bawah 4 ms / iterasi pada kueri 1 karakter dan pada kueri realistis 32 karakter — jalur kritis ketukan tombol tetap dalam anggaran 16 ms yang disebut Build Guide. <code>apps/freally-ui/src-tauri/tests/menubar_parity.rs</code> (4 kasus) — setiap CommandId PRD §8.28 ada di spesifikasi Rust; tanpa tambahan; 7 root tingkat atas dalam urutan yang benar; tanpa ID duplikat. <code>apps/freally-ui/src-tauri/tests/menubar_wiring.rs</code> (3 kasus) — setiap ID item menu berbentuk benar (bentuk <code>namespace.action</code>); setiap string akselerator ter-parse dengan bersih; Tentang / Preferensi / Keluar di menu aplikasi macOS menargetkan CommandId sungguhan. <code>apps/freally-ui/src-tauri/tests/statusbar_parity.rs</code> (2 kasus) — 7 segmen bawaan + 2 tambahan (+) Freally dikunci. <code>apps/freally-ui/tests/unit/*.test.ts</code> (kerangka vitest, ~25 kasus) — formatter, himpunan tertutup command-id + keselarasan dengan <code>MENU_BAR</code>, pembentukan segmen <code>highlight()</code> tokenizer + overlay galat + <code>firstError</code>, keunikan <code>BINDINGS</code> + <code>shortcutMatches</code> + <code>formatShortcut</code>, alih <code>sortStore</code> / lompatan ke bidang berbeda / kemiripan berdasarkan skor, siklus store tema + mutasi atribut DOM. <code>tests/smoke/phase_11_ui_e2e.{sh,ps1}</code> menjalankan <code>cargo test</code> untuk tes routing + <code>cargo check</code> untuk crate src-tauri + (jika <code>pnpm</code> tersedia) <code>pnpm install + check + build</code>. <strong>Gerbang validasi</strong>: <code>cargo fmt --all -- --check</code>, <code>cargo clippy --workspace --all-targets -- -D warnings</code>, <code>cargo test --workspace</code> semuanya hijau; cargo check + clippy <code>apps/freally-ui/src-tauri</code> bersih tanpa peringatan; 9 tes src-tauri + 7 smoke test lulus. <code>/review</code> + <code>/security-review</code> bersih (Aturan Tetap #9).","changelog.03bf40d97b72":"Kerangka <strong>Storybook</strong> + 3 story awal (LensTimingBadge, QuickFiltersPalette, SearchBar) di bawah <code>apps/freally-ui/src/stories/</code>, dengan <code>.storybook/main.ts</code> + <code>preview.ts</code> yang membawa pengalih toolbar tema gelap / terang sesuai mandat regresi visual PRD §9.","changelog.5df93276a274":"<strong>Serah terima Fase 11 → Fase 12</strong> (ditunda ke TASK-086a/b/c, didokumentasikan di Build-Prompts-Guide + ROADMAP): mengganti <code>commands/canned.rs</code> + <code>IndexStateMock</code> tiruan dengan transport JSON-RPC berawalan panjang <code>freally-rpc</code> sungguhan melalui Unix socket / named pipe per pengguna (mode berkas 0600 + pemeriksaan uid saat accept di Unix; DACL pipe dibatasi ke SID pengguna saat ini di Windows); mengalirkan <code>query_run</code> melalui <code>freally-query::execute_with_audio</code> sungguhan atas <code>freally-index</code> yang hidup, mengalirkan batch melalui <code>Window::emit(&quot;query:batch&quot;, ...)</code> agar gerbang 16 ms milik UI tetap jujur pada 5M berkas; host pratinjau native OS (QuickLook melalui <code>objc2</code> di macOS / handler pratinjau Shell melalui <code>windows-rs</code> di Windows / pratinjau GNOME Sushi DBus + KDE KIO di Linux) menggantikan <code>files_preview</code> / <code>files_thumbnail</code> tiruan. Kontrak TS di <code>lib/ipc/types.ts</code> tetap stabil selama penggantian.","changelog.1cfd9c0b8865":"<strong>Penyimpangan dari Build-Guide</strong> (tiga, semuanya dicatat di kode + entri ini): (1) <strong>Plugin shell Tauri</strong> — Build Guide menyiratkan <code>tauri-plugin-shell::open()</code> untuk <code>files_open</code> / <code>files_reveal</code>; API itu sudah usang dan digantikan <code>tauri-plugin-opener::open_path</code>. Kami memakai plugin baru untuk menghindari peringatan usang pada setiap build. (2) <strong>Menu native di Win/Linux</strong> — Build Guide menyebut &quot;di dalam jendela pada Win/Linux, bilah menu global pada macOS&quot;; Fase 11 merilis menu di dalam jendela pada Win/Linux + menu native macOS. Integrasi DBus AppMenu di Linux (jika tersedia) ditunda ke Fase 12. (3) <strong>Host pratinjau native OS</strong> — Fase 11 dirilis dengan penyedia konten tiruan untuk panel pratinjau (text-head + gambar mini SVG berwarna); integrasi QuickLook / Shell / Sushi / KIO dipindahkan ke Fase 12 (TASK-086c) karena berbagi cakupan IPC daemon sungguhan. TASK-075 / TASK-076 dalam prompt Fase 11 membawa catatan ROADMAP inline tentang penundaan ini.","changelog.2e4654ecd39f":"<strong>[semua platform]</strong> Bahasa kueri Fase 10 + pengerasan parser (<code>freally-query</code>) — parser buatan tangan dari Fase 5 mempertahankan permukaan 1:1 voidtools-Everything (kontrak Aturan Tetap #8) dan mendapat empat bagian baru: (1) <strong><code>ParseOpts { strict_everything: bool }</code></strong> + <code>pub fn parse_with(s, opts) -&gt; Result&lt;Query, ParseError&gt;</code> (<code>parse(s)</code> dari Fase 5 kini adalah <code>parse_with(s, ParseOpts::default())</code>). Mode strict-everything menolak setiap pengubah khusus Freally — <code>similar:</code>, keenam pengubah audio (<code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code>) ditambah alias <code>duration:</code> / <code>samplerate:</code>, serta prefiks lensa <code>audio:(...)</code> / <code>content:(...)</code> / <code>similar:(...)</code> — dengan memunculkan <code>ParseError::StrictEverythingViolation { pos, token, reason }</code> bertipe yang baru sehingga bilah pencarian Fase 11 dapat menyorot pengubah mana yang tidak akan berlaku bagi pengguna voidtools murni. Permukaan berbentuk voidtools (size, date, ext, attrib, path/parent/child + alias name/folder, filter cepat, regex, wildcard, perekat boolean, tanda kurung, kata kunci cadangan demi kebiasaan pengguna <code>wfn:</code> / <code>case:</code> / <code>count:</code> / <code>dupe:</code> / <code>nodiacritics:</code> / <code>type:</code> / <code>lang:</code>) tetap di-parse dalam mode ketat. (2) <strong>Sintaks prefiks lensa</strong> <code>&lt;key&gt;:(...)</code> untuk <code>name:</code> / <code>audio:</code> / <code>content:</code> / <code>similar:</code>. Varian AST baru <code>QueryNode::Lens { kind: LensKind, inner: Box&lt;QueryNode&gt; }</code> (dengan <code>pub enum LensKind { Name, Audio, Content, Similar }</code>) membungkus sub-kueri di dalamnya sehingga UI hasil yang dikelompokkan per lensa di Fase 11 dapat merender bagian per lensa. Parser hanya memanggil jalur prefiks lensa saat token tepat berupa <code>&lt;key&gt;:</code> <em>dan</em> token berikutnya adalah <code>(</code> — <code>audio:</code> polos tetap menjadi filter cepat; <code>similar:foo</code> tetap menjadi pengubah <code>Similar</code> yang sudah ada; <code>name:foo</code> tetap menjadi alias <code>child:</code>. Cakupan lensa kosong (<code>audio:()</code>) runtuh menjadi <code>True</code>. Saat ini eksekutor memperlakukan cakupan lensa <code>Name</code> / <code>Audio</code> / <code>Similar</code> sebagai pembungkus transparan (pengubah di dalamnya tetap menggerakkan routing); cakupan lensa <code>Content</code> memunculkan <code>QueryError::UnsupportedModifier(&quot;content&quot;)</code> sampai Fase 11+ menyambungkan pengekstrak konten Fase 8 ke eksekutor. (3) <strong>Pass optimizer</strong> di <code>crates/freally-query/src/optimizer.rs</code> yang baru: <code>pub fn optimize(q: &amp;Query) -&gt; Query</code> mengurutkan ulang anak-anak <code>And</code> berdasarkan <code>selectivity_rank</code> (yang termurah lebih dulu → short-circuit memanfaatkannya), merekursi ke <code>Or</code> / <code>Not</code> / <code>Lens</code> (urutan Or dipertahankan — urutan penting untuk urutan hit yang stabil); fungsi peringkat dikalibrasi terhadap biaya per predikat eksekutor Fase 5/6/9 (literal/quick-filter/child = 10-12, ext = 13, size/date/attrib = 20-24, path/parent = 30, wildcard = 40, regex = 50, audio = 80, similar = 85, reserved = 90). Helper routing lensa <code>is_audio_only_route(node)</code> dan <code>is_similarity_route(node)</code> memungkinkan eksekutor melewati pra-filter trigram nama berkas untuk kueri khusus audio (setiap baris hidup adalah kandidat, sehingga <code>for_each_live</code> berjalan tanpa panggilan <code>evaluator.matches</code> per baris). Optimizer dipasang ke <code>execute_with_audio</code> (di depan pipeline) dan <code>PlanCache::get_or_plan</code> (bentuk yang di-cache adalah bentuk yang dioptimalkan) sehingga setiap eksekusi nyata mendapat manfaat tanpa mengubah bentuk AST dari <code>parse()</code> yang terlihat pengguna. (4) <strong><code>pub fn parse_to_report(s: &amp;str, opts: ParseOpts) -&gt; ParseReport</code></strong> — titik masuk IPC <code>query.parse</code> di <code>crates/freally-query/src/report.rs</code> yang baru. <code>ParseReport { source, strict_everything, ast: Option&lt;AstNode&gt;, tokens: Vec&lt;TokenInfo&gt;, errors: Vec&lt;ErrorInfo&gt; }</code> sepenuhnya serde-Serialize, siap untuk perintah Tauri atau POST <code>freally-http</code> <code>/v1/query.parse</code> di masa depan. <code>TokenInfo { kind, span: TokenSpan { start, end }, text }</code> membawa span per token + tipe semantik <code>TokenKind</code> (<code>Literal</code> / <code>Quoted</code> / <code>Wildcard</code> / <code>Regex</code> / <code>Modifier{name}</code> / <code>QuickFilter{name}</code> / <code>LensPrefix{lens}</code> / <code>LParen</code> / <code>RParen</code> / <code>Bang</code> / <code>And</code> / <code>Or</code> / <code>Not</code>) sehingga bilah pencarian dapat menyorot token saat pengguna mengetik. <code>ErrorInfo { span, message, code: ErrorCode }</code> memproyeksikan setiap varian <code>ParseError</code> ke span + pesan yang ramah UI + <code>ErrorCode</code> yang dapat dibaca mesin (<code>Empty</code> / <code>UnexpectedEof</code> / <code>UnexpectedToken</code> / <code>UnbalancedParens</code> / <code>InvalidRegex</code> / <code>InvalidWildcard</code> / <code>UnknownModifier</code> / <code>InvalidModifierValue</code> / <code>StrictEverythingViolation</code>). <code>AstNode</code> yang dapat diserialisasi mencerminkan <code>QueryNode</code> tanpa payload <code>Arc&lt;Regex&gt;</code> (sumber regex disimpan sebagai string — konsumen IPC mengompilasinya di sisinya sendiri); <code>ModifierDetail</code> membawa kumpulan bidang terkecil yang dibutuhkan UI per pengubah (size: <code>{op, bytes}</code>, date: <code>{op, epoch_day}</code> atau <code>{name}</code>, ext: <code>{extensions}</code>, attrib: <code>{letters}</code>, path/parent/child/similar: <code>{needle}</code>, varian audio: <code>{op, value}</code>, reserved: <code>{value}</code>). <code>parse_to_report</code> tidak pernah mengembalikan <code>Err</code> — bahkan sumber kosong menghasilkan laporan lengkap; di bawah <code>--strict-everything</code> ia memindai aliran token terlebih dahulu dan memunculkan <em>semua</em> pelanggaran pengubah / prefiks lensa khusus Freally dalam satu lintasan (alih-alih perilaku temukan-pertama-lalu-berhenti milik <code>parse_with</code>). Jalur panas (pembukuan parser + <code>tokenize</code>) tetap tidak berubah — tipe-tipe baru diturunkan darinya. Internal parser baru: <code>Token</code> mendapat bidang <code>byte_len: usize</code> sehingga lapisan laporan dapat menyintesis span per token tanpa tokenisasi ulang. Dependensi runtime baru <code>serde = workspace</code> untuk tipe-tipe baru (sudah menjadi dependensi workspace lewat cache audio Fase 9). Tes baru: 67 unit test di <code>freally-query</code> (parser + cache + optimizer + report), 17 kasus smoke Fase 10 di bawah <code>tests/smoke/phase_10_query.rs</code> (diekspor ulang sebagai <code>crates/freally-query/tests/phase_10_query.rs</code>), 21 tes fixture DSL Freally di <code>crates/freally-query/tests/freally_dsl.rs</code> (≥200 kueri yang dihasilkan), 3 tes kompatibilitas voidtools termasuk <code>three_hundred_voidtools_queries_parse</code> yang baru (total ≥300, 120+ dikurasi tangan + generator algoritmik). Gerbang regresi Aturan Tetap #8 adalah fixture 50 kueri di dalam himpunan 300+ yang lebih besar.","changelog.07f1d2595011":"<strong>Penyimpangan dari Build-Guide.</strong> Prompt Fase 10 berbunyi &quot;Ganti parser ad-hoc Fase 5 dengan tata bahasa chumsky (atau pest).&quot; Kami memilih untuk <strong>mengeraskan parser recursive-descent yang sudah ada</strong> alih-alih menulis ulang, karena permukaan Fase 5 adalah kontrak 1:1 voidtools-Everything (Aturan Tetap #8) dengan banyak kasus pojok — <code>(a)!b</code> di-parse sebagai <code>(a) AND !b</code>; <code>regex:</code> hanya mengonsumsi hingga tanda kurung / spasi berikutnya; <code>attrib:HRA</code> adalah <em>himpunan</em> flag, bukan string; disambiguasi filter cepat / prefiks lensa <code>audio:</code> bergantung pada kelas token berikutnya. Mengodekan ulang setiap keanehan di API kombinator chumsky 0.10 atau di tata bahasa PEG <code>query.pest</code> tanpa meregresi fixture 50 kueri berisiko tinggi dan berimbal kecil. Parser buatan tangan yang dikeraskan mencapai setiap tujuan Fase 10 — pelacakan span per token melalui <code>Token::byte_len</code>, galat per token melalui <code>ParseReport::errors</code>, mode strict-everything, prefiks lensa, optimizer — tanpa risiko apa pun terhadap kontrak Aturan Tetap #8. Pertumbuhan fixture voidtools menjadi 300+ adalah <em>gerbang regresi</em>, bukan target porting. Pass kinerja Fase 13 mengevaluasi apakah porting ke chumsky sepadan begitu angka benchmark tersedia.","changelog.c2c6adddd634":"<strong>[semua platform]</strong> Pengekstrak audio Fase 9 (<code>freally-audio</code>) — decoder berbasis symphonia + pengukuran kenyaringan EBU R128 (melalui crate pure-Rust <code>ebur128 = &quot;0.1&quot;</code>) + rasio keheningan + rentang dinamis, ditambah pengubah <code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code> di DSL kueri. Permukaan publik: <code>pub fn analyze_file(path: &amp;Path) -&gt; Result&lt;AudioAttributes, AudioError&gt;</code> ditambah <code>analyze_with_opts(path, AnalysisOpts)</code> untuk jalur pembatalan kooperatif + anggaran waktu; <code>pub trait AudioAttributesProvider</code> (abstraksi berbentuk cache yang diajak bicara oleh eksekutor); <code>pub struct AudioCache</code> (cache JSON di memori + di disk dengan invalidasi berbasis mtime, ekstraksi single-flight melalui <code>Condvar</code>, dan anggaran waktu per ekstraksi dengan bawaan <code>DEFAULT_AUDIO_TIME_BUDGET = 5 s</code> sehingga berkas audio jahat tidak dapat berputar tanpa akhir). <code>AudioAttributes</code> membawa <code>codec</code> (short-id symphonia dalam huruf kecil — <code>flac</code> / <code>mp3</code> / <code>aac</code> / <code>vorbis</code> / <code>pcm_s16</code> / <code>alac</code> / …), <code>sample_rate</code>, <code>channels</code>, <code>bit_depth</code>, <code>duration_ns</code>, <code>lufs_integrated</code>, <code>lufs_short_term_p99</code>, <code>lufs_short_term_p10</code>, <code>peak_dbfs</code> (true peak melalui oversampler polyphase 4× milik crate ebur128 — spesifikasi Build-Guide terpenuhi tanpa FIR buatan tangan), <code>silence_ratio</code> (% sampel di bawah <code>−60 dBFS</code>; penghitungan per sampel sehingga perhitungannya tidak bergantung pada jumlah kanal — lihat regresi <code>mono_and_correlated_stereo_report_same_ratio</code>), dan <code>dynamic_range_lu</code> (<code>short_term_p99 − short_term_p10</code>; runtuh menjadi <code>0</code> untuk klip di bawah 3 detik yang jendela geser short-term-nya tidak pernah terisi, dengan persentil yang dimunculkan sebagai <code>f32::NEG_INFINITY</code> sehingga kueri <code>lufs:&gt;x</code> tidak pernah cocok secara keliru). Bidang LUFS / peak melakukan round-trip nilai tak hingga (<code>±∞</code> / <code>NaN</code>) melalui helper JSON kustom <code>lufs_serde</code> yang memakai tiga string penanda (<code>&quot;-inf&quot;</code> / <code>&quot;+inf&quot;</code> / <code>&quot;nan&quot;</code>) — perilaku bawaan <code>serde_json</code> yang mengubah nilai tak hingga menjadi <code>null</code> akan diam-diam merusak cache jika tidak; <code>unknown_sentinel_rejects</code> menjaga jalur galat bertipe dari regresi. Jumlah kanal dibatasi keras pada <code>MAX_CHANNELS = 64</code> sehingga header yang cacat tidak dapat memaksa alokasi per tap yang sangat besar sebelum sandbox menangkapnya. Penganalisis memunculkan galat bertipe <code>AudioError::NotAudio</code> / <code>Probe</code> / <code>Decode</code> / <code>Empty</code> / <code>Unsupported</code> / <code>Cancelled</code> / <code>Json</code> / <code>NonUtf8Path</code>. DSL kueri menambahkan parser <code>parse_audio_lufs</code> / <code>_codec</code> / <code>_length</code> / <code>_rate</code> / <code>_silence</code> / <code>_dr</code> yang memakai ulang bentuk <code>split_op</code> dari Fase 5 (<code>&lt;</code> / <code>&lt;=</code> / <code>&gt;</code> / <code>&gt;=</code> / <code>=</code> / polos = <code>==</code>); <code>length:</code> menerima detik, <code>mm:ss</code>, dan <code>hh:mm:ss</code> (dengan penjaga luapan menit sehingga <code>length:1:90</code> ditolak); <code>rate:</code> menerima satuan <code>Hz</code> / <code>kHz</code>; <code>silence:</code> menerima rasio maupun persentase; <code>dr:</code> menolak nilai negatif; <code>duration:</code> menjadi alias <code>length:</code> dan <code>samplerate:</code> menjadi alias <code>rate:</code> demi kebiasaan pengguna voidtools-Everything. Eksekutor menambahkan <code>pub fn execute_with_audio(idx, similarity_opt, audio_opt, q, opts)</code> yang mendeteksi kueri bermuatan audio melalui <code>has_audio_anywhere</code>, mensyaratkan <code>AudioAttributesProvider</code> (jika tidak ada, memunculkan <code>QueryError::AudioProviderUnavailable</code> — galat bertipe alih-alih hasil kosong, sesuai kontrak <code>SimilarityIndexUnavailable</code> Fase 6), dan untuk setiap baris mencari <code>AudioAttributes</code> melalui penyedia sebelum menjalankan <code>eval_audio_predicate</code> terhadap atribut yang di-cache. Komposisi audio dengan lensa kemiripan (<code>similar:bassdrop codec:flac length:&gt;3:00</code>) berfungsi dari ujung ke ujung melalui jalur eksekutor yang sama. Pemeriksaan pembatalan kooperatif dipicu sekali per paket symphonia (<code>Ordering::Acquire</code> pada atomik pembatalan untuk pasangan flip <code>Release</code> dari supervisor); <code>SampleBuffer</code> direset pada <code>SymphoniaError::ResetRequired</code> sehingga paket berikutnya mengalokasikan ulang sesuai <code>capacity()</code> decoder baru (menghindari panic asersi kapasitas <code>copy_interleaved_typed</code>). <code>TimeBudgetSupervisor</code> adalah thread terlepas yang membalik flag pembatalan begitu anggaran habis dan membersihkan dirinya sendiri melalui flag <code>done</code> yang dibalik di <code>Drop</code> milik supervisor. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>symphonia = &quot;0.5&quot;</code> (MPL-2.0; decoder audio pure-Rust; fitur yang diaktifkan: aac, alac, flac, isomp4, mp3, ogg, pcm, vorbis, wav, aiff, opt-simd — Opus sengaja dinonaktifkan karena vektor tes upstream-nya membawa data bernuansa GPL yang dilarang kebijakan deny; kami akan meninjaunya kembali saat crate Opus khusus MIT tersedia), <code>ebur128 = &quot;0.1&quot;</code> (MIT/Apache-2.0; port pure-Rust dari libebur128), ditambah dependensi workspace yang sudah ada (<code>serde_json</code>, <code>parking_lot</code>, <code>tracing</code>, <code>thiserror</code>, <code>tempfile</code> untuk tes). Smoke test <code>tests/smoke/phase_09_audio.rs</code> (10 kasus — diekspor ulang di bawah <code>crates/freally-query/tests/phase_09_audio.rs</code>) mencakup round-trip penganalisis pada fixture WAV sintetis (sinus 1 kHz pada −23 dBFS terbaca ≈ −23 LUFS dalam ±1 LU; keheningan murni terbaca <code>silence_ratio &gt; 0.99</code> dan LUFS terintegrasi = <code>f32::NEG_INFINITY</code>), round-trip disk cache audio + invalidasi mtime, parsing keenam pengubah audio, contoh gabungan <code>lufs:&lt;-14 codec:flac length:&gt;3:00</code> dari prompt Build-Guide, gerbang <code>AudioProviderUnavailable</code> bertipe, pemfilteran <code>execute_with_audio</code> dari ujung ke ujung terhadap <code>Index</code> di memori yang diisi berkas audio sintetis (sinus keras + pelan memverifikasi kedua arah <code>lufs:&gt;-20</code> / <code>lufs:&lt;-20</code>), pencocokan epsilon <code>silence:=</code> terhadap audio keheningan murni, fall-through <code>NullProvider</code> (pengubah audio tidak mencocokkan apa pun alih-alih panic), dan jalur pembatalan flag-batal / supervisor anggaran waktu. Fase 9 tidak memperkenalkan string UI baru — pengubahnya berbentuk perintah (seperti <code>size:</code> / <code>ext:</code>); <code>xtask i18n-lint</code> tetap hijau pada 5 kunci × 17 lokal non-sumber.","changelog.138d44119faa":"<strong>Penyimpangan dari Build-Guide.</strong> Dua catatan inline tentang dependensi yang tidak persis sesuai Build Guide:","changelog.c49ebee11cd1":"<strong>Decoder audio</strong>: Build Guide menyebut &quot;symphonia&quot; — dipakai sesuai yang tertulis. Build Guide juga menyebut &quot;ebur128 (libebur128)&quot;; kami memakai crate pure-Rust <code>ebur128 = &quot;0.1&quot;</code> (port oleh Sebastian Dröge) alih-alih pustaka C agar workspace tetap pure-Rust dan menghindari langkah pemasangan pustaka sistem di CI tiga OS.","changelog.fb9344590719":"<strong>Dukungan Opus</strong>: Build Guide mencantumkan Opus di antara format yang didukung. Kami menghilangkannya untuk v0.19.84 karena fitur <code>opus</code> milik symphonia menarik vektor tes bernuansa GPL yang bertentangan dengan larangan AGPL/GPL milik <code>cargo-deny</code>. Kontainer OGG berisi Opus dimunculkan sebagai kegagalan <code>Probe</code>/<code>Decode</code> alih-alih kecocokan yang menyesatkan; kami akan meninjaunya kembali saat decoder Opus khusus MIT dirilis. Dua catatan lagi: <strong>Suite kesesuaian EBU R128</strong>: prompt Fase 9 menyebut &quot;klip referensi dengan LUFS yang diketahui (suite kesesuaian EBU R128), toleransi ±0.1 LU&quot; sebagai gerbangnya. Smoke test menyertakan harness sinus sintetis pada ±1 LU (sinus 1 kHz pada −23 dBFS terbaca ≈ −23 LUFS setelah K-weighting); klip EBU yang dipublikasikan tidak disematkan karena workspace berupaya tidak menyimpan fixture biner sama sekali di dalam tree. Pass kinerja Fase 13 menambahkan suite kesesuaian ke matriks CI begitu kebijakan fixture biner diputuskan. <strong>Penyambungan sandbox</strong>: penganalisis audio <em>tidak</em> dijalankan di dalam <code>Sandbox</code> milik <code>sandbox-extractors</code> Fase 7 — supervisor itu dirancang untuk pengekstrak <code>Extractor</code> (berbentuk teks), sedangkan audio menghasilkan <code>AudioAttributes</code> terstruktur. Crate audio menyertakan <code>TimeBudgetSupervisor</code> sendiri dengan anggaran bawaan 5 detik yang sama; kontrak pembatalan kooperatifnya identik (load <code>Acquire</code> pada atomik pembatalan per paket). Isolasi subproses untuk berkas audio yang benar-benar jahat termasuk dalam evaluasi Fase 13 yang sama yang mencakup jalur decode PDF non-kooperatif.","changelog.1eeff18b7504":"<strong>[semua platform]</strong> Pengekstrak dokumen Fase 8 (<code>freally-extractors::extractors</code>) — enam pengekstrak yang dapat dipasang dan didaftarkan ke <code>Pipeline</code> Fase 7, ditambah helper <code>register_all(builder)</code> / <code>default_pipeline()</code> yang menyambungkannya sesuai urutan dispatch. Cakupan: <strong>(1) Teks polos + Markdown</strong> — membaca hingga <code>PLAIN_TEXT_CAP_BYTES = 5 MiB</code>, mendeteksi byte-order mark UTF-8 / UTF-16 LE / UTF-16 BE, mendekode isinya ke UTF-8, dan mendorong teks yang didekode ke sink; pengekstrak ini juga menjadi jalur penampung untuk berkas yang tidak diklaim pengekstrak lain (allow-list ekstensi <code>.txt</code> / <code>.text</code> / <code>.md</code> / <code>.markdown</code> / <code>.mkd</code> / <code>.log</code> / <code>.rst</code> / <code>.adoc</code> / <code>.asciidoc</code> / <code>.rtf</code> ditambah heuristik byte awal <code>looks_like_text</code> yang menoleransi 1 NUL nyasar dan menolak 2 atau lebih). <strong>(2) PDF</strong> — <code>pdf-extract = &quot;0.10&quot;</code> (MIT, pure-Rust, ekosistem pdf-rs) mem-parse dokumen dan menghasilkan teks dengan <code>U+000C</code> di antara halaman sehingga cuplikan pencarian dapat menyebut nomor halaman; PDF terenkripsi / dilindungi kata sandi dimunculkan sebagai <code>ExtractError::Unsupported(...)</code>, masukan yang cacat sebagai <code>ExtractError::Malformed(...)</code>. <strong>(3) Office</strong> — <code>XlsxExtractor</code> memakai <code>calamine = &quot;0.34&quot;</code> (MIT) dan menghasilkan satu baris per sel yang tidak kosong sebagai <code>Sheet1!A1=value</code>; <code>DocxExtractor</code> dan <code>PptxExtractor</code> mem-parse OOXML secara langsung melalui <code>zip = &quot;5&quot;</code> + <code>quick-xml = &quot;0.39&quot;</code> sehingga kami tidak menyertakan dependensi <code>ooxmlsdk-rs</code> (lihat catatan penyimpangan). docx merender judul sebagai Markdown (<code># Title</code>, <code>## Sub</code>, …) dan meratakan tabel sebagai baris <code>| cell | cell |\\n</code>; pptx menelusuri slide dalam urutan numerik dan memberi awalan <code># Slide N: &lt;title&gt;</code> pada masing-masing. <strong>(4) Kode</strong> — runtime <code>tree-sitter = &quot;0.25&quot;</code> + 32 crate tata bahasa yang mencakup Rust, Python, JS, TS/TSX, Go, Java, C, C++, C#, Ruby, Bash, Lua, PHP, Kotlin, Scala, Swift, Haskell, OCaml, Elixir, Erlang, Clojure, Elm, Dart, R, Julia, Zig, Nix, TOML, YAML, JSON, HTML, CSS, SQL. Setiap parse menghasilkan bagian <code>[lang]</code> / <code>[identifiers]</code> / <code>[strings]</code> / <code>[comments]</code>; identifier dihapus duplikatnya, string + komentar mempertahankan bentuk literalnya sehingga <code>content:&quot;hello world&quot;</code> cocok dengan sumber aslinya. Pemeriksaan pembatalan kooperatif dipicu setiap <code>CANCEL_CHECK_EVERY = 1024</code> node sehingga supervisor dapat menyela penelusuran pohon yang panjang. <strong>(5) Intip arsip</strong> — <code>zip = &quot;5&quot;</code> + <code>sevenz-rust2 = &quot;0.21&quot;</code> + <code>tar = &quot;0.4&quot;</code> mengenumerasi entri tanpa mengekstrak byte ke disk; bentuk keluarannya adalah <code>archive.zip!path/to/inner.txt size=1234</code> per entri (daemon menyerahkan path virtual ini ke pengindeks sehingga pencarian <code>inner.txt</code> mencocokkan isi arsip). Batas keras <code>MAX_ENTRIES = 100_000</code> per arsip; tar berisi 1M berkas tidak akan menghabiskan sink dan anggaran waktu. <strong>(6) Data terstruktur</strong> — <code>serde_json</code> (workspace) + <code>csv = &quot;1&quot;</code> + <code>serde_yaml_ng = &quot;0.10&quot;</code> diratakan menjadi baris <code>key=value</code>: JSON / YAML memakai kunci bertitik (<code>address.zip=10001</code>) dengan <code>[idx]</code> untuk array; CSV menghasilkan <code>header=value</code> per baris non-header, dan beralih ke <code>col0=value</code> saat header tidak ada; YAML multi-dokumen memberi awalan <code>[doc=N]</code> pada setiap dokumen. Smoke test <code>tests/smoke/phase_08_doc_extractors.rs</code> (16 kasus) mencakup registrasi <code>default_pipeline()</code>, urutan dispatch (xlsx menang atas archive-peek untuk <code>.xlsx</code>; archive-peek menang untuk <code>.zip</code> biasa; PDF menang lewat magic <code>%PDF-</code>; teks polos menangkap <code>.log</code>), penghapusan BOM teks polos, perataan JSON / CSV / YAML, daftar zip dengan path virtual, konversi gaya Heading docx → Markdown, urutan slide pptx, dan penangkapan identifier / string / komentar oleh pengekstrak kode. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>pdf-extract = &quot;0.10&quot;</code> (MIT), <code>calamine = &quot;0.34&quot;</code> (MIT/Apache-2.0), <code>zip = &quot;5&quot;</code> (MIT), <code>quick-xml = &quot;0.39&quot;</code> (MIT), <code>sevenz-rust2 = &quot;0.21&quot;</code> (Apache-2.0), <code>tar = &quot;0.4&quot;</code> (MIT/Apache-2.0), <code>csv = &quot;1&quot;</code> (Unlicense/MIT), <code>serde_yaml_ng = &quot;0.10&quot;</code> (MIT/Apache-2.0), <code>tree-sitter = &quot;0.25&quot;</code> (MIT) ditambah 32 crate tata bahasa yang tercantum di atas (campuran MIT/Apache-2.0 — lisensi setiap tata bahasa ada di allow-list deny.toml).","changelog.eeeac6857769":"<strong>Penyimpangan dari Build-Guide.</strong> Dua dependensi yang disebut diganti agar CI 3 OS tetap hijau dan jadwal 18 lokal tetap sesuai rencana:","changelog.56e5dde6f237":"<strong>Intip arsip:</strong> Build Guide menyebut <code>compress-tools</code> (libarchive). libarchive adalah pustaka sistem — host CI Windows tidak menyertakannya dan orkestrasi <code>vcpkg</code> akan memblokir fase ini. Kami memakai trio pure-Rust (<code>zip</code> + <code>sevenz-rust2</code> + <code>tar</code>); hasilnya adalah keluaran path virtual <code>archive.ext!entry size=N</code> yang sama seperti yang diminta Build Guide, tanpa dependensi sistem.","changelog.bd47ec1aa5f2":"<strong>Office:</strong> Build Guide menyebut <code>ooxmlsdk-rs</code> untuk docx + pptx. Crate itu tidak lagi dipelihara di crates.io per 2026-Q1 dan tidak mendukung Rust 2024. Office Open XML adalah zip + XML, sehingga kami membacanya langsung dengan <code>zip</code> + <code>quick-xml</code>. Dampak bersihnya: permukaan serangan yang lebih kecil (pengindeks hanya membaca <em>teks</em>, bukan gaya / tata letak / objek tertanam) dan satu dependensi terpatok berkurang. Dua catatan lagi: <strong>Dockerfile</strong> belum memiliki tata bahasa di dalam tree karena satu-satunya <code>tree-sitter-dockerfile</code> yang dipublikasikan (0.2.0) masih terikat ke runtime tree-sitter 0.20, yang bertentangan dengan runtime 0.25 kami melalui aturan <code>links = &quot;tree-sitter&quot;</code> milik cargo; untuk sementara Dockerfile ditangani pengekstrak teks polos dan kami akan meninjaunya kembali saat tata bahasanya di-rebase. <strong>Kerja sama PDF</strong> berlaku untuk seluruh dokumen, bukan per halaman, karena <code>pdf-extract</code> memblokir selama parsing — PDF berat yang melampaui anggaran waktu sandbox dihentikan dengan membocorkan thread pekerja (kontrak terdokumentasi sandbox untuk pengekstrak non-kooperatif); isolasi subproses adalah evaluasi Fase 13.","changelog.9aec97cffe7b":"<strong>[semua platform]</strong> Framework pengekstrak format Fase 7 (<code>freally-extractors</code>) — trait, dispatcher, sandbox per ekstraksi, antrean ekstraksi terbatas, penyimpanan blob beralamat konten, dan mode per pengekstrak (Malas / Segera / Dinonaktifkan). Permukaan publik sesuai prompt Fase 7 dalam Build Guide: <code>pub trait Extractor: Send + Sync { fn id(&amp;self) -&gt; ExtractorId; fn matches(&amp;self, path: &amp;Path, magic: &amp;[u8]) -&gt; bool; fn extract(&amp;self, path: &amp;Path, sink: &amp;mut TextSink) -&gt; Result&lt;ExtractionStats, ExtractError&gt;; }</code>. <code>Pipeline::builder().register(...).build()</code> adalah langkah registrasi saat kompilasi; <code>Pipeline::dispatch_path(path)</code> membaca hingga <code>MAGIC_HEAD_BYTES = 32</code> dari awal berkas kandidat dan menelusuri pengekstrak terdaftar sesuai urutan registrasi, melewati pengekstrak yang <code>ExtractorMode</code> efektifnya <code>Disabled</code>; <code>Pipeline::replace_settings</code> memungkinkan daemon menukar pengaturan secara langsung tanpa restart. Metode trait <code>Extractor::extract</code> menerima <code>&amp;mut TextSink</code> (penulis byte terbatas dengan flag pembatalan sandbox yang disalurkan melalui <code>is_cancelled()</code>); penulisan yang melewati batas teks per ekstraksi mengembalikan <code>SinkOverflow</code>, yang dilipat pengekstrak menjadi <code>ExtractError::OutputTooLarge</code>. <code>Sandbox::execute(Arc&lt;dyn Extractor&gt;, PathBuf)</code> menjalankan thread pekerja yang memanggil pengekstrak, dengan thread pemanggil bertindak sebagai supervisor — <code>mpsc::sync_channel::recv_timeout</code> melakukan polling per tick (bawaan 100 ms), memberlakukan anggaran waktu 5 detik dengan membalik flag pembatalan lalu menunggu satu jendela tenggang pembatalan (bawaan 250 ms) sebelum mengembalikan <code>SandboxError::TimeBudget</code> terlepas dari apakah pekerja sudah berhenti (pengekstrak non-kooperatif membocorkan satu thread pekerja per pelanggaran — kontrak yang didokumentasikan; Fase 13 mengevaluasi isolasi subproses untuk format pihak ketiga yang jahat); penjaga RSS membaca baris <code>VmRSS:</code> dari <code>/proc/self/status</code> di Linux, <code>GetProcessMemoryInfo</code> di Windows, dan tidak melakukan apa pun di macOS / Unix lain (prompt Fase 7: &quot;no-op (macOS — andalkan anggaran waktu)&quot;). Pengekstrak kooperatif memeriksa <code>sink.is_cancelled()</code> di antara unit kerja utama dan memunculkan <code>ExtractError::Cancelled</code>; sandbox melipatnya kembali menjadi <code>SandboxError::TimeBudget</code> atau <code>SandboxError::MemoryCeiling</code> berdasarkan alasan pelanggaran yang dilacaknya. <code>ExtractionQueue</code> adalah <code>BinaryHeap&lt;Entry&gt;</code> terbatas yang diberi kunci <code>(mtime_ns desc, FIFO seq)</code> sehingga berkas yang baru disentuh di-dispatch lebih dulu dan entri dengan mtime sama dikeluarkan sesuai urutan penyisipan; <code>try_push</code> memunculkan <code>QueueError::Full(capacity)</code> begitu heap mencapai kapasitas dan <code>QueueError::Closed</code> setelah <code>close()</code>, mencerminkan postur keamanan penutupan <code>EventQueue</code> Fase 4 (<code>closed</code> berada di dalam <code>Mutex</code> yang sama dengan heap sehingga <code>close()</code> yang berjalan bersamaan tidak dapat berlomba dengan pemeriksaan &quot;apakah heap kosong?&quot; milik penunggu). <code>BlobStore::open(&lt;index_root&gt;/extracted)</code> mewujudkan root-nya; <code>put(content)</code> menghitung <code>BlobId = blake3(content)</code> (32 B → 64 karakter hex), meng-encode konten dengan zstd (bawaan level 3 — pass kinerja Fase 13 mengevaluasi penurunan ke level 1 jika kompresi mendominasi waktu ekstraksi), dan menulis secara atomik melalui tmp+rename di dalam direktori shard yang sama ke <code>&lt;root&gt;/&lt;first2hex&gt;/&lt;full-hex&gt;</code>; <code>get(id)</code> me-mmap frame terkompresi melalui <code>memmap2::Mmap</code> dan mengembalikan <code>Vec&lt;u8&gt;</code> yang sudah didekompresi; <code>for_each(|id|)</code> menelusuri penyimpanan yang hidup, melewati sisa parsial <code>.tmp-*</code> dan nama berkas non-hex pada tingkat log <code>warn</code>. Dedup idempoten pada <code>put</code> bersifat implisit dan beralamat konten; <code>BlobStoreStats</code> (<code>puts</code> / <code>dedup_hits</code> / <code>get_hits</code> / <code>get_misses</code> / <code>bytes_written</code> / <code>bytes_decompressed</code>) mengisi panel status daemon. <code>ExtractorMode::{Eager, Lazy, Disabled}</code> berbawaan <code>Lazy</code> (indeks yang baru di-bootstrap tidak membakar CPU untuk ekstraksi konten sebelum pengguna menunjukkan minat pada pencarian konten); <code>PipelineSettings</code> membawa bawaan global ditambah <code>HashMap&lt;String, ExtractorMode&gt;</code> berisi override per pengekstrak (diberi kunci <code>ExtractorId::as_str()</code> sehingga berkas JSON tetap stabil antarkenaikan versi crate), anggaran waktu / memori / batas sink, dan kapasitas antrean. Pengaturan melakukan round-trip melalui <code>serde_json</code> dengan bersih — dialog pengaturan Fase 12 akan memiliki format berkas JSON-nya. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>zstd = &quot;0.13&quot;</code> (BSD-3-Clause; sudah ditarik lewat Tantivy, dideklarasikan langsung di sini untuk jalur kompresi/dekompresi blob store), <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0; sudah ditarik lewat <code>freally-index</code>, dideklarasikan langsung di sini untuk pembacaan mmap blob store), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0; primitif pengalamatan konten yang sama yang sudah dipakai Fase 4 + Fase 6), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0; sama dengan primitif lock di seluruh workspace), <code>serde_json = workspace</code> (MIT/Apache-2.0; serialisasi pengaturan), <code>windows-sys = &quot;0.59&quot;</code> dengan fitur <code>Win32_System_ProcessStatus</code> + <code>Win32_System_Threading</code> di Windows untuk <code>GetProcessMemoryInfo</code>, dan <code>libc = &quot;0.2&quot;</code> di Linux + macOS (parsing hanya-baca <code>/proc/self/status</code> di Linux; sekadar keberadaan di macOS untuk hook RSS di masa depan). Smoke test <code>tests/smoke/phase_07_extractor_fw.rs</code> (17 kasus) mencakup dispatch Pipeline (ekstensi + magic + kecocokan-pertama-menang + yang-dinonaktifkan-dilewati + pembacaan magic berkas pendek), Sandbox (anggaran waktu kooperatif dipicu dalam anggaran+tenggang + galat pengekstrak diteruskan + jalur sukses), Queue (prioritas + back-pressure + close membuka blokir pop yang memblokir), BlobStore (round-trip + dedup + tata letak + persistensi + round-trip hex), dan round-trip JSON Settings.","changelog.d64d1c8e1432":"<strong>[semua platform]</strong> Lensa kemiripan nama berkas Fase 6 (<code>freally-similarity</code>) — indeks near-duplicate nama berkas berbasis MinHash bigram + LSH 16×8. <code>SimilarityIndex::open(dir)</code> membuka atau membuat <code>minhash.idx</code> yang berakar di direktori yang diberikan; <code>upsert(file_id, name)</code> mengubah masukan menjadi huruf kecil, membuang ekstensi di akhir, menghitung tanda tangan MinHash <code>[u64; 128]</code> melalui keluarga hash linear yang deterministik (pasangan <code>(a, b)</code> yang di-seed SplitMix64, dengan <code>MINHASH_SEED = 0x534F5552_43455252</code> yang tetap), dan menyisipkan baris itu ke 16 pita LSH yang masing-masing berisi 8 hash; <code>remove(file_id)</code> memberi tombstone pada baris dan membuangnya dari setiap pita sehingga posting pita yang basi tidak dapat memunculkan hit yang sudah di-tombstone. <code>apply(&amp;[JournalEvent])</code> mengonsumsi event Create / Rename / Delete (Modify dan AttrChange tidak berpengaruh karena nama berkas tidak berubah) dan menurunkan ulang <code>file_id</code> melalui pemotongan <code>blake3(OsStr-bytes)[..8]</code> yang sama dengan yang dipakai <code>freally-index</code>, sehingga <code>SimilarityHit::file_id</code> dapat ditelusuri kembali melalui <code>Index::store::get_many</code> dengan bersih. <code>candidates(query, &amp;SimilarityOpts)</code> menjalankan pencarian LSH, memberi skor setiap kandidat melalui estimasi Jaccard, membuang hit di bawah ambang (bawaan <code>DEFAULT_JACCARD_THRESHOLD = 0.30</code>), mengurutkan berdasarkan Jaccard menurun dengan seri <code>file_id</code> dipecahkan secara menaik demi keluaran yang deterministik, dan memotong hingga <code>candidate_cap</code>. <code>flush()</code> menulis ulang <code>minhash.idx</code> secara atomik melalui tmp-rename — <code>[Header — 32 B] [Heap] [Rows: file_id u64 + name_off u32 + name_len u32 + signature [u64; 128]]</code> — magic <code>SRC-MNHS</code>, versi 1; <code>open()</code> membangun ulang peta pita dari tanda tangan setiap baris yang hidup sehingga format berkas di disk tetap ringkas (catatan pass kinerja Fase 13: simpan peta pita secara langsung saat SA-IS hadir). DSL kueri (<code>freally-query</code>) kini mem-parse <code>similar:&lt;needle&gt;</code> menjadi varian baru <code>ModifierKind::Similar(String)</code> — dipindahkan dari himpunan <code>Reserved</code> Fase 5; needle kosong (<code>similar:</code>) menghasilkan galat <code>ParseError::InvalidModifierValue</code>. Titik masuk baru <code>execute_with(idx, similarity, q, opts)</code> mengalirkan kueri apa pun yang membawa pengubah <code>Similar</code> tingkat atas melalui <code>SimilarityIndex</code> yang diberikan (kandidat LSH → hydration SQLite → filter predikat sisa → pengurutan Jaccard menurun kecuali pengguna secara eksplisit memilih <code>SortSpec</code> non-bawaan); <code>execute(idx, q, opts)</code> lama kini menjadi pembungkus tipis di sekitar <code>execute_with(idx, None, …)</code> yang mengembalikan <code>QueryError::SimilarityIndexUnavailable</code> bertipe saat kueri <code>similar:</code> sampai ke sana, sehingga pemanggil melihat pesan yang jelas alih-alih hasil kosong. <code>similar:</code> yang terkubur di dalam <code>OR</code> / <code>NOT</code> / AND bersarang memunculkan <code>QueryError::UnsupportedSimilarPosition</code> — Fase 6 merilis potongan pertama yang hanya mendukung tingkat atas, yang diangkat oleh pass optimizer Fase 10. Varian baru <code>SortField::Relevance</code> mengurutkan berdasarkan Jaccard menurun saat kueri kemiripan berlaku dan kembali ke urutan <code>Name</code> untuk kueri non-kemiripan (sesuai semantik &quot;Sort by Relevance&quot; milik Everything dari voidtools; UI Fase 11 menampilkan opsi ini). Tanda tangan nama berkas dihitung pada <em>stem</em> (ekstensi dibuang) sehingga pengguna yang mengetik <code>similar:report-final</code> mencocokkan <code>report-final.pdf</code> yang terindeks dengan bersih tanpa penalti 4-5 bigram untuk <code>.pdf</code> di akhir; nama lengkap dalam huruf kecil tetap disimpan di heap untuk diagnostik. Gerbang spesifikasi Fase 6: korpus sintetis 5 000 nama (seed SplitMix64 yang deterministik) dengan 50 near-duplicate yang diketahui (penambahan akhiran <code>-v2</code> + penambahan tag <code>-draft</code> + penghapusan 1 karakter yang dijauhkan dari lutut LSH pada Jaccard ≈ 0.73) mencapai batas bawah recall 95 % dari spesifikasi (<code>crates/freally-similarity/tests/recall.rs</code>); smoke <code>tests/smoke/phase_06_similarity.rs</code> mencakup invarian parse/route/compose/persist/posisi galat. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>blake3 = &quot;1&quot;</code> (sudah ditarik lewat <code>freally-index</code>; dideklarasikan langsung di sini untuk penurunan file_id); rantai <code>parking_lot</code> / <code>thiserror</code> / <code>tracing</code> / <code>freally-journal</code> yang sudah ada.","changelog.1b0bc0f992e4":"<strong>[semua platform]</strong> Kerangka Fase 0: workspace Cargo; shell UI Tauri 2 + Svelte 5 berukuran 1100×720 bertema gelap; stub <code>.ftl</code> untuk 18 lokal; <code>xtask</code> (<code>i18n-lint</code>, <code>third-party-notices</code>, <code>icon-build</code>, <code>release</code>); CI GitHub Actions 3 OS; kebijakan lisensi <code>deny.toml</code> (AGPL dilarang keras); keluarga ikon kaca pembesar biru muda. Tag publik pertama akan menjadi <strong>v0.19.84</strong>.","changelog.24697757938e":"<strong>[khusus Windows]</strong> Subscriber journal USN NTFS Fase 1 (<code>freally-journal-win</code>): <code>JournalSubscriber::open</code> mengkueri journal melalui <code>FSCTL_QUERY_USN_JOURNAL</code>, <code>bootstrap()</code> mengenumerasi MFT melalui <code>FSCTL_ENUM_USN_DATA</code>, <code>subscribe()</code> mengalirkan event inkremental melalui <code>FSCTL_READ_USN_JOURNAL</code>, dan kursor per volume (serial volume + ID journal + USN berikutnya) disimpan di bawah <code>%LOCALAPPDATA%\\Freally\\cursors\\&lt;serial&gt;.json</code> dengan penyimpanan atomik berbasis rename. Flag alasan dipetakan ke <code>JournalEvent::{Create, Modify, Delete, Rename, AttrChange}</code>. Akan diimbangi oleh subscriber FSEvents macOS di Fase 2 dan subscriber inotify/fanotify Linux di Fase 3.","changelog.b71505a013b6":"<strong>[khusus Windows]</strong> Penyambungan Service Control Manager untuk <code>freally-indexd</code>: subperintah <code>install</code> / <code>uninstall</code> / <code>service</code> mendaftarkan dan menjalankan Windows Service <code>Freally-Indexd</code> (mulai otomatis, menerima perintah stop dari SCM). Fase 4 mengisi subscriber per volume + inti indeks di dalam badan service.","changelog.cc1fb2dcf2b9":"<strong>[khusus macOS]</strong> Subscriber journal FSEvents Fase 2 (<code>freally-journal-mac</code>): <code>JournalSubscriber::open</code> me-resolve root pantauan absolut, menangkap <code>stat.st_dev</code> + <code>statfs.f_fstypename</code>-nya, dan memuat (atau membuat saat pertama dijalankan) kursor per pantauan di bawah <code>~/Library/Application Support/Freally/cursors/&lt;root_hash&gt;.json</code>. <code>bootstrap()</code> menelusuri tree dan memancarkan event sintetis <code>JournalEvent::Create</code>. <code>subscribe()</code> menjalankan thread CFRunLoop khusus yang menjalankan <code>FSEventStreamCreate(latency=0.5s, FileEvents | NoDefer | UseCFTypes | WatchRoot)</code>, mengklasifikasikan bitmask flag setiap batch melalui tabel flag FSEvents → <code>JournalEvent</code>, melakukan <strong>pemasangan rename per batch</strong> (mencocokkan kedua bagian pasangan <code>ItemRenamed</code> berdasarkan inode), memindai ulang subtree secara inline pada <code>MustScanSubDirs</code>, dan menyimpan <code>last_event_id</code> untuk melanjutkan setelah restart. Pasangan rename lintas batch turun derajat menjadi <code>Delete + Create</code> (catatan pass kinerja Fase 13). Dependensi runtime <code>core-foundation = &quot;0.10&quot;</code>, <code>core-foundation-sys = &quot;0.8&quot;</code>, <code>fsevent-sys = &quot;4&quot;</code>, <code>libc = &quot;0.2&quot;</code> — semuanya MIT/Apache-2.0, masuk allowlist deny.toml.","changelog.4fcde431e77b":"<strong>[khusus macOS]</strong> Penyambungan agen launchd untuk <code>freally-indexd</code>: subperintah <code>install</code> / <code>uninstall</code> / <code>service</code> mendaftarkan dan menjalankan agen launchd per pengguna di <code>~/Library/LaunchAgents/io.mikeweaver.freally.indexd.plist</code> dengan <code>RunAtLoad=true</code> + <code>KeepAlive=true</code>. Fase 4 mengisi subscriber per root + inti indeks di dalam badan agen. Mode latar depan <code>run --root &lt;path&gt;</code> mencetak event FSEvents ke stdout untuk pemeriksaan manual / smoke test.","changelog.051c4dd1753a":"<strong>[semua platform]</strong> Facade <code>freally-journal</code> kini mengekspor ulang <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> kanonis dari <code>freally-journal-mac</code> pada <code>cfg(target_os = &quot;macos&quot;)</code>. Linux masih memakai permukaan bertipe tetapi berupa stub; Fase 3 akan menggantinya.","changelog.8b1b0978d0a2":"<strong>[khusus Linux]</strong> Subscriber journal inotify+fanotify Fase 3 (<code>freally-journal-lin</code>): <code>JournalSubscriber::open</code> me-resolve root pantauan absolut, menangkap <code>stat.st_dev</code> + nama yang dipetakan dari magic number <code>statfs.f_type</code> (ext4/btrfs/zfs/xfs/f2fs/tmpfs/...), mendeteksi <code>CAP_SYS_ADMIN</code> melalui baris <code>CapEff:</code> di <code>/proc/self/status</code>, dan memuat (atau membuat saat pertama dijalankan) kursor per pantauan di bawah <code>~/.local/share/freally/cursors/&lt;root_hash&gt;.json</code> (memperhatikan XDG_DATA_HOME). <code>bootstrap()</code> menelusuri tree melalui <code>getdents64(2)</code> mentah (lebih cepat daripada <code>read_dir</code> pada tree raksasa) dengan penjaga siklus <code>(st_dev, st_ino)</code> dan memancarkan event sintetis <code>JournalEvent::Create</code>. <code>subscribe()</code> menjalankan thread khusus yang menjalankan backend yang dipilih: <strong>inotify</strong> (bawaan, tanpa hak istimewa) — <code>inotify_add_watch</code> rekursif yang mencakup create/modify/close-write/delete/move/attr, dengan <code>IN_Q_OVERFLOW</code> memicu pemindaian ulang <code>getdents64</code> atas seluruh tree; atau <strong>fanotify</strong> (memerlukan CAP_SYS_ADMIN) — satu <code>fanotify_mark(FAN_MARK_FILESYSTEM)</code> dengan <code>FAN_REPORT_DFID_NAME</code> sehingga pelacakan rename bertahan melintasi subvolume Btrfs dan overlayfs yang tidak dapat direproduksi inotify. Pengklasifikasi mask inotify mencerminkan prioritas alasan USN Fase 1 (<code>Delete &gt; Create</code>, <code>Rename &gt; Create</code>, <code>IN_CLOSE_WRITE</code> menetapkan <code>Modify</code>). Pemasangan rename per batch melalui cookie inotify / rekaman info <code>OLD_DFID_NAME</code> fanotify; pemisahan lintas batch turun derajat menjadi <code>Delete + Create</code> (catatan pass kinerja Fase 13). <code>EPERM/EINVAL/ENOSYS</code> fanotify saat inisialisasi beralih ke inotify sehingga kernel &lt; 5.17 (tanpa <code>FAN_REPORT_DFID_NAME</code>) dan build <code>CONFIG_FANOTIFY=n</code> tetap berfungsi. Dependensi runtime hanya <code>libc = &quot;0.2&quot;</code> — jalur syscall mentah murni.","changelog.f558e7c13bef":"<strong>[khusus Linux]</strong> Penyambungan unit systemd-user untuk <code>freally-indexd</code>: subperintah <code>install</code> / <code>uninstall</code> / <code>service</code> menulis <code>~/.config/systemd/user/freally-indexd.service</code> dengan <code>Type=simple</code> + <code>Restart=always</code> + <code>WantedBy=default.target</code> (sesuai spesifikasi Fase 3) dan menjalankan <code>systemctl --user enable --now</code>. <code>ExecStart</code> mengutip path biner sehingga instalasi <code>--binary &quot;/path with spaces/freally-indexd&quot;</code> tetap selamat melewati parser unit systemd yang peka spasi. Fase 4 mengisi subscriber per root + inti indeks di dalam badan service. Mode latar depan <code>run --root &lt;path&gt;</code> mencetak event inotify/fanotify ke stdout untuk pemeriksaan manual / smoke test.","changelog.c891685c91b5":"<strong>[khusus Linux]</strong> Kebijakan Polkit di <code>crates/freally-indexd/polkit/io.mikeweaver.freally.policy</code> yang mendeklarasikan aksi <code>io.mikeweaver.freally.elevate</code> untuk alur peningkatan fanotify yang opsional. <code>auth_self_keep</code> (≈5 menit) meminta kata sandi pengguna aktif itu sendiri; anotasi <code>org.freedesktop.policykit.exec.path</code> + <code>argv1</code> mengunci <code>/usr/local/bin/freally-indexd elevate</code> sehingga ID aksi tidak dapat dipakai ulang untuk biner lain. Pengelola distribusi menyertakan berkas ini di <code>/usr/share/polkit-1/actions/</code>.","changelog.5ce16f33ef5f":"<strong>[semua platform]</strong> Facade <code>freally-journal</code> kini mengekspor ulang <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> / <code>WatchCursor</code> kanonis dari <code>freally-journal-lin</code> pada <code>cfg(target_os = &quot;linux&quot;)</code>. Target Unix lain (FreeBSD, OpenBSD, illumos) tetap memakai permukaan <code>portable_stub</code> yang bertipe tetapi berupa stub.","changelog.369e1b7b5e7f":"Diperbaiki (putaran review Fase 8)","changelog.600f17cedae8":"<strong>[semua platform]</strong> Pengekstrak teks polos Fase 8 kini mendeteksi encoding <em>sebelum</em> pemotongan kelebihan batas dijalankan. Versi sebelumnya tanpa syarat menjalankan pemangkasan <code>from_utf8</code>-dalam-loop pada buffer yang terpotong terlepas dari encoding-nya — untuk masukan UTF-16 yang melebihi batas 5 MiB (≈ 2.5 M codepoint), loop itu membuang byte sampai menemukan prefiks berbentuk UTF-8, sering kali menyisakan buffer dengan panjang byte ganjil, yang kemudian ditolak <code>decode</code> sebagai <code>ExtractError::Malformed</code>. Dengan pemotongan yang sadar encoding, UTF-16 dipangkas ke batas byte genap dan UTF-8 dipangkas ke batas codepoint melalui helper baru <code>trim_to_utf8_boundary</code>. Regresi baru <code>utf16_le_overshoot_truncates_at_even_boundary_not_malformed</code> mengunci kontrak ini.","changelog.29036e7ef80a":"<strong>[semua platform]</strong> Pengekstrak intip arsip + data terstruktur Fase 8 kini membersihkan karakter kontrol pemisah baris (<code>\\n</code> / <code>\\r</code> / <code>\\0</code>) dalam nama entri arsip, nilai bidang CSV, dan nilai string skalar JSON / YAML melalui helper baru <code>extractors::util::sanitize_inline</code>. Sebelumnya, entri zip / 7z / tar yang jahat dapat mendeklarasikan nama yang memuat <code>\\n</code> dan menyuntikkan baris palsu ke blob pencarian (satu entri menyamar sebagai banyak entri); bug yang sama ada di permukaan skalar CSV / JSON / YAML, tempat bidang berkutip secara sah dapat memuat baris baru. Keluaran yang sudah dibersihkan mempertahankan recall pencarian dengan meng-escape byte tersebut (<code>\\\\n</code> / <code>\\\\r</code> / <code>\\\\0</code>) alih-alih membuangnya. Regresi baru <code>entry_name_with_newline_is_sanitized</code> (arsip), <code>csv_field_with_newline_is_sanitized</code>, dan <code>json_string_value_with_newline_is_sanitized</code> mencakup kontrak tersebut di setiap permukaan.","changelog.85af001a0e9a":"<strong>[semua platform]</strong> Parser docx + pptx Fase 8 kini memeriksa <code>sink.is_cancelled()</code> berdasarkan anggaran per event alih-alih per paragraf (docx) / hanya per slide (pptx). Docx jahat dengan satu <code>&lt;w:p&gt;</code> raksasa (ribuan run <code>&lt;w:t&gt;</code> yang disambung) dulu menghabiskan beberapa detik di dalam <code>parse_docx_body</code> tanpa memberi kesempatan pada flag pembatalan; parser XML slide milik pptx sama sekali tidak memiliki pemeriksaan pembatalan di dalam. Perbaikannya menghitung setiap event quick-xml dan menguji flag itu dengan anggaran 32 event — load-nya sendiri hanya satu atomik <code>Ordering::Relaxed</code>, biayanya di bawah satu nanodetik. Jendela tenggang sandbox Fase 7 tetap menjadi jaring pengaman untuk kasus terburuk, tetapi penghentian kooperatif kini dipicu dengan anggaran terbatas apa pun bentuk XML masukannya.","changelog.85445058bd37":"<strong>[semua platform]</strong> Pengekstrak docx Fase 8 kini menekan paragraf bergaya judul tetapi tanpa teks. Versi sebelumnya memancarkan <code># \\n\\n</code> polos (atau tingkat hash yang lebih dalam) ke blob pencarian untuk blok <code>&lt;w:p&gt;</code> kosong yang membawa <code>&lt;w:pStyle w:val=&quot;HeadingN&quot;/&gt;</code>; token hilir seperti <code>#</code> hanyalah gangguan yang menghabiskan batas sink tanpa manfaat recall. Regresi baru <code>docx_skips_empty_heading_paragraphs</code> mencakupnya.","changelog.1dad52d35905":"<strong>[semua platform]</strong> Pengekstrak kode + teks polos Fase 8 kini memangkas buffer kelebihan batas ke batas codepoint UTF-8 dalam O(1) melalui backtrack byte lanjutan <code>trim_to_utf8_boundary</code> bersama, menggantikan loop <code>while !std::str::from_utf8(&amp;buf).is_ok() { buf.pop(); }</code> sebelumnya yang memindai ulang seluruh buffer 4 / 5 MiB untuk setiap pop (kasus terburuk O(N²)). Enam unit test di <code>extractors::util::tests</code> menjaga kasus codepoint lengkap, codepoint parsial, batas ASCII, semua-byte-lanjutan, dan buffer kosong dari regresi.","changelog.4e47265991ba":"<strong>[semua platform]</strong> Tabel docx Fase 8 (<code>&lt;w:tbl&gt;</code> / <code>&lt;w:tr&gt;</code> / <code>&lt;w:tc&gt;</code>) kini memiliki cakupan tes eksplisit. <code>parse_docx_body</code> sudah menangani tag tabel tetapi tidak ada tes yang menjalankan jalur itu; regresi di sana akan diam-diam menghilangkan isi tabel dari recall pencarian pada setiap docx yang memiliki tabel. <code>docx_renders_tables_as_pipe_rows</code> yang baru mengunci render <code>| cell | cell |</code>.","changelog.f8937347b501":"<strong>[semua platform]</strong> YAML multi-dokumen Fase 8 (pemisah <code>---</code>) kini memiliki cakupan tes eksplisit. Jalur <code>flatten_yaml</code> menghasilkan kunci berawalan <code>[doc=N]</code> tetapi tidak ada tes yang mencakup logika awalan itu; <code>flattens_multi_document_yaml_with_doc_prefix</code> yang baru memastikan refaktor di masa depan tidak dapat diam-diam meruntuhkan batas dokumen.","changelog.585aef173030":"Diperbaiki (putaran review Fase 5)","changelog.0aa74d3eaa36":"<strong>[semua platform]</strong> Parser kueri Fase 5 kini memperlakukan <code>!</code> setelah <code>)</code> sebagai prefiks NOT — <code>(a)!b</code> di-parse sebagai <code>(a) AND !b</code> agar sesuai dengan perilaku voidtools-Everything yang terdokumentasi. Sebelumnya pemeriksaan batas byte-dan-token melewatkan <code>RParen</code>, sehingga <code>!b</code> di akhir runtuh menjadi satu literal <code>!b</code> dan negasinya dibuang secara diam-diam (regresi Aturan Tetap #8). Tes parser baru <code>bang_after_rparen_is_not</code> mengunci kontrak ini.","changelog.7a304dd66705":"<strong>[semua platform]</strong> Cache rencana Fase 5 tidak lagi memutasi rencana yang di-cache saat <code>match_mode.match_path</code> aktif. Pengosongan seed yang memungkinkan pencarian path melewati pra-filter trigram kini hanya berjalan saat eksekusi — <code>ExecPlan</code> tetap menjadi fungsi murni dari string kueri, sehingga dua pemanggil bersamaan dengan kueri yang sama tetapi pengaturan <code>match_path</code> berbeda tidak lagi dapat meracuni rencana yang di-cache satu sama lain. Tes wiring baru <code>plan_cache_survives_match_path_toggle</code> mencakupnya.","changelog.fa995dcc342d":"<strong>[semua platform]</strong> <code>parse_iso_day</code> Fase 5 menolak hari yang mustahil secara kalender (30 Feb, 31 Apr, 29 Feb pada tahun non-kabisat, …) sejak awal melalui validator baru <code>days_in_month</code> (aritmetika epoch-day Howard Hinnant menerima hari 1-31 untuk bulan apa pun, dan diam-diam menggulirkan kelebihannya ke depan). Voidtools menolak tanggal-tanggal ini — regresi Aturan Tetap #8. Tes parser baru <code>invalid_calendar_days_reject</code> mencakup kasus tahun kabisat + akhir bulan.","changelog.a94bbcf610a6":"<strong>[semua platform]</strong> Daftar cadangan pengubah Fase 5 diperluas untuk mencakup token kebiasaan pengguna voidtools-Everything (<code>wfn:</code>, <code>wholefilename:</code>, <code>case:</code>, <code>count:</code>, <code>dupe:</code>, <code>nodiacritics:</code>) sehingga pengguna yang mengetiknya mendapat <code>QueryError::UnsupportedModifier</code> bertipe saat eksekusi alih-alih galat parse. Ter-parse-tetapi-gagal-dengan-jelas adalah kontrak Aturan Tetap #8 sampai masing-masing sakelar itu dirilis bersama fase pemilik lensanya. Tes parser baru <code>voidtools_reserved_toggles_parse</code> mencakup keluarga ini.","changelog.6543bc5ccebd":"<strong>[semua platform]</strong> <code>eval_full</code> Fase 5 kini mengubah path kandidat menjadi huruf kecil sekali per baris saat <code>match_path</code> aktif, alih-alih mengulanginya untuk setiap node anak AND / OR — string path huruf kecil diangkat ke <code>NameEvaluator::matches_full</code> dan diteruskan melalui <code>eval_full</code> sebagai <code>Option&lt;&amp;str&gt;</code>. Ini menghapus alokasi <code>to_lowercase()</code> per anak AND yang membesar seiring kedalaman kueri.","changelog.cd2b5074233d":"<strong>[semua platform]</strong> <code>eval_modifier::Reserved</code> Fase 5 kini menjalankan <code>debug_assert!</code> saat tercapai — <code>validate_supported</code> adalah gerbang terdokumentasi di bagian atas <code>execute()</code>, dan pengubah Reserved yang mencapai evaluasi berarti ada pemanggil yang membangun AST <code>Query</code> secara manual dan melewati gerbang itu. Cabang <code>false</code> diam-diam sebelumnya adalah kode mati pada jalur panggilan yang didukung dan kini gagal dengan jelas di bawah <code>cfg(debug_assertions)</code>.","changelog.dc40e0e57b5d":"<strong>[semua platform]</strong> Lensa nama berkas Fase 5 (<code>freally-query</code>) — parser + eksekutor DSL berbentuk voidtools-Everything di atas indeks Fase 4. <code>parse(s)</code> membangun AST <code>Query</code> yang mencakup istilah substring literal / wildcard (<code>*</code>, <code>?</code>) / regex (prefiks <code>regex:</code>), perekat boolean (<code>AND</code> / <code>OR</code> / <code>NOT</code> / prefiks <code>!</code>, AND implisit di antara atom yang bersebelahan, grup dalam tanda kurung), dan predikat pengubah: <code>size:</code> (dengan <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>=</code>, satuan <code>b</code>/<code>kb</code>/<code>mb</code>/<code>gb</code>/<code>tb</code>), <code>date:</code> (alias relatif <code>today</code> / <code>yesterday</code> / <code>thisweek</code> / <code>lastweek</code> / <code>thismonth</code> / <code>lastmonth</code> / <code>thisyear</code> / <code>lastyear</code> ditambah <code>YYYY-MM-DD</code> absolut dengan pembanding), <code>ext:</code> (tunggal atau daftar dipisah <code>;</code>, <code>.</code> dibuang), <code>attrib:</code> (himpunan huruf Windows <code>R</code>/<code>H</code>/<code>S</code>/<code>A</code>/<code>D</code>/<code>C</code>/<code>E</code>/<code>T</code>/<code>O</code>/<code>L</code>), <code>path:</code> / <code>parent:</code> / <code>child:</code> (pencocok substring; alias <code>name:</code> / <code>folder:</code> dipatuhi). Alias filter cepat <code>audio:</code> / <code>video:</code> / <code>image:</code> / <code>document:</code> / <code>executable:</code> / <code>archive:</code> diperluas menjadi himpunan ekstensi yang sudah ditentukan. Pengubah lensa masa depan (<code>content:</code> / <code>lufs:</code> / <code>codec:</code> / <code>channels:</code> / <code>samplerate:</code> / <code>length:</code> / <code>similar:</code> / <code>duration:</code> / <code>type:</code> / <code>lang:</code>) dapat di-parse tetapi dijaga oleh <code>validate_supported</code>, yang memunculkan <code>QueryError::UnsupportedModifier</code> sampai fase pemiliknya dirilis. <code>execute(idx, query, ExecOpts)</code> merencanakan kueri (substring literal terpanjang menjadi seed trigram; OR memecah seed menjadi pemindaian baris hidup), menarik kandidat dari indeks nama kustom melalui API byte pinjaman baru <code>for_each_candidate_named</code> / <code>for_each_live</code>, menjalankan predikat sisi nama, melakukan hydration pada yang lolos melalui pengambilan batch klausa IN <code>Store::get_many</code> yang baru, mengevaluasi predikat rekaman penuh, menerapkan <code>SortSpec</code> (nama / path / ukuran / tanggal / tipe / ekst, menaik/menurun), dan mengalirkan hasil melalui <code>ResultSet::first_batch</code> / <code>collect</code>. Sakelar <code>MatchMode</code> (<code>match_case</code> / <code>whole_word</code> / <code>match_path</code> / <code>match_diacritics</code>) diterapkan berlapis saat eksekusi; <code>match_path</code> memperluas target pencarian ke path lengkap yang dikanonisasi dengan melewati pra-filter indeks nama (catatan pass kinerja Fase 13); <code>match_diacritics: false</code> membuang tanda gabung melalui NFKD sebelum perbandingan substring. <code>PlanCache</code> LRU 16 entri (<code>PlanCache::default16</code>) diberi kunci string kueri yang sudah dipangkas dan memakai ulang AST + rencana yang sudah di-parse saat pengetikan ulang yang sering. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>regex = &quot;1&quot;</code> (MIT/Apache-2.0), <code>unicode-normalization = &quot;0.1&quot;</code> (MIT/Apache-2.0). <code>name_index</code> di <code>crates/freally-index</code> mengganti irisan trigram-nya dari <code>BTreeSet</code> ke penggabungan dua-pointer atas posting terurut (catatan PERF Build-Guide §<code>name_index</code>) dan menyediakan <code>name_bytes</code> / <code>for_each_candidate_named</code> / <code>for_each_live</code> untuk lensa; <code>Store::get_many</code> memotong 250 ID per klausa IN agar tetap di bawah <code>SQLITE_MAX_VARIABLE_NUMBER</code> milik SQLite. <code>xtask gen-fixture</code> menyintesis aliran rekaman berkas SplitMix64 yang deterministik untuk benchmark kinerja Fase 5 (<code>cargo bench -p freally-query --bench filename_lens</code>); benchmark itu mencetak P50 / P99 per skenario dengan penanda FAIL dan hanya keluar dengan kode bukan nol saat <code>FREALLY_BENCH_GATE=1</code>. Fixture <code>tests/voidtools_compat.rs</code> mengunci 50 kueri Everything sungguhan — gerbang regresi Aturan Tetap #8; <code>tests/wiring.rs</code> mencakup eksekutor dari ujung ke ujung terhadap indeks berbasis <code>tempfile</code>; <code>tests/smoke/phase_05_filename_lens.rs</code> adalah smoke agnostik OS yang berjalan di setiap entri matriks CI.","changelog.0af41265e3fd":"<strong>[semua platform]</strong> Inti indeks Fase 4 (<code>freally-index</code>) — façade agnostik OS yang mengonsumsi enum <code>JournalEvent</code> bersama dan mengorkestrasi tiga penyimpanan persisten: indeks Tantivy (<code>index.tantivy/</code>) untuk pencarian teks penuh + berfaset, <code>files.db</code> SQLite kanonis dalam mode WAL + <code>synchronous=NORMAL</code> sebagai baris kebenaran <code>FileRecord</code> yang tahan lama, dan indeks nama kustom berbasis mmap (<code>name.idx</code> heap string terkemas + posting terbalik trigram; <code>name.suf</code> suffix array leksikografis) untuk menghasilkan kandidat substring. <code>Index::open(root)</code> mewujudkan pohon direktori, membuka atau membuat setiap penyimpanan, dan merekonsiliasi penyimpangan dengan memutar ulang penyimpanan kanonis ke indeks nama saat jumlah barisnya tidak cocok. <code>Index::apply(&amp;[JournalEvent])</code> memproses event Create / Modify / Delete / Rename / AttrChange melalui hapus-lalu-tambah Tantivy + upsert SQLite + upsert/hapus indeks nama dengan <code>file_id = blake3(path)[0..8]</code> sebagai kunci yang stabil. <code>Index::commit()</code> mem-flush Tantivy, menulis ulang <code>name.idx</code> + <code>name.suf</code> secara atomik melalui tmp-rename, melakukan checkpoint WAL SQLite ke DB utama, dan menyimpan <code>manifest.json</code> dengan <code>tantivy_generation</code> yang dinaikkan ditambah kursor per volume yang dicatat melalui <code>Index::record_cursor</code>. <code>EventQueue</code> terbatas (kapasitas bawaan 10 000 — spesifikasi Build-Guide) memunculkan back-pressure sebagai <code>IndexError::QueueFull</code> alih-alih diam-diam membuang event; <code>push_blocking</code> mematuhi semantik penutupan yang sama. Root indeks bawaan per OS (<code>%LOCALAPPDATA%\\Freally\\index</code> / <code>~/Library/Application Support/Freally/index</code> / <code>${XDG_DATA_HOME:-~/.local/share}/freally/index</code>) melalui <code>default_index_root()</code>. Dependensi runtime baru (semuanya permisif, masuk allowlist deny.toml): <code>tantivy = &quot;0.26&quot;</code> (MIT), <code>rusqlite = &quot;0.37&quot;</code> dengan fitur <code>bundled</code> (MIT) — menarik <code>libsqlite3-sys</code> + SQLite yang dibundel (domain publik, masuk allow-list di bawah <code>Unlicense</code>), <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0). Smoke test <code>tests/smoke/phase_04_index.rs</code> mencakup tata letak direktori, round-trip event penuh, pemulihan kill-9 dari SQLite, persistensi kursor manifest, back-pressure antrean, dan dedup hapus-lalu-tambah Tantivy.","changelog.8167310c5eff":"<strong>[semua platform]</strong> Facade <code>freally-journal</code> kini mengekspor ulang <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> kanonis dari subscriber Windows pada <code>cfg(windows)</code>, subscriber macOS pada <code>cfg(target_os = &quot;macos&quot;)</code>, dan subscriber Linux pada <code>cfg(target_os = &quot;linux&quot;)</code>. Target Unix lain tetap memakai permukaan <code>portable_stub</code> yang bertipe tetapi berupa stub.","changelog.f11a02c6c5f1":"<strong>[macOS + Linux]</strong> Flag <code>--root &lt;path&gt;</code> pada subperintah <code>Run</code> milik <code>freally-indexd</code> (yang diutamakan di macOS / Linux) kini juga menggerakkan subscriber journal Linux; <code>--volume</code> yang sudah ada tetap berfungsi sebagai sinonim di setiap OS.","changelog.6897dd8bf8f4":"Diperbaiki (putaran review Fase 4)","changelog.2ed95ca28b12":"<strong>[semua platform]</strong> <code>Index::apply</code> Fase 4 kini menurunkan <code>JournalEvent::Rename</code> yang <code>old_path</code>-nya tidak pernah diindeks (pasangan rename lintas batch yang tidak dapat dipasangkan subscriber journal) menjadi <code>Delete(old) + synthetic Create(new)</code> alih-alih menulis baris Tantivy / indeks nama tanpa baris kebenaran <code>files.db</code>. Mencerminkan kontrak cadangan lintas batch yang dipublikasikan subscriber journal; smoke baru <code>rename_of_unknown_path_degrades_to_delete_plus_create</code> mencakupnya.","changelog.85d4a5272278":"<strong>[semua platform]</strong> <code>EventQueue::close</code> Fase 4 tidak lagi berlomba dengan <code>wait_for_events</code> / <code>push_blocking</code> — <code>closed</code> kini disimpan di dalam <code>Mutex</code> yang sama dengan antrean itu sendiri alih-alih <code>Mutex</code> saudara, sehingga <code>notify_all</code> milik <code>close()</code> tidak dapat jatuh di antara pemeriksaan &quot;apakah antrean kosong?&quot; milik penunggu dan <code>Condvar::wait</code>-nya. Smoke baru <code>close_unblocks_push_blocking_and_wait_for_events</code> dan <code>try_push_after_close_refuses</code> mengunci kontrak ini.","changelog.8096900614c3":"<strong>[semua platform]</strong> <code>Manifest::load_or_default</code> Fase 4 kini memperlakukan galat parse JSON sebagai hilang-dan-peringatkan alih-alih <code>IndexError::Manifest</code> keras yang akan memblokir <code>Index::open</code>. Penyimpanan kanonis SQLite dan <code>meta.json</code> Tantivy adalah catatan yang tahan lama; manifest adalah cache per commit yang ditulis ulang <code>Index::commit</code> pada setiap siklus. Smoke baru <code>torn_manifest_does_not_block_open</code> mencakupnya.","changelog.0f06a85ae4d4":"<strong>[semua platform]</strong> <code>derive_file_id</code> Fase 4 kini meng-hash <code>OsStr::as_encoded_bytes()</code> secara langsung alih-alih <code>to_string_lossy()</code> sehingga path yang hanya berbeda pada byte UTF-8 tidak valid tidak runtuh menjadi ID yang sama. Dampak di dunia nyata jarang (nama berkas Linux ext4 / Btrfs adalah urutan byte sembarang) tetapi perbaikan ini menghapus satu kelas tabrakan diam-diam sebelum Fase 5 mulai bergantung pada <code>file_id</code> sebagai hash yang stabil.","changelog.4f8d098583e4":"<strong>[khusus Windows]</strong> Pemasangan rename journal USN pada <code>freally-journal-win</code> Fase 1 kini mengklasifikasikan bagian nama-LAMA dari sebuah rename (dan rekaman <code>FILE_DELETE</code> apa pun) sebagai <strong>terminal</strong>: langsung dipancarkan tanpa mensyaratkan <code>USN_REASON_CLOSE</code>. NTFS tidak memancarkan rekaman penutup untuk sesi nama lama — tidak ada lagi yang perlu ditunggu di path itu. Sebelumnya pengklasifikasi mengembalikan <code>Pending</code> untuk rekaman <code>RENAME_OLD_NAME</code> yang tidak memiliki <code>CLOSE</code>, tabel pemasangan tetap kosong, dan rekaman <code>RENAME_NEW_NAME | CLOSE</code> yang sepadan dibuang diam-diam melalui <code>?</code>. Dampak bersihnya: <code>JournalEvent::Rename</code> tidak pernah dipancarkan untuk rename apa pun di dalam tree. Uji ulang diagnostik pada volume NTFS sungguhan mengonfirmasi perbaikannya; tes integrasi <code>realtime_create_modify_rename_delete_round_trip</code> kini lulus dari ujung ke ujung dan tidak lagi diberi <code>#[ignore]</code>.","changelog.6924516bf9eb":"<strong>[khusus Windows]</strong> <code>JournalEvent::Delete</code> kini merujuk tabel pemasangan rename berdasarkan FRN sebelum beralih ke hasil <code>build_path</code> milik rekaman. Windows modern memakai penghapusan <code>NtSetInformationFile</code> bersemantik POSIX yang secara internal mengganti nama berkas menjadi nama sementara <code>$.dF{guid}</code> sebelum mengeluarkan <code>FILE_DELETE</code>; tanpa pencarian ini konsumen akan melihat <code>Delete $.dF{guid}</code> alih-alih <code>Delete &lt;original_path&gt;</code>. Defensif: tes yang mengungkap bug rename melihat perilaku <code>DeleteFile</code> klasik di sini, tetapi jalur POSIX dapat terpicu dalam skenario berkas terkunci / lintas proses.","changelog.6b2e8f83dd8e":"Usang","changelog.43e7d9ac5463":"_(kosong)_"};
